window.CASES = [{"id":"rolex","title":"Il Rolex del notaio","place":"Masseria Ruggiero, Valle d'Itria","teaser":"Settant'anni, trenta invitati, un orologio sparito dal comodino.","intro":"Il notaio Ruggiero festeggia i settant'anni nella sua masseria. A fine cena si accorge che il suo Rolex d'epoca, 40.000 euro, non è più sul comodino della camera al piano di sopra. Nessuno ha lasciato la festa. I sospetti del notaio sono tre, e ti ha chiamato perché la polizia, dice lui, «fa troppe domande e guarda troppo poco».","details":[{"id":"d1","label":"La finestra della camera","text":"Aperta. Sul davanzale polvere e polline gialli, intatti.","insight":"Davanzale della camera coperto di polvere e polline, senza un segno."},{"id":"d2","label":"Il cassetto del comodino","text":"La scatola dell'orologio è stata rimessa nel cassetto, chiusa con cura.","insight":"La scatola vuota del Rolex è stata richiusa e rimessa al suo posto nel cassetto."},{"id":"d3","label":"Il prato","text":"L'irrigazione automatica è partita alle 21:30. Il prato tra la casa e il parcheggio è fradicio.","insight":"Il prato tra la casa e il parcheggio è fradicio dalle 21:30."},{"id":"d4","label":"Il telefono di Davide","text":"Lasciato sul tavolo, schermo acceso. Una notifica di un'app di scommesse: «Saldo insufficiente». Sotto, un messaggio di «Ile ♥» delle 21:28: «Sopra tra cinque minuti».","insight":"Sul telefono di Davide: «Saldo insufficiente» da un'app di scommesse, e un messaggio di «Ile» alle 21:28: «Sopra tra cinque minuti»."},{"id":"d5","label":"Il parcheggio","text":"Tre mezzi degli ospiti: la moto di Davide, la Panda bianca di Ilenia, una berlina grigio scuro di Franco Lattanzi.","insight":"Nel parcheggio: moto di Davide, Panda bianca di Ilenia, berlina grigio scuro di Franco."},{"id":"d6","label":"Il bagno di sotto","text":"Cartello scritto a mano: «Guasto, usate quello di sopra».","insight":"Il bagno di sotto è guasto: stasera per il bagno si sale al piano di sopra."},{"id":"d7","label":"La foto sul mobile","text":"Bianco e nero, 1979. Il notaio giovane a un tavolo da gioco con un altro uomo. Didascalia: «Con Vito Lattanzi, Circolo Unione». Al polso di Vito, lo stesso Rolex.","insight":"Foto del 1979: al polso di Vito Lattanzi, al tavolo da gioco col notaio, lo stesso Rolex."}],"suspects":[{"id":"davide","name":"Davide Ruggiero","role":"Nipote, 28 anni","look":"Gamba che batte sotto il tavolo, telefono sempre in mano.","tell":"La gamba batte sotto il tavolo senza sosta. Quando il telefono vibra lo gira a faccia in giù. Si parla di soldi e lui guarda il piatto; si parla di Ilenia e lui guarda la porta della cucina.","questions":[{"id":"a1","q":"Dov'era durante la cena?","a":"A tavola. Sono salito una volta verso le nove, il bagno di sotto è rotto. Come tutti.","insight":"Davide dice di essere salito al piano di sopra una volta sola, verso le 21."},{"id":"a2","q":"Il suo telefono dice che ha debiti di gioco.","req":["d4"],"a":"Ottomila euro. Sì. Ma lo zio me li presta, me l'ha detto stasera. Perché dovrei rubargli un orologio?","insight":"Davide ha 8.000 € di debiti di gioco. Dice che stasera lo zio gli ha promesso il prestito.","lie":true},{"id":"a3","q":"Cosa sa dell'orologio?","a":"Che lo zio non se lo toglie mai. Stasera l'ha lasciato di sopra perché il cinturino gli stringeva. Lo sapevano tutti, l'ha detto a tavola."}]},{"id":"ilenia","name":"Ilenia Carone","role":"Cameriera di sala, 23 anni","look":"Composta, professionale. Serve dalla cucina da inizio serata.","tell":"Mani dietro la schiena, postura da sala. Quando nomini Davide guarda verso di lui, poi subito verso la cucina. Due volte si tocca la tasca del grembiule, come per controllare che ci sia ancora qualcosa.","questions":[{"id":"i1","q":"È salita al piano di sopra stasera?","a":"Una volta, alle 21:15, per portare un bicchiere d'acqua al notaio per la pillola. L'orologio era sul comodino, l'ho visto io.","insight":"Ilenia dice di essere salita una volta, alle 21:15. L'orologio era sul comodino."},{"id":"i2","q":"Che rapporto ha con Davide?","a":"È il nipote del notaio. Lo servo come servo gli altri. Perché?","aside":"Si liscia il grembiule con tutte e due le mani.","insight":"Ilenia dice che Davide per lei è un ospite come gli altri.","lie":true},{"id":"i3","q":"Dalla cucina si vede il parcheggio. Ha notato qualcosa?","a":"Verso le dieci meno un quarto si è accesa la luce dentro una macchina scura. Ho pensato che qualcuno stesse andando via. Poi la luce si è spenta e non è partito nessuno.","insight":"Verso le 21:45 si è accesa e poi spenta la luce interna di un'auto scura nel parcheggio. Nessuno è partito."}]},{"id":"franco","name":"Franco Lattanzi","role":"Socio dello studio, 66 anni","look":"Elegante, giacca di lino, scarpe di camoscio. Calmo.","tell":"Gambe accavallate, voce bassa e regolare. Sulla punta delle scarpe di camoscio ci sono aloni più scuri. Quando si parla del parcheggio si aggiusta il polsino sinistro, due volte.","questions":[{"id":"f1","q":"Si è mosso dalla tavola durante la cena?","a":"Una volta sola, per il bagno di sopra. Fuori non sono uscito, se è questo che mi chiede.","insight":"Franco dice di essere salito una volta al bagno e di non essere mai uscito di casa."},{"id":"f2","q":"Da quanto conosce il notaio?","a":"Quarant'anni. Prima di essere il mio socio era amico di mio padre. Giocavano a carte insieme, al circolo. (Poi, senza che tu lo chieda.) Stasera, al dolce, l'ho sentito dire a Davide: «Neanche un euro, finché giochi.»","insight":"Franco dice di aver sentito il notaio, al dolce, dire a Davide: «Neanche un euro, finché giochi»."},{"id":"f3","q":"Nella foto del '79 suo padre porta lo stesso Rolex. Come mai?","req":["d7"],"a":"(Un silenzio lungo.) Mio padre l'ha perso a carte con lui. Una sera sola. Tutto quello che aveva al polso. Non ne ha mai più parlato, fino alla morte.","insight":"Nel 1979 Vito Lattanzi, padre di Franco, ha perso quel Rolex a carte con il notaio.","lie":true},{"id":"f4","q":"Il prato è bagnato dalle 21:30 e le sue scarpe hanno aloni d'acqua. Dov'è andato?","req":["d3","t_franco"],"a":"Sarò passato sull'erba mentre fumavo in terrazza.","aside":"Guarda la terrazza dalla finestra. Non aggiunge altro.","insight":"Franco dice di essersi bagnato le scarpe fumando in terrazza. La terrazza è lastricata e non tocca il prato.","lie":true}]}],"bluff":{"text":"Annunci ad alta voce che nel cinturino c'è un localizzatore e che tra dieci minuti sapremo dov'è l'orologio.","reactions":{"davide":"Si alza di scatto: «Meglio, così la smettete di guardare me.» Poi si risiede e cerca Ilenia con gli occhi.","ilenia":"Le scivola un bicchiere dal vassoio. Lo raccoglie senza alzare lo sguardo.","franco":"Tira fuori un sigaro e lo rigira tra le dita, spento. Chiede se il segnale passa anche al chiuso."},"insight":"Al bluff del localizzatore: Davide cerca Ilenia con gli occhi, a Ilenia cade un bicchiere, Franco chiede se il segnale passa al chiuso."},"motive":{"options":["Pagare i debiti di gioco dopo il no dello zio.","Riprendersi l'orologio che suo padre aveva perso a carte.","Rivenderlo e lasciare il lavoro per stare con Davide.","Vendicarsi di un socio che voleva chiudere lo studio."],"correct":1},"culprit":"franco","key":["f4","i3","t_franco","x1"],"solution":"Franco è salito «al bagno» e ha preso l'orologio dal comodino, rimettendo la scatola nel cassetto come chi conosce la casa. Alle 21:45 ha attraversato il prato appena irrigato per nasconderlo nella sua berlina: Ilenia ha visto la luce interna accendersi, il camoscio delle sue scarpe si è macchiato. Il movente sta nella foto del 1979: quell'orologio suo padre l'aveva perso a carte proprio con il notaio. Franco non l'ha rubato. Secondo lui se l'è ripreso. Davide aveva nascosto il no dello zio per vergogna, e Ilenia la loro storia: alle 21:33 si sono visti cinque minuti nel corridoio di sopra, per questo tutti e due hanno taciuto.","contradictions":[{"id":"x1","a":"f1","b":"i3","who":"franco","reply":"Va bene, sono uscito un momento. A prendere le sigarette in macchina.","aside":"Dal taschino della giacca gli spunta un sigaro.","insight":"Franco ammette di essere andato alla sua auto verso le 21:45, dopo aver detto di non essere mai uscito.","lie":true},{"id":"x2","a":"i2","b":"d4","who":"ilenia","reply":"(Abbassa la voce.) Stiamo insieme da due mesi. Alle nove e mezza ci siamo visti cinque minuti nel corridoio di sopra. Se il notaio lo scopre, domani non lavoro più.","aside":"Guarda la porta della cucina.","insight":"Ilenia ammette di frequentare Davide e di averlo incontrato al piano di sopra verso le 21:30.","lie":true},{"id":"x3","a":"a2","b":"f2","who":"davide","reply":"Va bene. Mi ha detto di no, davanti a tutti. Non volevo sembrare quello che ha un motivo.","aside":"Gira il telefono a faccia in giù.","insight":"Davide ammette che al dolce lo zio gli ha negato il prestito.","lie":true}]},{"id":"reliquiario","title":"Il braccio d'argento","place":"Chiesa di San Fortunato, centro storico di Lecce","teaser":"Domani la processione. Stanotte il santo ha perso il braccio.","intro":"Da trecento anni, la mattina di San Fortunato, il reliquiario d'argento con l'osso del braccio del santo esce in processione per le vie di Lecce. Stamattina alle sei il sacrestano ha trovato la teca vuota e una finestra laterale in frantumi. La processione è tra dieci ore e la città vuole un colpevole entro pranzo. Il parroco ti ha chiamato perché, dice, «qui le voci corrono più veloci dei carabinieri».","details":[{"id":"d1","label":"La finestra laterale","text":"Vetro colorato in frantumi. I pezzi sono quasi tutti fuori, sul marciapiede. Dentro, solo qualche scheggia.","insight":"Finestra laterale rotta: i vetri sono quasi tutti fuori, sul marciapiede. Dentro, poche schegge."},{"id":"d2","label":"La teca","text":"Cristallo e bronzo, intatta. La piccola serratura è aperta, senza un graffio.","insight":"Teca intatta. La serratura è aperta, senza un graffio."},{"id":"d3","label":"La centralina dell'allarme","text":"Registro: disinserito alle 23:10 con il codice della confraternita, reinserito alle 23:24. Nessun allarme per la finestra.","insight":"Allarme disinserito alle 23:10 col codice della confraternita, reinserito alle 23:24. La finestra non ha fatto scattare niente."},{"id":"d4","label":"La bacheca della confraternita","text":"Un avviso della Curia: «Lunedì 14, inventario e perizia degli argenti sacri. Presenti il priore e un perito orafo.»","insight":"Lunedì 14 la Curia fa inventario e perizia degli argenti, con il priore e un perito orafo."},{"id":"d5","label":"La giacca del priore","text":"Appesa in sagrestia, sotto l'abito della confraternita. Nella tasca interna, una lettera della banca aperta e riaperta: «Ultimo avviso prima del pignoramento dell'immobile di via Palmieri».","insight":"Nella giacca del priore, in sagrestia: ultimo avviso della banca prima del pignoramento del negozio di via Palmieri."},{"id":"d6","label":"Il mazzo del sacrestano","text":"Sul chiodo accanto alla porta della sagrestia: tutte le chiavi della chiesa, compresa quella piccola della teca. Etichetta: «Rocco».","insight":"Il mazzo di Rocco, con la chiave della teca, sta appeso a un chiodo in sagrestia, in vista."},{"id":"d7","label":"Le foto delle processioni","text":"Due foto incorniciate in sagrestia. Tre anni fa il reliquiario è opaco, quasi nero nelle pieghe. L'anno scorso brilla come appena uscito dal negozio.","insight":"Nelle foto: tre anni fa il reliquiario era scuro nelle pieghe. L'anno scorso brillava come nuovo."}],"suspects":[{"id":"rocco","name":"Rocco Negro","role":"Sacrestano, 60 anni","look":"Mani da muratore, giacca della banda sulla spalla. È il primo che tutti guardano.","tell":"Risponde a tutto, anche a quello che non chiedi. Quando qualcuno bisbiglia alle sue spalle si gira di scatto. Due volte si tocca la tasca della giacca della banda, dove tintinnano delle monete.","questions":[{"id":"r1","q":"In giro dicono che lei ha già rubato.","a":"Vent'anni fa. Rame dai tetti, a Galatina. Ho fatto il mio e ho pagato. Don Pietro mi ha preso lo stesso, e da allora qui dentro non è sparito nemmeno un cero.","insight":"Rocco ha un precedente per furto di vent'anni fa. Dice che da allora in chiesa non è sparito niente.","lie":true},{"id":"r2","q":"La chiave della teca è sul suo mazzo.","req":["d6"],"a":"Da trent'anni, su quel chiodo. Ma stanotte ero in piazza con la banda, prova generale, dalle dieci a mezzanotte e mezza. Suono il bombardino. Il maestro fa l'appello e c'erano trecento persone a guardare.","insight":"Rocco dice di essere stato alla prova della banda dalle 22 alle 00:30, davanti a trecento persone."},{"id":"r3","q":"Chi conosce il codice dell'allarme?","a":"Io ho quello della parrocchia. Quello della confraternita ce l'hanno il priore e la restauratrice, che la sera lavorava nel laboratorio dietro l'altare. La chiave della teca, invece: io e il priore. Basta.","insight":"Il codice della confraternita: il priore e Chiara. La chiave della teca: Rocco e il priore."},{"id":"r4","q":"Alla prova, ha visto qualcuno della chiesa?","a":"La restauratrice. Verso le undici meno un quarto, dietro il palco, a parlare col maestro. Vicini vicini. Poi non l'ho più vista.","insight":"Rocco dice di aver visto Chiara in piazza verso le 22:45, dietro il palco, col maestro della banda. Poi più niente."}]},{"id":"ennio","name":"Ennio Carlà","role":"Priore della confraternita, 63 anni","look":"Abito scuro, medaglione della confraternita al collo, capelli pettinati con cura. Gira il cappello tra le mani.","tell":"Parla del furto con parole da comunicato: «gesto sacrilego», «comunità ferita». Gira il cappello senza sosta, tranne quando nomini la Curia: lì si ferma. Due volte si passa un dito nel colletto.","questions":[{"id":"e1","q":"Quando ha lasciato la chiesa?","a":"Alle nove, dopo la vestizione della statua. Ho chiuso io il portone. Poi a casa, a letto: stamattina mi alzavo alle cinque.","insight":"Il priore dice di essere andato a casa alle 21 e di non essere più uscito."},{"id":"e2","q":"Mi parli del reliquiario.","a":"Argento massiccio, Seicento napoletano. Due chili e cento. Un tesoro. L'ho fatto periziare io, tre anni fa.","insight":"Il priore dice che il reliquiario è d'argento massiccio, periziato tre anni fa."},{"id":"e3","q":"In tasca ha un avviso di pignoramento.","req":["d5"],"a":"Il negozio è chiuso da due anni. Lo sanno tutti. Che c'entra con il santo?","aside":"Rimette la lettera nella giacca, piegata in quattro.","insight":"Il priore dice che dei suoi debiti «lo sanno tutti». La lettera la tiene in sagrestia, non a casa.","lie":true},{"id":"e4","q":"Dall'anno scorso il reliquiario non annerisce più. Come mai?","req":["d7"],"a":"L'avranno lucidato meglio. Chieda alla restauratrice, l'ha avuto lei in laboratorio.","aside":"Risponde senza alzare gli occhi dal cappello.","insight":"Sul reliquiario che non annerisce, il priore rimanda a Chiara e al suo laboratorio."}]},{"id":"chiara","name":"Chiara Montinaro","role":"Restauratrice, 36 anni","look":"Mani macchiate di pasta per argento, occhiali sulla testa. Seduta sul gradino dell'altare, fissa la teca vuota.","tell":"Si strofina il pollice sui polpastrelli, il gesto di chi lucida. Guarda a lungo la teca vuota, poi espira forte e abbassa le spalle. Quando parla il priore trattiene il fiato. Quando si nomina la banda, controlla il telefono.","questions":[{"id":"c1","q":"Dov'era stanotte?","a":"Al cinema all'aperto con mia sorella, fino a mezzanotte. Ho ancora il biglietto, lei ha le foto.","insight":"Chiara dice di essere stata al cinema all'aperto con la sorella fino a mezzanotte.","lie":true},{"id":"c2","q":"Lei ha il codice della confraternita.","a":"Sì, per il laboratorio. Ma la teca non l'ho mai aperta: la chiave non ce l'ho. Il reliquiario me l'hanno portato una volta sola, due settimane fa. Me l'ha portato il priore, e se l'è riportato lui.","insight":"Chiara ha il codice dell'allarme, non la chiave della teca. Dice di aver avuto il reliquiario in laboratorio una volta sola, due settimane fa."},{"id":"c3","q":"Perché ha sospirato guardando la teca vuota?","req":["t_chiara"],"a":"(Abbassa la voce.) Perché adesso nessuno lo pesa. Quando l'ho pulito, sotto la base, dove l'argento era consumato, c'era ottone. Placcato. È una copia. L'ho detto al priore dieci giorni fa. Mi ha risposto: ci penso io, dopo la festa. E io sono stata zitta, perché era passato dal mio laboratorio e avrebbero pensato a me.","insight":"Chiara dice che sotto la base il reliquiario è ottone placcato. L'ha detto al priore dieci giorni fa e poi ha taciuto.","lie":true},{"id":"c4","q":"Chi apre la cassetta delle offerte?","a":"Rocco, ogni sera, prima di chiudere. Il sabato don Pietro conta e dice sempre che i fedeli sono diventati tirchi.","insight":"La cassetta delle offerte la apre Rocco ogni sera. Il sabato il parroco trova sempre meno soldi."}]}],"contradictions":[{"id":"x1","a":"e2","b":"c3","who":"ennio","reply":"Me l'ha detto, sì. Non ci ho creduto. È giovane, si sarà sbagliata.","aside":"Il cappello gli si ferma tra le mani.","insight":"Il priore ammette che dieci giorni fa Chiara gli ha detto che il reliquiario era ottone placcato. Non l'ha riferito a nessuno.","lie":true},{"id":"x2","a":"r1","b":"c4","who":"rocco","reply":"(Si svuota la tasca sul banco: monete.) Venti euro a settimana. Per le medicine di mia nipote. Don Pietro non lo sa. Il braccio del santo però no. Quello no.","aside":"Rimette le monete in fila, una per una.","insight":"Rocco ammette di prendere venti euro a settimana dalla cassetta delle offerte.","lie":true},{"id":"x3","a":"c1","b":"r4","who":"chiara","reply":"Va bene. Al cinema non ci sono andata. Ero col maestro della banda, in piazza e poi nella sua macchina. È sposato. Mia sorella mi copre.","aside":"Si toglie gli occhiali dalla testa e li stringe.","insight":"Chiara ammette di non essere stata al cinema: era col maestro della banda, sposato, in piazza e poi in auto. La sorella la copre.","lie":true}],"bluff":{"text":"Annunci che i carabinieri hanno ritrovato il reliquiario in un cassonetto e che il perito della Curia lo pesa oggi stesso, prima della processione.","reactions":{"rocco":"«Grazie, San Fortunato.» Corre verso la porta per chiamare la banda, poi si ferma e si tocca la tasca.","ennio":"«Grazie a Dio.» Si china a raccogliere il cappello, che gli è scivolato di mano.","chiara":"Si alza di scatto: «Pesarlo? Oggi?» Guarda il priore."},"insight":"Al bluff del ritrovamento: Chiara chiede della pesata e guarda il priore, al priore cade il cappello, Rocco si ferma sulla porta."},"motive":{"options":["Far sparire la copia prima che il perito la pesasse.","Pagare le medicine della nipote.","Coprire un danno fatto durante il restauro.","Vendicarsi della Curia che voleva sciogliere la confraternita."],"correct":0},"culprit":"ennio","key":["x1","e3","r3"],"solution":"Il braccio d'argento era sparito un anno fa: sommerso dai debiti, Ennio l'aveva sostituito con una copia placcata e aveva venduto l'originale. Per un anno nessuno se n'è accorto, tranne l'argento, che ha smesso di annerire. Poi Chiara, pulendolo, ha visto l'ottone, e la Curia ha fissato la perizia per lunedì. Alle 23:10 Ennio è rientrato col codice della confraternita, ha aperto la teca con la sua chiave e ha rotto la finestra dall'interno per simulare un furto. Rocco era in piazza con la banda, ma da anni prendeva qualche moneta dalla cassetta delle offerte. Chiara non era al cinema: era col maestro della banda, sposato, e per questo aveva un alibi falso."},{"id":"stangadavanti","title":"L'ultima sosta","place":"Festa di San Rocco, Casamurgia (BA)","teaser":"Dodici uomini sotto il santo. Uno non arriva alla terza sosta.","intro":"A Casamurgia la statua di San Rocco la portano dodici uomini, e il posto davanti si eredita come una casa. Alla terza sosta della processione Vito Lamanna, capo dei portatori, 54 anni, si piega sotto la stanga e non si rialza più. Il medico della festa dice cuore. Sua moglie dice che Vito il cuore ce l'aveva di ferro, e ha chiesto a don Nino, il parroco, di chiamarti.","details":[{"id":"d1","label":"La borraccia di Vito","text":"Metallo, col suo nome inciso. Ancora mezza piena. Il tappo è avvitato storto e l'acqua ha un odore amaro, che il limone non copre.","insight":"Il tappo della borraccia di Vito era avvitato storto. L'acqua rimasta ha un odore amaro."},{"id":"d2","label":"Il registro delle offerte","text":"Il libro del comitato. Offerte appuntate al manto del santo, processione del mattino: dichiarati 3.200 €. A margine, a matita, la grafia di Vito: «Contati io: 5.100. Parlare con N.»","insight":"Vito ha contato 5.100 € di offerte; il comitato ne ha dichiarati 3.200. A margine ha scritto: «Parlare con N.»"},{"id":"d3","label":"Il foglio del medico","text":"Appunti del medico della festa: «Alla seconda sosta V.L. dice di vedere tutto giallo. Nausea. Polso irregolare. Alla terza, arresto.»","insight":"Dopo aver bevuto: vista gialla, nausea, polso irregolare, poi arresto. È il quadro di un eccesso di digitale, un farmaco per il cuore."},{"id":"d4","label":"La foto di gruppo","text":"Sul telefono del parroco, ore 18:02: i portatori in posa davanti alla chiesa, camicie bianche e fasce rosse. Lino c'è, in seconda fila, col fiatone. Del comitato manca il tesoriere, Nicola Dimundo.","insight":"Nella foto delle 18:02 Lino c'è, col fiatone. Nicola, il tesoriere, no."},{"id":"d5","label":"Il cestino della sacrestia","text":"Tra le cartacce, un blister di digossina svuotato, farmaco per il cuore. Le compresse sono state spinte fuori tutte. L'etichetta col nome è stata strappata.","insight":"Nel cestino della sacrestia, dove stavano le borracce: un blister di digossina svuotato, senza nome."},{"id":"d6","label":"Il video della rissa","text":"Gira su tutti i telefoni del paese. Ieri sera, fuori dal bar: Lino Sisto spinge Vito contro un muro. «Sotto la stanga davanti non ci torni vivo.»","insight":"Ieri sera Lino ha spinto Vito contro un muro: «Sotto la stanga davanti non ci torni vivo.»"},{"id":"d7","label":"Le chiavi della sacrestia","text":"Due copie soltanto. Una è del parroco, che la lascia a Dora. L'altra è del tesoriere del comitato feste.","insight":"Le chiavi della sacrestia sono due: una del parroco, che la lascia a Dora, e una del tesoriere."}],"suspects":[{"id":"lino","name":"Lino Sisto","role":"Portatore, 34 anni","look":"Spalle larghe, camicia bianca sudata, la fascia rossa ancora al collo.","tell":"Pugni stretti e mascella dura quando si parla del posto davanti. Quando dici «Vito è morto» gli trema il mento. Controlla il telefono di continuo e lo rimette in tasca a schermo in giù.","questions":[{"id":"l1","q":"Ieri sera ha minacciato Vito davanti al bar.","req":["d6"],"a":"Ho detto una fesseria. Il posto davanti spettava a me, lui l'ha dato a suo figlio. Ma oggi dalle cinque alle sei ero dal barbiere, poi nella foto di gruppo, poi sotto la stanga di sinistra. La sua borraccia non l'ho mai vista.","insight":"Lino dice di essere stato dal barbiere dalle 17 alle 18, poi nella foto, poi alla stanga dal lato opposto a Vito.","lie":true},{"id":"l2","q":"Chi tiene i soldi della festa?","a":"Nicola. Tesoriere da dieci anni. Quest'anno però Vito s'era messo in testa di contare lui. Stamattina l'ha detto davanti a tutti: «Stasera i conti li guardo io.»","insight":"Stamattina Vito ha detto davanti a tutti: «Stasera i conti li guardo io.» Il tesoriere è Nicola."},{"id":"l3","q":"Com'era Vito prima della processione?","a":"Un toro. Ha fatto la scalinata della chiesa di corsa, per sfottere noi giovani. Poi alla seconda sosta ha bevuto dalla borraccia e ha cominciato a sudare freddo.","insight":"Alla seconda sosta Vito ha bevuto dalla sua borraccia e ha cominciato a sudare freddo."}]},{"id":"nicola","name":"Nicola Dimundo","role":"Tesoriere del comitato feste, 47 anni","look":"Camicia bianca stirata, fascia rossa, un mazzo di chiavi alla cintura.","tell":"Ogni volta che qualcuno nomina la sacrestia si tocca il mazzo di chiavi alla cintura. Parla piano e in fretta, e ogni tanto si asciuga le mani sui pantaloni.","questions":[{"id":"n1","q":"Dov'era prima della processione?","a":"In piazza coi portatori, dalle cinque. Ci sono pure nella foto di gruppo, chiedete al parroco.","insight":"Nicola dice di essere stato in piazza dalle 17, e di essere nella foto di gruppo."},{"id":"n2","q":"Vito ha contato 5.100 euro. Lei ne ha dichiarati 3.200.","req":["d2"],"a":"Il povero Vito contava male. Le banconote appuntate al manto si staccano, volano, la gente se le mette in tasca. Succede ogni anno.","aside":"Si asciuga le mani sui pantaloni.","insight":"Secondo Nicola i 1.900 € mancanti sono banconote volate via o finite in tasca alla gente.","lie":true},{"id":"n3","q":"Chi prepara le borracce dei portatori?","a":"Dora, in sacrestia. Acqua e limone, dodici borracce. Poi chiude a chiave. La chiave ce l'ha lei.","aside":"Tocca il mazzo di chiavi alla cintura.","insight":"Secondo Nicola le borracce le prepara Dora in sacrestia, e la chiave ce l'ha lei."},{"id":"n4","q":"In sacrestia c'è un blister di digossina vuoto. E lei la ritira ogni settimana.","req":["d5","o3"],"a":"Per mio padre, che ha il cuore malato. E poi mezzo paese prende quella roba. Pure Dora: chieda a lei cosa tiene nella borsetta.","insight":"Nicola dice che la digossina che ritira è per suo padre. Aggiunge che la prende anche Dora.","lie":true}]},{"id":"dora","name":"Addolorata «Dora» Fiore","role":"Sacrestana, 63 anni","look":"Vestito blu della festa, capelli appena fatti, rosario attorcigliato alle dita, una borsetta stretta sotto il braccio.","tell":"Vestito buono, piega fresca, odore di lacca. Quando dice «non mi sono mossa» si liscia la gonna. Ogni volta che si parla di medicine stringe la borsetta.","questions":[{"id":"o1","q":"Quando ha riempito le borracce?","a":"Alle cinque. Acqua fresca e una fetta di limone, come ha sempre voluto il parroco vecchio. Poi ho chiuso e non mi sono mossa da lì davanti fino alla processione.","insight":"Dora dice di essere rimasta davanti alla sacrestia dalle 17 fino alla processione."},{"id":"o2","q":"Alle cinque non era vestita così. Quando è andata a cambiarsi?","req":["t_dora"],"a":"(Si porta il rosario alla bocca.) Dalle cinque e mezza alle sei e mezza. Sono andata a casa a farmi i capelli, mia nipote me li fa. Mi vergognavo a dirlo. Ho lasciato il santo da solo.","insight":"Dora ammette: dalle 17:30 alle 18:30 era a casa dalla nipote per i capelli. La sacrestia è rimasta chiusa, senza nessuno.","lie":true},{"id":"o3","q":"Conosce bene Nicola?","a":"Come un figlio. Povero, col padre ricoverato a Bari da un mese. Eppure lo vedo ancora in farmacia ogni settimana a ritirare la digossina del padre. Dice che fa scorta.","insight":"Secondo Dora, Nicola ritira ogni settimana la digossina del padre, ricoverato a Bari da un mese."},{"id":"o4","q":"Ha visto qualcuno vicino alla sacrestia, prima della processione?","a":"Lino. Verso le cinque e venti girava dietro la chiesa, dalla parte della porticina. Guardava le finestre. Poi è sparito nel vicolo. Ho pensato che cercasse il bagno.","insight":"Verso le 17:20 Dora ha visto Lino dietro la chiesa, vicino alla porticina della sacrestia."}]}],"bluff":{"text":"Annunci che il tappo della borraccia è già in laboratorio, e che sul metallo le impronte restano per giorni.","reactions":{"lino":"Si pulisce le mani sui pantaloni. «Io quella borraccia non l'ho toccata. Mai.»","nicola":"«Le borracce le ho portate io in piazza, tutte e dodici. Le mie impronte ci sono per forza.»","dora":"«Ci saranno le mie, le ho riempite io!» Si fa il segno della croce."},"insight":"Al bluff delle impronte tutti e tre hanno spiegato, senza che nessuno lo chiedesse, perché le loro mani potevano essere sulle borracce."},"motive":{"options":["Riprendersi il posto davanti sotto la stanga del santo.","Impedire che Vito scoprisse la relazione con sua figlia.","Evitare che Vito, contando le offerte, scoprisse i 1.900 € spariti.","Nascondere di aver lasciato la sacrestia sguarnita per un'ora."],"correct":2},"culprit":"nicola","key":["x1","n4","n2"],"solution":"Nicola rubava dalle offerte appuntate al santo, e Vito se n'era accorto: «Parlare con N.». Stasera avrebbe controllato i conti davanti al comitato. Mentre gli altri posavano per la foto delle 18, Nicola era in sacrestia con la sua chiave, lasciata vuota da Dora che era andata a farsi i capelli. Ha sciolto nella borraccia di Vito la digossina che ritirava per un padre ricoverato. Alla seconda sosta Vito vedeva giallo, alla terza il cuore si è fermato. Lino aveva minacciato Vito e alle cinque non era dal barbiere ma nel vicolo con Rosa, la figlia di Vito, che vedeva di nascosto: la chiave della sacrestia non l'ha mai avuta. Dora ha lasciato il santo per la parrucchiera, e si vergognava a dirlo.","contradictions":[{"id":"x1","a":"n1","b":"d4","who":"nicola","reply":"Sono arrivato dopo, va bene. Ero in sacrestia a contare le offerte del mattino. Da solo.","insight":"Nicola ammette che verso le 18 era da solo in sacrestia, «a contare le offerte del mattino».","lie":true},{"id":"x2","a":"l1","b":"o4","who":"lino","reply":"(Abbassa la voce.) Dal barbiere non c'ero. Ero nel vicolo con Rosa, la figlia di Vito. Ci vediamo di nascosto da un anno. Se Vito lo veniva a sapere, la stanga davanti era l'ultimo dei miei problemi.","aside":"Guarda il telefono. Lo rimette in tasca a schermo in giù.","insight":"Lino ammette che dalle 17:20 alle 18 era nel vicolo dietro la sacrestia, con Rosa, la figlia di Vito, che frequenta di nascosto.","lie":true}]},{"id":"faroscialara","title":"Il faro di Punta Scialara","place":"Faro di Punta Scialara, costa di Vieste","teaser":"Centodiciassette gradini di ghisa. Il guardiano li conosceva a occhi chiusi.","intro":"Onofrio Lauriola, 71 anni, guardiano del faro da quaranta, è stato trovato all'alba in fondo alla scala a chiocciola. Per i carabinieri è scivolato: età, buio, gradini di ferro. Il figlio dice che suo padre quella scala la faceva anche dormendo. Tu guardi le pantofole ai piedi del morto e cominci a dargli ragione.","details":[{"id":"d1","label":"La scala a chiocciola","text":"Onofrio è in pantofole. A metà scala, sui gradini, impronte di sabbia bagnata e un filo d'alga ancora verde.","insight":"A metà scala: impronte di sabbia bagnata e un filo d'alga ancora verde. Onofrio è in pantofole."},{"id":"d2","label":"Il registro del faro","text":"Ultima riga, ore 01:35, grafia tremante: «Di nuovo la barca senza fanali alla Cala del Monaco. Quarta volta. Scendo sul ballatoio a fotografarla col tele.»","insight":"Registro, ore 01:35: barca senza fanali alla Cala del Monaco, «quarta volta». Onofrio scende sul ballatoio a fotografarla col tele."},{"id":"d3","label":"La macchina fotografica","text":"Sul ballatoio, una reflex con l'obiettivo lungo. Lo sportello della scheda è aperto. La scheda non c'è.","insight":"Sul ballatoio, la reflex col tele: sportello della scheda aperto, la scheda non c'è."},{"id":"d4","label":"La lettera del resort","text":"Un'offerta della Scialara Retreat per trasformare il faro in suite di lusso. Sopra, un post-it di Onofrio: «Mai. Sopra il mio cadavere.»","insight":"La Scialara Retreat voleva il faro per farne suite di lusso. Post-it di Onofrio: «Mai. Sopra il mio cadavere.»"},{"id":"d5","label":"La Cala del Monaco","text":"Sulla sabbia, il solco fresco di una chiglia tirata a secco. Tra gli scogli, una martellina con il manico fasciato di cima blu e schegge di roccia bianca appena spaccata.","insight":"Alla Cala del Monaco: solco fresco di una chiglia, una martellina col manico fasciato di cima blu, schegge di roccia bianca appena spaccata."},{"id":"d6","label":"Il telefono di Onofrio","text":"Ultima chiamata in uscita alle 00:50, a «Tonino». Durata tre minuti.","insight":"Ultima chiamata di Onofrio: alle 00:50, a «Tonino». Tre minuti."},{"id":"d7","label":"Il pugno di Onofrio","text":"La mano destra è chiusa. Dentro, un bottone di corno scuro con un filo blu strappato.","insight":"Nel pugno destro di Onofrio: un bottone di corno scuro, con un filo blu strappato."}],"suspects":[{"id":"michele","name":"Michele Frattaruolo","role":"Pescatore, padrone della Santa Rosa","look":"Giaccone da marinaio blu, stivali di gomma, pelle cotta dal sale. È venuto «a vedere», dice.","tell":"Tiene il giaccone chiuso con la mano sinistra, anche se fuori ci sono diciotto gradi. Quando parla guarda il faro, mai la cala. Due volte si passa la lingua sulle labbra screpolate.","questions":[{"id":"m1","q":"Dov'era stanotte?","a":"A letto. Col maestrale che tirava non è uscito nessuno. Chieda al porto.","insight":"Michele dice di non essere uscito stanotte: col maestrale, dice, non è uscito nessuno."},{"id":"m2","q":"Conosceva Onofrio?","a":"Lo conoscevano tutti. Stava sempre col binocolo, a guardare il mare degli altri. Uno così prima o poi qualcosa lo vede.","insight":"Michele su Onofrio: «Stava sempre col binocolo, a guardare il mare degli altri.»"},{"id":"m3","q":"Onofrio stringeva un bottone di corno. Perché tiene il giaccone chiuso con la mano?","req":["d7","t_michele"],"a":"(Toglie la mano. Al secondo occhiello manca il bottone.) L'ho perso settimane fa. Al porto, scaricando le cassette.","aside":"Dall'occhiello pende un filo blu acceso.","insight":"Al giaccone di Michele manca il secondo bottone; dall'occhiello pende un filo blu acceso. Lui dice di averlo perso settimane fa, al porto.","lie":true}]},{"id":"ilaria","name":"Ilaria Notarangelo","role":"Architetta della Scialara Retreat","look":"Tailleur chiaro, cartellina sotto il braccio, occhiali da sole anche all'ombra. È arrivata con un SUV bianco a noleggio.","tell":"Guarda l'orologio ogni due minuti e chiama il faro «l'immobile». Quando le chiedi della notte si toglie gli occhiali, poi se li rimette. Il telefono vibra; lei legge e lo capovolge sul tavolo.","questions":[{"id":"i1","q":"Onofrio aveva scritto: «Sopra il mio cadavere».","req":["d4"],"a":"Una frase da vecchio testardo. Ieri abbiamo litigato in piazza, lo sa mezza Vieste. Ma io gli immobili li compro con gli avvocati, non con le scale.","insight":"Ilaria ha litigato in piazza con Onofrio ieri. Dice: «Gli immobili li compro con gli avvocati, non con le scale.»"},{"id":"i2","q":"Dov'era stanotte?","a":"A cena a Peschici con due assessori, fino all'una e mezza. Poi dritta in albergo. Il portiere di notte mi ha dato la chiave alle due meno un quarto.","insight":"Ilaria dice: cena a Peschici con due assessori fino all'1:30, poi dritta in albergo; chiave dal portiere all'1:45."},{"id":"i3","q":"Conosce Michele Frattaruolo?","a":"Il pescatore? Ieri sera, a cena, il cuoco ci ha offerto dei datteri di mare «fuori menu». Ha detto che glieli porta Michele, di nascosto. Io non li ho toccati: sono vietati, e io con gli assessori ci lavoro.","insight":"Ilaria: a cena il cuoco ha offerto datteri di mare «fuori menu», e ha detto che glieli porta Michele di nascosto."}]},{"id":"tonino","name":"Tonino Lauriola","role":"Figlio di Onofrio, 38 anni","look":"Occhi gonfi, felpa della squadra di calcio del paese. Non si siede.","tell":"La voce si rompe ogni volta che dice «papà». Quando si nomina il resort si gratta il collo e guarda il mare. Ha il telefono in mano e non lo posa mai.","questions":[{"id":"t1","q":"Quando ha sentito suo padre l'ultima volta?","a":"Mi ha chiamato all'una meno dieci. Diceva: stanotte li fotografo, domani chiamo la Capitaneria. Gli ho detto di lasciar perdere, che non erano affari suoi.","insight":"Tonino: all'00:50 il padre gli ha detto «stanotte li fotografo, domani chiamo la Capitaneria»."},{"id":"t2","q":"Dov'era lei stanotte?","a":"In macchina sulla litoranea, tornavo da Mattinata. Verso l'una e mezza ho visto una barca senza luci entrare nella Cala del Monaco. Bianca, con la fascia verde: da queste parti così c'è solo la Santa Rosa, quella di Michele. E al belvedere sopra la cala c'era un SUV chiaro fermo, a fari spenti.","insight":"Tonino: verso l'1:30 una barca bianca con la fascia verde, come la Santa Rosa di Michele, entrava senza luci nella cala. Al belvedere sopra la cala, un SUV chiaro fermo a fari spenti."},{"id":"t3","q":"La società del resort le aveva offerto qualcosa?","req":["d4"],"a":"La gestione del bar. Se papà firmava. Non gliel'ho mai detto. Non me l'avrebbe perdonato.","insight":"Il resort aveva offerto a Tonino la gestione del bar, se il padre firmava. Onofrio non lo sapeva.","lie":true}]}],"bluff":{"text":"Dici che la macchina fotografica caricava le foto da sola su internet, e che la Capitaneria le sta già guardando.","reactions":{"michele":"Si volta verso il mare, verso la cala. Poi chiede, piano, se al buio si riconosce una barca o si vede solo nero.","ilaria":"Chiede se le foto hanno la data e l'ora. Poi riprende il telefono e scrive un messaggio.","tonino":"«Papà? Internet?» Si gratta il collo. «Gliel'ho regalata io quella macchina. Non ha nemmeno il wifi.»"},"insight":"Al bluff delle foto: Michele ha chiesto se al buio si riconosce una barca; Ilaria se le foto hanno data e ora, poi ha scritto a qualcuno."},"culprit":"michele","key":["m3","x1","d7"],"motive":{"options":["Sbloccare la vendita del faro al resort","Prendersi la gestione del bar del resort","Proteggere la pesca di frodo che Onofrio stava fotografando","Non far scoprire l'incontro notturno con l'assessore"],"correct":2},"solution":"Da settimane Onofrio vedeva una barca senza luci alla Cala del Monaco: era la Santa Rosa di Michele, che spaccava gli scogli per cavare datteri di mare e venderli sottobanco ai ristoranti. Stanotte Onofrio la fotografa col tele e Michele vede il riflesso sul ballatoio. Sbarca, sale nel faro lasciando sabbia sui gradini, lotta con il vecchio e lo spinge giù per la scala, poi si prende la scheda. Ma all'una e mezza Tonino aveva già riconosciuto la sua barca dalla litoranea, e nel pugno di Onofrio è rimasto il bottone del suo giaccone. Il resort voleva il faro, e Ilaria all'una e mezza era proprio sopra la cala: ma in macchina al belvedere, con l'assessore Tricarico che doveva restare fuori da tutto, non sulla spiaggia da cui è salita la sabbia. Tonino, invece, taceva solo l'offerta del bar che il resort gli aveva fatto alle spalle del padre.","contradictions":[{"id":"x1","a":"m1","b":"t2","who":"michele","reply":"Va bene, sono uscito. Mezz'ora, per i ricci. Il faro non l'ho nemmeno guardato.","aside":"Per i ricci si va di giorno, con la maschera.","insight":"Michele ammette di essere uscito stanotte e di essere stato alla Cala del Monaco, sotto il faro. Dice: mezz'ora, per i ricci.","lie":true},{"id":"x2","a":"i2","b":"t2","who":"ilaria","reply":"(Si toglie gli occhiali.) Mi sono fermata al belvedere. Dieci minuti, forse venti. Non ero sola: c'era l'assessore Tricarico. Ha moglie e tre figli. Se esce il suo nome salta il progetto, e salto anch'io.","aside":"Guarda il telefono capovolto sul tavolo.","insight":"Ilaria ammette di essere stata al belvedere sopra la cala verso l'1:30, in macchina con l'assessore Tricarico.","lie":true}]},{"id":"frantoio","title":"La partita 14","place":"Frantoio Scarano, campagne di Bitonto","teaser":"Un frantoiano ai piedi del silo. Sembra un incidente.","intro":"All'alba del primo giorno di raccolta, Nicola Scarano, 67 anni, viene trovato morto ai piedi della scala del silo. I carabinieri parlano di caduta. Il figlio non ci crede e ti ha chiamato. Sul piazzale ci sono tre persone che avevano motivi per odiarlo, o per temerlo.","details":[{"id":"d1","label":"La scala del silo","text":"Nicola è a terra ai piedi della scala. Sui pioli non c'è una traccia di fango, mentre le sue scarpe sono impastate di terra del piazzale.","insight":"Pioli della scala del silo puliti. Scarpe di Nicola impastate di terra del piazzale."},{"id":"d2","label":"Il registro delle molature","text":"Ultima riga, grafia di Nicola, ore 23:40: «Partita 14: NON certificare. Chiamare la Greco.»","insight":"Registro, 23:40, grafia di Nicola: «Partita 14: NON certificare. Chiamare la Greco.»"},{"id":"d3","label":"Il bicchiere blu","text":"Sul banco d'assaggio, un bicchiere blu da degustazione, di quelli che usano gli assaggiatori professionisti. Il fondo è lucido d'olio. Gli altri bicchieri sul banco, usati ieri pomeriggio, hanno una pellicola opaca.","insight":"Sul banco, un bicchiere blu da assaggiatore con il fondo lucido d'olio. I bicchieri di ieri pomeriggio sono opachi."},{"id":"d4","label":"Il cancello","text":"Il lucchetto è stato aperto con la chiave, senza segni di scasso. Nell'erba accanto al cancello, una tanica da cinque litri piena d'olio. Sul manico, a pennarello: «S.P.»","insight":"Cancello aperto con la chiave, senza scasso. Nell'erba, una tanica d'olio piena con scritto «S.P.»."},{"id":"d5","label":"L'offerta d'acquisto","text":"Sulla scrivania, un'offerta da 2 milioni di una multinazionale dell'olio. Firmata da Antonio. Manca la firma del padre.","insight":"Offerta d'acquisto da 2 milioni: firmata da Antonio, manca la firma di Nicola."},{"id":"d6","label":"La bacheca delle chiavi","text":"Un mazzo con l'etichetta «Pinto, restituite ieri ore 18». Tra le chiavi vecchie e brunite, quella del cancello è nuova di ferramenta, lucida.","insight":"Sandro ha restituito il mazzo ieri alle 18. La chiave del cancello sul suo mazzo è nuova, lucida."},{"id":"d7","label":"Il telefono di Nicola","text":"Ultima chiamata in uscita alle 23:45, a «Marta Greco». Durata 41 secondi.","insight":"Alle 23:45 Nicola ha chiamato Marta Greco: 41 secondi."}],"suspects":[{"id":"antonio","name":"Antonio Scarano","role":"Figlio, 35 anni","look":"Occhi rossi, felpa infilata al contrario. È lui che ti ha chiamato.","tell":"Tira fuori il telefono ogni pochi minuti e lo rimette in tasca senza guardarlo. Quando si parla dell'offerta si alza e va alla finestra. Piange quando ricorda il padre al frantoio, da bambino.","questions":[{"id":"a1","q":"Dov'era stanotte?","a":"A casa. Mia figlia aveva la febbre, alle due ho chiamato la guardia medica. Potete controllare.","insight":"Antonio dice di essere stato a casa con la figlia malata. Alle 2 ha chiamato la guardia medica."},{"id":"a2","q":"Lei voleva vendere, suo padre no.","req":["d5"],"a":"Ne parlavamo. Con calma, eh. Papà ci stava pensando.","aside":"Guarda il telefono. Non lo sblocca.","insight":"Antonio dice che il padre stava valutando la vendita.","lie":true},{"id":"a3","q":"Chi ha le chiavi del frantoio?","a":"Io, papà e Marta Greco, la consulente. Le servono per i campionamenti. Sandro le aveva fino a ieri.","insight":"Le chiavi le hanno Antonio, Nicola e Marta. Sandro le aveva fino a ieri."}]},{"id":"sandro","name":"Sandro Pinto","role":"Operaio, licenziato ieri","look":"Mani grandi, voce alta. Si è presentato da solo appena ha saputo.","tell":"Parla forte e ti guarda in faccia. Ha gli stivali infangati fino alla caviglia e le unghie nere d'olio. Quando qualcuno guarda verso il cancello, si gratta la nuca.","questions":[{"id":"s1","q":"Perché l'hanno licenziata?","a":"Perché ho detto che la partita 14 puzzava di olio di semi. Mi ha dato del bugiardo. Poi ieri sera alle undici mi scrive: «Avevi ragione tu. Domani sistemo tutto.» Guardi, è qui.","insight":"Ieri alle 23 Nicola ha scritto a Sandro, sulla partita 14 «tagliata» con olio di semi: «Avevi ragione tu. Domani sistemo tutto.»"},{"id":"s2","q":"Dov'era stanotte?","a":"Al bar Centrale fino all'una, poi a casa. Chiedete a Mimmo, il barista.","insight":"Sandro dice di essere stato al bar Centrale fino all'una, poi a casa.","lie":true},{"id":"s3","q":"Chi certifica l'olio che esce da qui?","a":"La Greco. Assaggia lei e firma lei. Tutto quello che esce da qui come extravergine passa dalla sua firma.","insight":"Le certificazioni dell'extravergine le firma Marta."},{"id":"s4","q":"Con chi litigava Nicola, ultimamente?","a":"Col figlio. Ieri pomeriggio, prima che mi cacciasse, Nicola gli urlava in faccia: «Finché campo io, qui non si vende niente!»","insight":"Ieri pomeriggio Nicola ha urlato ad Antonio: «Finché campo io, qui non si vende niente!»"}]},{"id":"marta","name":"Marta Greco","role":"Assaggiatrice e consulente, 42 anni","look":"Impeccabile anche all'alba. Profumo costoso, taccuino in pelle.","tell":"Risponde prima che tu finisca la domanda. Quando si nomina il registro si sistema un orecchino. Ha le scarpe pulite, appena lucidate, l'unica sul piazzale.","questions":[{"id":"m1","q":"Quando ha visto Nicola l'ultima volta?","a":"Ieri alle otto di sera, qui. Poi sono andata a casa. Da sola, purtroppo.","insight":"Marta dice di essere andata via alle 20 e di non essere più tornata."},{"id":"m2","q":"Nicola l'ha chiamata alle 23:45. Che cosa voleva?","req":["d7"],"a":"Ah, la chiamata. Parlavamo della raccolta di domani. Quaranta secondi, niente di importante.","insight":"Marta dice che alle 23:45 Nicola le ha parlato della raccolta.","lie":true},{"id":"m3","q":"C'è un suo bicchiere da assaggio ancora lucido d'olio.","req":["d3","m1"],"a":"Ne lascio sempre qualcuno in giro. Sarà di ieri pomeriggio.","aside":"Si sistema l'orecchino.","insight":"Marta dice che il bicchiere blu è suo e che è di ieri pomeriggio.","lie":true},{"id":"m4","q":"Parliamo della partita 14.","req":["d2"],"a":"Io certifico quello che assaggio. Punto.","aside":"Poi, dopo un attimo: «Chi le ha parlato della partita 14?»","insight":"Sulla partita 14 Marta chiede chi te ne ha parlato."}]}],"bluff":{"text":"Dici che la settimana scorsa Nicola aveva fatto installare una telecamera nel magazzino, e che non lo sapeva nessuno.","reactions":{"antonio":"«Papà? Una telecamera?» Fa due passi verso il magazzino, poi torna indietro.","sandro":"Smette di parlare di colpo. Guarda il cancello e si gratta la nuca.","marta":"Chiede, con voce neutra, se la telecamera registra anche l'audio."},"insight":"Al bluff della telecamera: Antonio va verso il magazzino, Sandro guarda il cancello, Marta chiede se registra l'audio."},"motive":{"options":["Vendere il frantoio e tenersi l'anticipo della multinazionale.","Vendicarsi del licenziamento di ieri.","Impedire che Nicola denunciasse l'olio certificato extravergine.","Coprire un furto d'olio dal magazzino."],"correct":2},"culprit":"marta","key":["m3","m2","x1"],"solution":"Sandro aveva ragione: la partita 14 era tagliata con olio di semi e Marta l'aveva certificata extravergine per un compratore che la pagava bene. Ieri sera Nicola se ne accorge, blocca la partita sul registro e alle 23:45 la chiama. Marta arriva con la sua chiave e assaggia l'olio davanti a lui per convincerlo che sbaglia: il suo bicchiere è l'unico ancora lucido. Nicola minaccia di denunciarla. Lei lo colpisce e trascina il corpo ai piedi del silo per simulare una caduta, ma sui pioli non c'è il fango delle scarpe di lui. Antonio nascondeva un anticipo di 50.000 € preso di nascosto dal padre; Sandro, con una copia della chiave, è venuto a mezzanotte a rubare olio ed è scappato vedendo la luce accesa e l'auto di Marta.","contradictions":[{"id":"x1","a":"m2","b":"d2","who":"marta","reply":"Va bene. Mi ha parlato della partita 14. Gli ho detto che si sbagliava. Tutto qui.","aside":"Guarda il banco d'assaggio.","insight":"Marta ammette che alle 23:45 Nicola le ha contestato la partita 14.","lie":true},{"id":"x2","a":"a2","b":"s4","who":"antonio","reply":"Va bene, ci siamo urlati addosso. E c'è un'altra cosa. La multinazionale mi ha già dato cinquantamila euro di anticipo. Papà non lo sapeva.","aside":"Si copre la faccia con le mani.","insight":"Antonio ammette la lite di ieri e un anticipo di 50.000 € dalla multinazionale, preso senza dirlo al padre.","lie":true},{"id":"x3","a":"s2","b":"d4","who":"sandro","reply":"Va bene! Verso mezzanotte sono venuto a prendermi l'olio che mi spettava. Avevo fatto una copia della chiave. Ma c'era la luce accesa dentro e un'auto nel piazzale. Ho mollato la tanica e sono scappato.","aside":"Abbassa la voce per la prima volta.","insight":"Sandro ammette di essere venuto al frantoio verso mezzanotte con una copia della chiave. Dice di aver visto luce accesa e un'auto nel piazzale.","lie":true}]},{"id":"pittule","title":"Foglie d'alloro","place":"Sagra della pittula, Martano","teaser":"Il presidente della sagra crolla alla cassa. Il suo infuso non era d'alloro.","intro":"Ieri sera, alla chiusura della Sagra della pittula, Gigi Pellegrino, presidente del comitato, si è accasciato dietro la cassa con il cuore impazzito. È in cardiologia a Lecce, vivo per miracolo: nel sangue gli hanno trovato il veleno dell'oleandro. In paese tutti fanno lo stesso nome, quello del friggitore che Gigi ha cacciato dalla sagra. Il figlio di Gigi non ci crede, e ti ha chiesto di passare prima che smontino gli stand.","details":[{"id":"d1","label":"La tazza di Gigi","text":"Tazza di smalto con la scritta PRESIDENTE. Sul fondo, un dito d'infuso freddo e due foglie lunghe, strette, dure come cuoio, con una nervatura bianca al centro.","insight":"Nella tazza PRESIDENTE: due foglie lunghe, strette, dure, con una nervatura bianca al centro."},{"id":"d2","label":"Il pentolone dell'infuso","text":"In cucina, il pentolone dell'infuso di fine serata. Foglie larghe e ovali, bucce di limone. L'hanno bevuto in dodici, volontari compresi. Nessuno sta male.","insight":"Nel pentolone: foglie larghe e ovali e bucce di limone. L'hanno bevuto in dodici, nessuno sta male."},{"id":"d3","label":"La siepe dietro la cassa","text":"Oleandri fioriti, a un passo dal bancone della cassa. Due rametti spezzati di fresco: sul taglio, lattice bianco ancora appiccicoso.","insight":"Nella siepe d'oleandro dietro la cassa, due rametti spezzati di fresco."},{"id":"d4","label":"L'agenda di Gigi","text":"Nella borsa del comitato. Alla data di ieri, a matita: «Dopo la chiusura: conti con Ada. 2019-2024, mancano 11.000?»","insight":"Agenda di Gigi, ieri: «Dopo la chiusura: conti con Ada. 2019-2024, mancano 11.000?»"},{"id":"d5","label":"I video del volontario","text":"Sul telefono di un volontario, due video. Ore 20:20: Tonino Russo urla davanti allo stand delle pittule: «Te ne pentirai, Gigi! Te ne pentirai!» Ore 22:14, durante la lotteria: sullo sfondo, dietro gli stand, passa una camicia a fiori.","insight":"Video delle 20:20: Tonino urla a Gigi «Te ne pentirai!». Video delle 22:14: una camicia a fiori passa dietro gli stand."},{"id":"d6","label":"Il cestino della cassa","text":"Tra gli scontrini, un paio di guanti in lattice, di quelli per contare le monete. Sulle dita, macchie verdi e un velo di lattice bianco rappreso.","insight":"Nel cestino della cassa, guanti da monete con macchie verdi e lattice bianco rappreso sulle dita."},{"id":"d7","label":"Il messaggio del cardiologo","text":"Il figlio di Gigi ti mostra il telefono: «Glicosidi dell'oleandro. Ingestione probabile tra le 21:30 e le 22:30.»","insight":"Secondo il cardiologo, Gigi ha ingerito il veleno tra le 21:30 e le 22:30."}],"suspects":[{"id":"ada","name":"Ada Mele","role":"Tesoriera del comitato, 54 anni","look":"Cardigan abbottonato fino al collo nonostante il caldo. La borsa della cassa stretta sulle ginocchia.","tell":"Tiene le mani chiuse a pugno sopra la borsa. Quando le apre per gesticolare, i polpastrelli sono arrossati. Chiede due volte come sta Gigi, e tutte e due le volte non aspetta la risposta.","questions":[{"id":"a1","q":"Dov'era ieri sera?","a":"Alla cassa, dalle sette a mezzanotte. Non mi sono mossa un minuto. Chi lascia la cassa di una sagra è un pazzo.","insight":"Ada dice di non essersi mai mossa dalla cassa, dalle 19 a mezzanotte."},{"id":"a2","q":"Ha visto la tazza di Gigi, ieri sera?","a":"No. L'infuso Gigi se lo beveva in cucina, con le cuoche. Alla cassa non l'ho mai vista.","insight":"Ada dice che la tazza di Gigi alla cassa non l'ha mai vista."},{"id":"a3","q":"Stanotte Gigi voleva fare i conti con lei. Mancano undicimila euro.","req":["d4"],"a":"Gigi i conti li sbaglia dal 2019. Sono conti suoi, non miei. Glielo dimostro con i quaderni.","aside":"Stringe la borsa della cassa.","insight":"Ada sapeva che Gigi voleva fare i conti con lei. Dice che gli errori sono di Gigi, e parla di «quaderni».","lie":true},{"id":"a4","q":"I guanti della cassa sono macchiati di verde.","req":["d6"],"a":"Sono i miei, per le monete. Il verde? Avrò toccato la siepe. Ci si appoggiano tutti.","aside":"Chiude la mano destra.","insight":"Ada dice che i guanti macchiati sono i suoi e che il verde viene dalla siepe dietro la cassa.","lie":true}]},{"id":"pamela","name":"Pamela Stifani","role":"Cuoca volontaria, 31 anni","look":"Grembiule infarinato, occhi gonfi. Ha ancora la retina nei capelli.","tell":"Si torce le mani nel grembiule e guarda il pentolone. Ogni volta che qualcuno dice «veleno» trattiene il fiato. Porta al collo una catenina d'oro che infila sotto il grembiule quando la guardi.","questions":[{"id":"p1","q":"Chi prepara l'infuso di Gigi?","a":"Io. Ogni sera: alloro del mio orto e bucce di limone. L'abbiamo bevuto tutti, dalla stessa pentola. Io due tazze.","insight":"L'infuso lo prepara Pamela, alloro del suo orto. Tutti hanno bevuto dalla stessa pentola."},{"id":"p2","q":"Chi ha portato la tazza a Gigi?","a":"Io, alle dieci meno cinque, alla cassa. Era lì con Ada a contare. Poi l'hanno chiamato sul palco per la lotteria e la tazza è rimasta sul bancone, accanto a lei. Venti minuti, più o meno.","insight":"Pamela dice di aver portato la tazza a Gigi alla cassa alle 21:55. Poi, per circa venti minuti di lotteria, è rimasta sul bancone accanto ad Ada."},{"id":"p3","q":"Le foglie nella tazza sono del suo alloro?","req":["d1"],"a":"(Ne prende una e la gira.) Questa non è alloro. L'alloro è largo e profuma. Questa è dura, lunga... è oleandro. Come la siepe dietro la cassa. Io l'oleandro non lo tocco nemmeno per i fiori.","aside":"Si siede e si passa una mano sulla fronte.","insight":"Pamela riconosce le foglie della tazza: oleandro, come la siepe dietro la cassa."},{"id":"p4","q":"Che rapporto aveva con Gigi?","a":"È il presidente. Io friggo le pittule. Basta.","aside":"Infila la catenina sotto il grembiule.","insight":"Pamela dice che tra lei e Gigi c'è solo il lavoro della sagra.","lie":true}]},{"id":"tonino","name":"Tonino Russo","role":"Friggitore, 58 anni","look":"Camicia a fiori aperta sul petto, voce che si sente dall'altra parte della piazza. È venuto da solo, «per chiarire».","tell":"Urla, ma ti guarda in faccia mentre urla. Quando nomini Gigi in ospedale gli trema il mento. Ha un taglio fresco sul dorso della mano, fasciato con un tovagliolo di carta.","questions":[{"id":"t1","q":"Ieri sera ha minacciato Gigi davanti a tutti.","req":["d5"],"a":"Mi ha tolto lo stand dopo vent'anni! Gli ho detto di tutto, sì. Alle otto e venti. Poi sono tornato al mio locale a Calimera: trenta coperti, due camerieri, fino all'una. Chieda a chiunque.","insight":"Tonino dice di essere tornato nel suo locale a Calimera dopo le 20:20 e di esserci rimasto fino all'una.","lie":true},{"id":"t2","q":"Perché Gigi l'ha cacciata?","a":"Dice per l'igiene. Io dico perché a novembre gli ho detto che la cassa della sagra non tornava. «Gigi, guarda chi conta i soldi.» Ecco la ricompensa.","insight":"Tonino dice di aver avvertito Gigi, a novembre, che i soldi della sagra non tornavano."},{"id":"t3","q":"Chi sta alla cassa, di solito?","a":"Sempre lei, la Mele. Da dieci anni. Non dà il cambio a nessuno, nemmeno per andare in bagno. Uno se lo chiede, perché.","insight":"Da dieci anni alla cassa c'è solo Ada, senza cambi."},{"id":"t4","q":"Chi è vicino a Gigi, nel comitato?","a":"Vicino? La cuoca, Pamela. Da un anno, di nascosto, che Gigi è sposato. Lo sa tutta Martano tranne sua moglie.","insight":"Tonino dice che Pamela e Gigi hanno una relazione nascosta da un anno."}]}],"contradictions":[{"id":"x1","a":"a2","b":"p2","who":"ada","reply":"Ah, quella tazza. Può darsi. C'era tanta gente, chi se la ricorda una tazza.","aside":"Chiude le mani a pugno sulla borsa.","insight":"Ada ammette che la tazza di Gigi può essere rimasta sul bancone della cassa, accanto a lei.","lie":true},{"id":"x2","a":"p4","b":"t4","who":"pamela","reply":"(Tira fuori la catenina.) Me l'ha regalata lui. Da un anno. Ieri pomeriggio mi ha detto che era finita, che torna da sua moglie. Ma l'infuso gliel'ho fatto come sempre. Come sempre.","aside":"Stringe la catenina nel pugno.","insight":"Pamela ammette la relazione con Gigi. Dice che ieri pomeriggio lui l'aveva lasciata.","lie":true},{"id":"x3","a":"t1","b":"d5","who":"tonino","reply":"Va bene, sono tornato! Dieci minuti. La friggitrice nello stand era mia, vent'anni di olio. Me la sono ripresa senza chiedere, e mi sono pure tagliato. Alla cassa non ci sono nemmeno passato.","aside":"Si guarda il tovagliolo sulla mano.","insight":"Tonino ammette di essere tornato alla sagra verso le 22:14 per riprendersi la friggitrice.","lie":true}],"bluff":{"text":"Annunci che Gigi si è svegliato e che nel pomeriggio parlerà con i carabinieri.","reactions":{"ada":"«Poverino. Con tutti quei farmaci sarà confuso, dirà cose senza senso.»","pamela":"Scoppia a piangere e stringe la catenina nel pugno.","tonino":"«Allora ditegli che Tonino non c'entra.» Poi guarda verso il suo vecchio stand, vuoto."},"insight":"Al bluff del risveglio: Ada dice che Gigi sarà confuso, Pamela stringe la catenina, Tonino guarda il suo vecchio stand."},"motive":{"options":["Gelosia: Gigi aveva chiuso la loro storia.","Vendetta per lo stand tolto dopo vent'anni.","Impedire a Gigi di scoprire l'ammanco nella cassa.","Prendersi la presidenza del comitato."],"correct":2},"culprit":"ada","key":["x1","a4","a3"],"solution":"Da anni Ada si teneva una parte dell'incasso della sagra, e Tonino l'aveva capito prima di tutti. Gigi aveva rifatto i conti e voleva chiuderli con lei la sera stessa. Alle dieci, quando è salito sul palco per la lotteria, la sua tazza è rimasta sul bancone accanto ad Ada: lei ha strappato due foglie dalla siepe alle sue spalle, con i guanti della cassa, e le ha lasciate nell'infuso. Il pentolone era innocuo. Pamela nascondeva la sua storia con Gigi, finita il giorno prima. Tonino nascondeva di essere tornato alle 22:14 a riprendersi la friggitrice, ma alla cassa non si è avvicinato."},{"id":"spartitomonteleone","title":"Notte sul porto","place":"Teatro Galante, Bari","teaser":"Una prima col sindaco in sala. Una vetrina vuota all'intervallo.","intro":"Il Teatro Galante riapre dopo tre anni con «Notte sul porto» di Saverio Monteleone. Nel foyer, sotto vetro, lo spartito autografo del 1891, il tesoro del teatro. Quando all'intervallo il pubblico esce, la vetrina è vuota e chiusa a chiave. Trecento persone nel foyer, tutte sospettate. Il sovrintendente vuole la polizia; il sindaco vuole prima te, e senza giornalisti.","details":[{"id":"d1","label":"La vetrina","text":"Richiusa a chiave, vetro intatto, nessun graffio sulla serratura. Sul velluto resta il segno rettangolare dello spartito.","insight":"La vetrina è stata aperta e richiusa con una chiave. Nessuna forzatura."},{"id":"d2","label":"Il registro della vigilanza","text":"«19:30 — allarme vetrina foyer escluso. Motivo: falsi allarmi ripetuti. Autorizza: direzione.»","insight":"Alle 19:30 l'allarme della vetrina è stato escluso. «Autorizza: direzione.»"},{"id":"d3","label":"La polizza","text":"Rinnovata tre settimane fa. Valore assicurato dello spartito: da 200.000 a 900.000 €. Beneficiario: il teatro. Firma del sovrintendente.","insight":"Tre settimane fa il valore assicurato dello spartito è passato da 200.000 a 900.000 €. Firma del sovrintendente."},{"id":"d4","label":"La borsa di Samuele","text":"Sotto il leggio in buca: fotocopie dello spartito, pagina per pagina, fitte di annotazioni a matita. In mezzo, il biglietto da visita di un editore musicale di Milano. Sul retro, a penna: «Bozze entro ottobre. Riservato.»","insight":"Samuele ha una copia completa dello spartito, annotata, e il biglietto di un editore di Milano: «Bozze entro ottobre. Riservato.»"},{"id":"d5","label":"La cassaforte della direzione","text":"La chiave di riserva della vetrina è al suo posto. Accanto, una lettera di un antiquario di Ginevra: «Confermo l'interesse del mio cliente. Massima discrezione.»","insight":"Nella cassaforte della direzione: la chiave di riserva della vetrina e la lettera di un antiquario di Ginevra. «Massima discrezione.»"},{"id":"d6","label":"Il guardaroba","text":"Un tubo portadisegni nero, scontrino 17, depositato alle 20:35. Il primo atto era cominciato da mezz'ora. La guardarobiera ricorda solo «un signore in smoking». Stasera sono tutti in smoking.","insight":"Alle 20:35, a primo atto in corso, un uomo in smoking ha lasciato al guardaroba un tubo portadisegni nero. Scontrino 17."},{"id":"d7","label":"Il programma di sala","text":"Primo atto: 20:00-21:15, senza interruzioni. A matita, qualcuno ha segnato «20:40 — assolo al pianoforte».","insight":"Primo atto: 20:00-21:15, senza pause. A matita: «20:40 — assolo al pianoforte»."}],"suspects":[{"id":"aldo","name":"Aldo Ferrante","role":"Sovrintendente del teatro, 61 anni","look":"Smoking impeccabile, garofano all'occhiello, voce da conferenza stampa.","tell":"Parla del teatro al passato: «era un gioiello», «avevamo un pubblico». Mentre ti ascolta si liscia due volte il taschino dello smoking. Sorride anche quando nessuno lo guarda.","questions":[{"id":"a1","q":"Dov'era durante il primo atto?","a":"Nel mio palco, dall'inizio alla fine, accanto al sindaco. Non ho perso una nota.","insight":"Aldo dice di non aver mai lasciato il palco durante il primo atto, accanto al sindaco."},{"id":"a2","q":"Tre settimane fa ha fatto quadruplicare l'assicurazione.","req":["d3"],"a":"Valore di mercato aggiornato. Un Monteleone autografo vale quello. Lo dice il perito.","insight":"Aldo dice che l'aumento della polizza a 900.000 € è una stima del perito."},{"id":"a3","q":"L'allarme della vetrina l'ha fatto spegnere lei.","req":["d2"],"a":"Suonava ogni cinque minuti, alla prima, col sindaco in sala! Cosa dovevo fare, farlo suonare durante l'ouverture?","insight":"Aldo ammette di aver fatto escludere l'allarme della vetrina alle 19:30: «suonava ogni cinque minuti»."}]},{"id":"samuele","name":"Samuele Loiacono","role":"Maestro al pianoforte, 33 anni","look":"Frac un po' largo, capelli spettinati, dita macchiate di matita.","tell":"Quando parla dello spartito muove le dita come se suonasse. Quando si parla del furto incrocia le braccia e lancia un'occhiata verso la buca, dove ha lasciato la borsa.","questions":[{"id":"s1","q":"Dov'era durante il primo atto?","a":"In buca, al pianoforte. Settantacinque minuti senza respirare. Alle 20:40 c'è il mio assolo, l'hanno sentito in duecento. E durante l'assolo alzo sempre gli occhi al palco della direzione, per scaramanzia. Stasera accanto al sindaco c'era una sedia vuota.","insight":"Samuele era in buca per tutto il primo atto. Alle 20:40, durante l'assolo, ha visto una sedia vuota accanto al sindaco, nel palco della direzione."},{"id":"s2","q":"Lei ha fotocopiato lo spartito pagina per pagina.","req":["d4"],"a":"Lo studio da due anni. Mi servono per studiare, nient'altro. E sì, a Lecce mi hanno accusato di aver rubato una lettera d'archivio. Assolto. Lo sanno tutti, per questo guardate me.","insight":"Samuele dice che le fotocopie gli servono solo per studiare. A Lecce è stato accusato di un furto d'archivio, e assolto.","lie":true},{"id":"s3","q":"Come stanno i conti del teatro?","a":"Male. Noi orchestrali non vediamo uno stipendio da aprile. Il sovrintendente ripete che «presto arriveranno soldi». Non ha mai detto da dove.","insight":"Gli orchestrali non vedono uno stipendio da aprile. Aldo ripete che «presto arriveranno soldi»."}]},{"id":"tonino","name":"Tonino Scarpa","role":"Custode del teatro, 62 anni","look":"Divisa blu, auricolare nell'orecchio, una sola chiave appesa al collo.","tell":"Odore di sigaretta sulla divisa. Tiene il telefono basso e lo sbircia: sullo schermo c'è la partita del Bari in diretta. Quando dici «vetrina» si tocca la chiave appesa al collo.","questions":[{"id":"c1","q":"Dov'era durante il primo atto?","a":"Al mio posto, in foyer, vicino alla vetrina. Non è passato nessuno. Lo giuro sui miei figli.","insight":"Tonino dice di aver sorvegliato la vetrina per tutto il primo atto."},{"id":"c2","q":"Lei non era in foyer. Era a guardare la partita.","req":["t_tonino"],"a":"(Si toglie l'auricolare.) All'ingresso artisti, lì il telefono prende. Verso le otto e mezza dalla porta a vetri ho visto uno scendere dalla scala di servizio, quella che viene dai palchi. Smoking, di spalle, un tubo nero sotto il braccio. Andava verso il foyer. Io ho nascosto il telefono e non ho guardato chi era.","insight":"Tonino ammette di essere stato all'ingresso artisti a guardare la partita. Verso le 20:30 ha visto un uomo in smoking, di spalle, scendere dalla scala dei palchi con un tubo nero.","lie":true},{"id":"c3","q":"Chi ha le chiavi della vetrina?","a":"Io, questa qui, sempre al collo. E la riserva, nella cassaforte del sovrintendente. La combinazione la sa solo lui.","insight":"Le chiavi della vetrina sono due: quella di Tonino, al collo, e la riserva nella cassaforte che apre solo Aldo."}]}],"bluff":{"text":"Annunci che a fine spettacolo la polizia aprirà tutto quello che c'è al guardaroba, cappotto per cappotto.","reactions":{"aldo":"«Il ladro sarà già a Brindisi. Non perdiamo tempo col guardaroba.»","samuele":"Guarda verso la buca. «Anche le borse? Anche quelle degli orchestrali?»","tonino":"«Il guardaroba? E che c'entra il guardaroba?» Si tocca la chiave al collo."},"insight":"Al bluff del guardaroba Aldo ha detto che è tempo perso, Samuele ha chiesto se apriranno anche le borse degli orchestrali, Tonino si è toccato la chiave."},"motive":{"options":["Incassare 900.000 € dall'assicurazione e vendere l'originale a Ginevra.","Avere l'originale per l'edizione che prepara di nascosto.","Rifarsi degli stipendi che il teatro non paga da aprile.","Coprire di aver lasciato la vetrina sguarnita per la partita."],"correct":0},"culprit":"aldo","key":["x1","c2","a2","c3"],"solution":"Il furto non è avvenuto all'intervallo ma durante il primo atto, con il foyer vuoto. Alle 19:30 Aldo fa escludere l'allarme. Verso le 20:30 lascia il palco, e dalla buca Samuele vede la sua sedia vuota. Scende dalla scala di servizio, apre la vetrina con la riserva della sua cassaforte, arrotola lo spartito nel tubo e alle 20:35 lo lascia al guardaroba: lo scontrino 17 ce l'ha nel taschino. Il teatro è al verde: 900.000 € dall'assicurazione e l'originale venduto a Ginevra. Tonino aveva lasciato il posto per guardare il Bari e l'ha visto passare di spalle; Samuele nascondeva un'edizione non autorizzata per un editore di Milano, non un furto.","contradictions":[{"id":"x1","a":"a1","b":"s1","who":"aldo","reply":"Sono sceso un momento. Un problema con le luci del foyer.","aside":"Si liscia il taschino.","insight":"Aldo ammette di aver lasciato il palco durante il primo atto, «per le luci del foyer».","lie":true},{"id":"x2","a":"s2","b":"d4","who":"samuele","reply":"(Scioglie le braccia.) Un editore di Milano vuole la prima edizione critica di «Notte sul porto». Il sovrintendente non mi avrebbe mai dato il permesso. Le copie le ho prese dall'archivio senza chiedere. Se si sa, qui non suono più.","insight":"Samuele ammette di preparare di nascosto un'edizione dello spartito per un editore di Milano, con copie prese dall'archivio senza permesso.","lie":true}]},{"id":"trullostella","title":"Il trullo di troppo","place":"Trullo Stella, rione Monti, Alberobello","teaser":"Tre famiglie, un solo trullo. E il proprietario non risponde più.","intro":"Una coppia di Torino arriva al Trullo Stella con la ricevuta di un bonifico da 1.400 euro. Dentro c'è già un altro ospite, con un'altra prenotazione. Nel pomeriggio ne arrivano altri due. Il proprietario, Donato Recchia, 81 anni, è sparito da ieri mattina. In paese dicono che è scappato con i soldi. Tu pensi che un uomo di ottantun anni non sappia nemmeno cosa sia un bonifico online.","details":[{"id":"d1","label":"L'annuncio clonato","text":"Stesse foto del Trullo Stella, 90 euro a notte invece di 160, «pagamento anticipato con bonifico». L'IBAN è di una banca online. Intestatario: Donato Recchia.","insight":"L'annuncio clonato del Trullo Stella chiede un bonifico anticipato su un conto di banca online intestato a Donato Recchia."},{"id":"d2","label":"La cassetta della posta","text":"Una busta della stessa banca online: «Ecco la tua nuova carta». È ancora sigillata. Il timbro è di due mesi fa.","insight":"Nella cassetta di Donato, una busta della stessa banca online con la nuova carta: sigillata, timbro di due mesi fa."},{"id":"d3","label":"Il raccoglitore dell'agenzia","text":"Tra i documenti degli ospiti, una fotocopia a colori, fronte e retro, della carta d'identità di Donato. È quella rinnovata a marzo. Accanto, la tessera sanitaria.","insight":"Nel raccoglitore dell'agenzia: fotocopia a colori della carta d'identità di Donato, quella rinnovata a marzo, e la tessera sanitaria."},{"id":"d4","label":"La casa di Donato","text":"Letto rifatto. Mancano le medicine per il cuore, il rasoio, la coppola della domenica.","insight":"In casa di Donato mancano le medicine per il cuore, il rasoio e la coppola della domenica. Il letto è rifatto."},{"id":"d5","label":"Il cellulare di Donato","text":"Un vecchio telefono a tasti, lasciato sul tavolo della cucina. Ultimo SMS, ieri alle 7:12, da un numero non in rubrica: «Zio la finanza ti cerca per gli affitti in nero. Sparisci qualche giorno e lascia il telefono, ti rintracciano. Non dire niente a nessuno. G.»","insight":"SMS a Donato, ieri alle 7:12, da un numero non in rubrica, firmato «G.»: la finanza lo cerca per gli affitti in nero, deve sparire e lasciare il telefono."},{"id":"d6","label":"Il quaderno di Donato","text":"A matita, le prenotazioni che gli passa l'agenzia. Agosto: solo «Intini, 10 notti». In fondo: «Stagione morta. Il 30 finisce il contratto con Sabrina. Passo all'agenzia di Bari.»","insight":"Quaderno di Donato: ad agosto una sola prenotazione, «Intini, 10 notti». In fondo: il 30 finisce il contratto con Sabrina, passa a un'agenzia di Bari."},{"id":"d7","label":"La lettera della finanziaria","text":"Sul tavolo di Donato, un sollecito intestato al nipote Gianni: «Tre rate scadute. Ultimo avviso prima del recupero crediti.»","insight":"Sollecito di una finanziaria a nome di Gianni: tre rate scadute, ultimo avviso prima del recupero crediti."}],"suspects":[{"id":"gianni","name":"Gianni Recchia","role":"Nipote di Donato, 34 anni","look":"Camicia stropicciata, telefono in mano, le pellicine delle dita mangiate a sangue.","tell":"La gamba batte sotto il tavolo. Si strappa le pellicine del pollice finché sanguina. Quando parla dello zio abbassa la voce e ti guarda fisso.","questions":[{"id":"g1","q":"Dov'è suo zio?","a":"Non lo so. Il telefono squilla a vuoto da ieri. Se lo zio scappa, va in un posto solo: la casedda della nonna verso Locorotondo. Ma lì non c'è campo, e senza macchina io non ci arrivo.","insight":"Gianni: se lo zio scappa, va nella casedda della nonna verso Locorotondo, dove non c'è campo. Lui dice di non avere la macchina."},{"id":"g2","q":"L'annuncio del trullo l'ha fatto lei?","a":"Quello vero, sì. Tre giorni fa ho visto la copia e l'ho segnalata alla piattaforma. Ecco la mail, guardi l'ora. Chi fa una truffa non la denuncia.","insight":"Gianni dice di aver segnalato l'annuncio clonato alla piattaforma tre giorni fa. Mostra la mail."},{"id":"g3","q":"Il messaggio a suo zio è firmato «G.».","req":["d5"],"a":"Io lo zio lo chiamo, non gli scrivo: gli SMS li legge con la lente. E il mio numero ce l'ha salvato come «Giannino». Se era mio, lo vedeva. Chi ha scritto sapeva che lui della finanza ha il terrore.","insight":"Gianni: lo zio lo ha in rubrica come «Giannino» e gli SMS li legge con la lente; lui lo chiama, non gli scrive."},{"id":"g4","q":"Lei ha tre rate scadute con una finanziaria.","req":["d7"],"a":"Seimila euro. Lo zio lo sa. Mi ha detto: vieni a lavorare ai trulli e li ripaghi. Io lo zio non lo derubo.","aside":"Si strappa un'altra pellicina.","insight":"Gianni: debito di seimila euro; lo zio lo sa e gli ha offerto di lavorare ai trulli per ripagarlo."}]},{"id":"sabrina","name":"Sabrina Colucci","role":"Titolare dell'agenzia Chiavi del Trullo","look":"Tailleur blu, sorriso da accoglienza, un mazzo di chiavi con venti targhette colorate.","tell":"Sorride anche quando non serve. Il telefono con la cover dell'agenzia è sul tavolo. Dalla borsa, ogni tanto, vibra un secondo telefono, economico. Lei non lo guarda e ci mette sopra la mano.","questions":[{"id":"s1","q":"Come funziona la gestione del trullo?","a":"Chiavi, pulizie, check-in. Gli annunci li fa il nipote, i soldi vanno a Donato. Io prendo la mia percentuale e basta.","insight":"Sabrina dice che lei fa chiavi, pulizie e check-in: gli annunci li fa il nipote e i soldi vanno a Donato."},{"id":"s2","q":"Quando ha visto Donato l'ultima volta?","a":"L'altro ieri pomeriggio, per i conti. Era agitato. Continuava a dire che la finanza ce l'aveva con lui, che l'avrebbero arrestato.","insight":"Sabrina: l'altro ieri pomeriggio Donato era agitato e diceva che la finanza ce l'aveva con lui, che l'avrebbero arrestato."},{"id":"s3","q":"Nel suo raccoglitore c'è la carta d'identità di Donato.","req":["d3"],"a":"Me l'ha data lui, per il contratto di gestione. È normale.","aside":"Il contratto di gestione è del 2019.","insight":"Sabrina dice che la fotocopia della carta d'identità di Donato le serviva per il contratto di gestione.","lie":true},{"id":"s4","q":"L'SMS a Donato viene da un numero sconosciuto. E lei ha due telefoni.","req":["d5","t_sabrina"],"a":"Quello è per le signore delle pulizie. Una cosa di lavoro.","aside":"Il telefono sul tavolo ha il logo dell'agenzia. Mentre risponde, spinge l'altro in fondo alla borsa.","insight":"Sabrina dice che il secondo telefono serve per le signore delle pulizie.","lie":true}]},{"id":"rocco","name":"Rocco Intini","role":"Ospite del trullo, 52 anni","look":"Polo nuova, abbronzatura da tre giorni. Continua a guardare la porta del trullo.","tell":"Si volta ogni volta che si muove la tenda del trullo. All'anulare sinistro niente fede, ma una striscia di pelle bianca. Risponde prima che tu finisca la domanda.","questions":[{"id":"r1","q":"Come ha prenotato il trullo?","a":"In agenzia, dalla signora Colucci. Anticipo in contanti a maggio. Ho la ricevuta con il timbro.","insight":"Rocco ha prenotato in agenzia da Sabrina: anticipo in contanti a maggio, ricevuta col timbro."},{"id":"r2","q":"Si è tolto la fede. Chi c'è nel trullo?","req":["t_rocco"],"a":"(Abbassa la voce.) Una persona. Non è mia moglie. Se finisco su un verbale, sono finito. Io con i soldi di nessuno c'entro.","insight":"Rocco: nel trullo c'è una persona che non è sua moglie. Chiede di non finire su un verbale.","lie":true},{"id":"r3","q":"Ha visto il proprietario in questi giorni?","a":"Il vecchio? Ieri mattina, verso le sette e mezza. Caricava una valigetta sulla Panda e parlava da solo: «In galera non ci vado. Non ci vado.»","insight":"Rocco: ieri verso le 7:30 Donato caricava una valigetta sulla Panda e ripeteva «In galera non ci vado»."},{"id":"r4","q":"Ha visto qualcun altro in casa del vecchio?","a":"Il nipote. L'altro ieri sera, tardi. È uscito con una busta gonfia, di quelle della posta. Si è guardato intorno e se l'è infilata sotto la camicia.","insight":"Rocco: l'altro ieri sera Gianni è uscito da casa di Donato con una busta gonfia e se l'è infilata sotto la camicia."}]}],"bluff":{"text":"Annunci che la banca online ha dato ai carabinieri l'indirizzo internet da cui è stato aperto il conto, e che domattina arriva il nome.","reactions":{"gianni":"«Il nome di chi?» Si alza, va alla finestra, torna a sedersi. «Così lo zio può tornare a casa.»","sabrina":"«Tanto sarà il wifi di qualche bar, no? Quelli li usano tutti.» Lo dice sorridendo.","rocco":"«Io ho pagato in contanti.» Poi, piano: «Anche i nomi di chi dorme nei trulli?»"},"insight":"Al bluff dell'indirizzo internet: Gianni si è alzato ed è andato alla finestra; Sabrina ha parlato del wifi dei bar; Rocco ha chiesto dei nomi degli ospiti."},"culprit":"sabrina","key":["x1","s4","s3"],"motive":{"options":["Incassare con il trullo clonato prima di perdere la gestione","Ripagare le rate scadute con la finanziaria","Far sparire lo zio e mettere le mani sul trullo","Non far scoprire alla moglie con chi era in vacanza"],"correct":0},"solution":"Sabrina sapeva che a fine mese Donato le avrebbe tolto la gestione. Con la fotocopia fresca della sua carta d'identità ha aperto un conto online a nome di lui, mai usato da Donato come prova la busta sigillata, e ha messo in rete un clone del Trullo Stella a prezzo stracciato, incassando anticipi per un trullo che lei stessa aveva già affittato a Rocco. Quando i truffati hanno cominciato ad arrivare, le serviva un colpevole: col secondo telefono ha scritto a Donato firmandosi «G.», come il nipote pieno di debiti. Il vecchio, terrorizzato dalla finanza, è scappato nella casedda di campagna. Ma Sabrina conosceva la storia della finanza prima ancora che partisse l'SMS. Gianni nascondeva i 1.500 euro presi dal barattolo dello zio, e Rocco un'amante che non doveva finire su nessun verbale.","contradictions":[{"id":"x1","a":"s2","b":"d5","who":"sabrina","reply":"Mi sarò confusa col giorno. Forse me l'ha detto ieri, al telefono.","aside":"Ieri alle sette Donato ha lasciato il telefono sul tavolo della cucina.","insight":"Sabrina corregge: forse la storia della finanza Donato gliel'ha detta ieri, al telefono. L'SMS «G.» è di ieri alle 7:12.","lie":true},{"id":"x2","a":"g4","b":"r4","who":"gianni","reply":"(Si copre la faccia.) Soldi. Dal barattolo del caffè, in cucina. Millecinquecento euro, per la rata di settembre. Lo zio non li conta mai. Glieli rimetto, giuro.","insight":"Gianni ammette di aver preso 1.500 euro in contanti dal barattolo del caffè dello zio, l'altro ieri sera.","lie":true}]},{"id":"veggente","title":"La veggente di Polignano","place":"Villa sulla scogliera, Polignano a Mare","teaser":"Una profezia di morte. Tre giorni dopo, la morte.","intro":"«Morirai vicino all'acqua, prima della luna piena.» Madame Serena l'aveva detto a Riccardo Dell'Aquila, 49 anni, durante una seduta a casa sua. Ieri notte, due giorni prima della luna piena, Riccardo è precipitato dalla terrazza sulla scogliera. In paese parlano di maledizione. Tu delle veggenti hai un'opinione precisa.","details":[{"id":"d1","label":"La ringhiera","text":"Ferro battuto, alta un metro e dieci, intatta. Sotto, venti metri di scogliera.","insight":"Ringhiera della terrazza alta 1,10 m, intatta. Sotto, venti metri di scogliera."},{"id":"d2","label":"Due bicchierini","text":"Sul tavolino, due bicchierini di limoncello. Sul fondo di uno, un velo di polvere bianca che il limoncello non ha sciolto.","insight":"Due bicchierini di limoncello in terrazza. Sul fondo di uno, polvere bianca non sciolta."},{"id":"d3","label":"L'home banking","text":"Sul tablet di casa, l'app della banca aperta: bonifico di 3.000 € da Giulia a «S. Lorusso», due settimane fa. Causale: «consulenza».","insight":"Due settimane fa Giulia ha versato 3.000 € a «S. Lorusso». Causale: «consulenza»."},{"id":"d4","label":"Il biglietto della profezia","text":"Scritto a mano dalla veggente: «Acqua. Luna piena. Un tradimento. La lettera R.»","insight":"La profezia scritta da Serena: «Acqua. Luna piena. Un tradimento. La lettera R.»"},{"id":"d5","label":"La polizza","text":"In un cassetto dello studio: polizza vita da 800.000 €, stipulata quattro mesi fa. Beneficiaria: Giulia.","insight":"Polizza vita di Riccardo da 800.000 €, stipulata quattro mesi fa. Beneficiaria: Giulia."},{"id":"d6","label":"I messaggi di Marco","text":"Sul telefono di Riccardo, due messaggi del fratello Marco. Martedì: «Se non mi dai tempo per quei soldi te ne penti.» Ieri, ore 23:52: «Sono sotto casa. Aprimi.»","insight":"Marco a Riccardo, martedì: «Se non mi dai tempo per quei soldi te ne penti.» Ieri alle 23:52: «Sono sotto casa. Aprimi.»"},{"id":"d7","label":"Il flacone in bagno","text":"Sonnifero prescritto a Giulia dieci giorni fa. Confezione da 30 compresse, ne restano 4.","insight":"Sonnifero prescritto a Giulia dieci giorni fa: ne mancano 26 su 30."}],"suspects":[{"id":"serena","name":"Madame Serena","role":"Veggente, al secolo S. Lorusso","look":"Anelli a ogni dito, voce bassa. È venuta a «portare conforto».","tell":"Frasi lasciate a metà, pause lunghe: aspetta un tuo cenno prima di continuare. Quando si parla della scogliera si sfila un anello e lo rimette, tre volte di fila.","questions":[{"id":"v1","q":"Come ha previsto la morte di Riccardo?","a":"Le carte parlano a chi sa ascoltare. Lei, per esempio: ha perso qualcuno di importante, vero? Lo vedo.","aside":"Mentre parla ti guarda le mani, non gli occhi."},{"id":"v2","q":"Da dove viene la R della profezia?","req":["d4"],"a":"Dalle carte!","aside":"Risponde subito. Per un attimo guarda verso il divano, dove sono seduti Giulia e Marco.","insight":"Alla domanda sulla R, Serena risponde «dalle carte» e guarda il divano dove siedono Giulia e Marco."},{"id":"v3","q":"Lei è S. Lorusso. Giulia le ha versato 3.000 euro.","req":["d3"],"a":"Una seduta. Come tutte le altre. Il mio tempo costa, signore mio.","aside":"Si sfila un anello.","insight":"Serena dice che i 3.000 € di Giulia erano il prezzo di una seduta.","lie":true}]},{"id":"giulia","name":"Giulia Dell'Aquila","role":"Moglie, 44 anni","look":"Occhiali scuri in casa. Un fazzoletto stretto in mano, asciutto.","tell":"Occhiali scuri in casa, fazzoletto asciutto in mano. Parla prima delle cose pratiche, poi si ferma e porta il fazzoletto agli occhi. Quando si nomina la profezia appoggia la schiena al divano.","questions":[{"id":"g1","q":"Cosa è successo ieri sera?","a":"Un limoncello in terrazza, noi due, come ogni sera. Alle undici sono andata a letto. Riccardo era sconvolto dalla profezia, non dormiva più. Forse si è buttato. O è caduto.","insight":"Giulia dice: limoncello in terrazza con Riccardo, poi a letto alle 23. Pensa a un suicidio o a una caduta."},{"id":"g2","q":"Mancano 26 sonniferi in dieci giorni.","req":["d7"],"a":"Dormo male. Da mesi. Lo sanno tutti che dormo male.","insight":"Sui 26 sonniferi mancanti Giulia dice solo che dorme male.","lie":true},{"id":"g3","q":"Parliamo della polizza da 800.000 euro.","req":["d5"],"a":"L'ha voluta lui. Io non volevo nemmeno firmare. L'ha voluta lui.","aside":"Ripete l'ultima frase due volte.","insight":"Giulia dice che la polizza l'ha voluta Riccardo."}]},{"id":"marco","name":"Marco Dell'Aquila","role":"Fratello, 45 anni","look":"Tuta da lavoro del porto, arrivato di corsa da Bari.","tell":"Ha ancora il badge del porto appeso al collo. Guarda il pavimento quando si parla di soldi e si asciuga il naso col dorso della mano. Quando si nomina la notte scorsa stringe il badge nel pugno.","questions":[{"id":"k1","q":"Ha minacciato suo fratello.","req":["d6"],"a":"Gli dovevo ventimila euro, gli ho scritto una cosa stupida. Ieri notte ero di turno al porto di Bari, dalle dieci alle sei. Ci sono le timbrature.","insight":"Marco doveva 20.000 € a Riccardo. Dice di essere stato di turno al porto di Bari dalle 22 alle 6, con le timbrature.","lie":true},{"id":"k2","q":"Riccardo credeva alla veggente?","a":"Riccardo? Rideva degli oroscopi. È Giulia che ha voluto portarla in casa. Insisteva.","insight":"Secondo Marco è stata Giulia a volere la veggente in casa. Riccardo rideva degli oroscopi."},{"id":"k3","q":"Com'era il loro matrimonio?","a":"Da un anno dormivano in stanze separate. Lui parlava di separazione.","insight":"Da un anno Riccardo e Giulia dormivano separati. Lui parlava di separazione."}]}],"bluff":{"text":"Annunci che l'autopsia ha già trovato un sedativo nel sangue di Riccardo.","reactions":{"serena":"«Sedativo?» Si siede di colpo e si sfila tutti gli anelli, uno dopo l'altro.","giulia":"«Li prendeva anche lui, ogni tanto, per dormire.» Si toglie gli occhiali e li rimette.","marco":"«Allora qualcuno l'ha aiutato a cadere.» Poi guarda il telefono del fratello sul tavolo."},"insight":"Al bluff del sedativo: Serena si sfila gli anelli, Giulia dice che Riccardo prendeva sonniferi, Marco guarda il telefono del fratello."},"motive":{"options":["Cancellare il debito di ventimila euro col fratello.","Evitare che Riccardo la denunciasse per truffa.","Vendicare un tradimento scoperto in seduta.","Incassare la polizza prima della separazione."],"correct":3},"culprit":"giulia","key":["v3","g2","d2","x1","x3"],"solution":"Giulia ha costruito la maledizione. Ha pagato Serena per una profezia su misura (acqua, luna piena, la R di Riccardo) così che una morte sulla scogliera sembrasse destino, o suicidio. Ieri sera ha versato lei i limoncelli, con dentro le compresse del suo sonnifero. Quando Riccardo si è addormentato l'ha portato alla ringhiera. Il movente: la polizza da 800.000 € e una separazione in arrivo. Serena nascondeva di essere stata pagata per recitare quella profezia: truffatrice, non assassina. Marco nascondeva di aver lasciato il turno per venire a chiedere tempo al fratello: alle 23:52 ha suonato, nessuno ha aperto, ed è tornato a Bari.","contradictions":[{"id":"x1","a":"g1","b":"d2","who":"giulia","reply":"Li ho versati io, come sempre. Ci avrà messo lui qualcosa, per dormire.","aside":"Stringe il fazzoletto.","insight":"Giulia ammette di aver versato lei i due limoncelli.","lie":true},{"id":"x2","a":"k1","b":"d6","who":"marco","reply":"Va bene. Ho timbrato e sono venuto qua in macchina, l'uscita me l'ha timbrata un collega. Volevo chiedergli tempo. Ho suonato dieci minuti, le luci erano spente, nessuno ha aperto. Sono tornato a Bari.","aside":"Stringe il badge nel pugno.","insight":"Marco ammette di aver lasciato il turno ed essere stato sotto casa di Riccardo alle 23:52. Dice che le luci erano spente e nessuno ha aperto.","lie":true},{"id":"x3","a":"v3","b":"k2","who":"serena","reply":"Va bene. Non era una seduta. Mi ha pagata per spaventarlo, diceva che usciva in barca ubriaco. I dettagli me li ha dati lei: l'acqua, la luna piena, la R. Io leggo le carte, non ammazzo la gente.","aside":"Si rimette gli anelli, uno per uno.","insight":"Serena ammette che Giulia l'ha pagata per la profezia e le ha dato i dettagli: acqua, luna piena, la R.","lie":true}]},{"id":"barca-vuota","title":"Mare calmo","place":"Porto vecchio, Gallipoli","teaser":"La barca torna all'alba. Il pescatore no.","intro":"All'alba la «Stella Maris», il gozzo di Cosimo Tarantino, è stata trovata alla deriva vicino all'isola di Sant'Andrea. Motore spento, nessuno a bordo. La capitaneria cerca da sei ore e il porto dà già Cosimo per annegato. Il comandante, che ti deve un favore, ti ha chiesto di dare un'occhiata prima che diventi una tragedia ufficiale.","details":[{"id":"d1","label":"Il motore","text":"Spento. La chiave è girata su OFF e il serbatoio è quasi pieno.","insight":"Motore spento con la chiave su OFF. Serbatoio quasi pieno."},{"id":"d2","label":"Le reti","text":"Piegate a poppa, asciutte. Nemmeno un'alga.","insight":"Reti piegate a poppa, asciutte, senza un'alga."},{"id":"d3","label":"La cima di poppa","text":"A poppa Cosimo teneva legato un canotto gonfiabile. Il canotto non c'è. La cima è stata sciolta, non tagliata né strappata.","insight":"Il canotto di poppa non c'è. La cima è stata sciolta, non tagliata né strappata."},{"id":"d4","label":"La Panda di Dora","text":"Parcheggiata sotto casa. Sul tappetino del guidatore, sabbia bagnata e un filo d'alga. Sul cruscotto, lo scontrino di un distributore self-service di Lido Pizzo: ore 4:21.","insight":"Panda di Dora: sabbia bagnata sul tappetino, scontrino di un distributore di Lido Pizzo delle 4:21."},{"id":"d5","label":"Il telefono di Cosimo","text":"Trovato nella cabina, carico. Ultimo messaggio inviato a Dora alle 3:12: «Mare calmo. Ti voglio bene.»","insight":"Telefono di Cosimo in cabina. Ultimo messaggio a Dora, 3:12: «Mare calmo. Ti voglio bene.»"},{"id":"d6","label":"La cucina di casa","text":"Sul frigo, il portapillole settimanale di Cosimo, per la pressione. Vuoto. Anche la scatola nuova, comprata venerdì, è sparita.","insight":"Il portapillole della pressione di Cosimo è vuoto. Sparita anche la scatola nuova di venerdì."},{"id":"d7","label":"La polizza","text":"Nella credenza: polizza infortuni, morte accidentale in mare, 300.000 euro. Beneficiaria Addolorata Tarantino. Il massimale è stato triplicato a marzo.","insight":"Polizza per morte accidentale in mare: 300.000 € a Dora. Massimale triplicato a marzo."}],"suspects":[{"id":"nando","name":"Nando Scorrano","role":"Grossista di pesce, 60 anni","look":"Stivali di gomma, catena d'oro, un telefono che squilla ogni due minuti. Al porto lo chiamano «la banca».","tell":"Parla di Cosimo sempre al presente: «mi deve», «è uno che». Rifiuta tutte le chiamate tranne una, a cui risponde a monosillabi allontanandosi di qualche passo.","questions":[{"id":"n1","q":"Cosimo le doveva dei soldi.","a":"Quarantamila. Cambiali, scadenza venerdì. E un morto non paga, lo sa? Se lo volevo morto, ero scemo.","insight":"Cosimo doveva 40.000 € in cambiali a Nando, con scadenza venerdì."},{"id":"n2","q":"Dov'era stanotte?","a":"All'asta del mercato ittico, dalle tre e mezza alle sei. Ho comprato sei lotti. C'è il registro, ci sono le telecamere, ci sono cinquanta pescatori.","insight":"Nando dice di essere stato all'asta del pesce dalle 3:30 alle 6, con registro e telecamere."},{"id":"n3","q":"Cosimo le ha detto qualcosa, ultimamente?","a":"Lunedì, al bar, tranquilli. «Venerdì ti pago, Nando. In un modo o nell'altro.» Io non l'ho mai minacciato, eh. Sono un commerciante.","insight":"Nando dice che lunedì Cosimo gli ha promesso di pagare venerdì «in un modo o nell'altro». Dice di non averlo mai minacciato.","lie":true},{"id":"n4","q":"Ha visto il mozzo, ieri?","a":"Ieri sera al bar. Cosimo gli ha passato dei soldi sotto il tavolo, pensavano che non guardassi. Io guardo sempre, quando ci sono soldi.","insight":"Nando dice di aver visto Cosimo passare dei soldi a Samuele sotto il tavolo, ieri sera al bar."}]},{"id":"samuele","name":"Samuele Nuzzo","role":"Mozzo, 19 anni","look":"Felpa col cappuccio, mani screpolate dal sale. Seduto su una bitta da ore, non se ne va.","tell":"Ogni tanto la mano va alla tasca dei jeans e ci resta. Guarda il mare aperto, non la barca. Quando parla di Cosimo la voce gli si rompe, ma non piange.","questions":[{"id":"s1","q":"Perché stanotte non era in barca?","a":"Mi ha scritto a mezzanotte: «Stanotte non venire, esco da solo.» In tre anni non era mai successo.","insight":"A mezzanotte Cosimo ha scritto a Samuele di non venire: usciva da solo. In tre anni mai successo."},{"id":"s2","q":"Cosa tiene in quella tasca?","req":["t_samuele"],"a":"(Tira fuori le banconote e le rimette via.) Soldi miei. Me li sono guadagnati.","aside":"Si tira il cappuccio sulla testa.","insight":"Samuele ha in tasca 200 € in contanti. Dice che sono soldi suoi.","lie":true},{"id":"s3","q":"Com'era Cosimo in barca?","a":"Un maniaco. Il canotto lo legava con tre nodi. E il telefono non se lo portava mai, lo lasciava a casa. Diceva che in mare si sta zitti.","insight":"Secondo Samuele, Cosimo legava il canotto con tre nodi e in mare il telefono non se lo portava mai."},{"id":"s4","q":"Cosimo aveva paura di qualcuno?","a":"Lunedì sera due uomini di Nando sono saliti in barca. L'hanno preso per il collo. «Venerdì, o la barca va a fuoco.» Io ero in cabina, zitto.","insight":"Samuele dice che lunedì due uomini di Nando hanno preso Cosimo per il collo: «Venerdì, o la barca va a fuoco.»"}]},{"id":"dora","name":"Addolorata «Dora» Tarantino","role":"Moglie di Cosimo, 49 anni","look":"Scialle nero, il telefono stretto in mano. Le amiche le fanno cerchio intorno.","tell":"Ha gli occhi gonfi e il trucco rifatto. Quando il telefono vibra guarda lo schermo e lo gira in giù, senza rispondere. All'orlo dei jeans, sotto lo scialle, c'è sabbia umida.","questions":[{"id":"o1","q":"Quando ha sentito suo marito l'ultima volta?","a":"Alle tre e dodici mi ha scritto: «Mare calmo, ti voglio bene.» Io dormivo. L'ho letto alle sei e ho chiamato la capitaneria. Stanotte non sono uscita di casa.","insight":"Dora dice di aver dormito tutta la notte, senza uscire di casa. Il messaggio delle 3:12 l'ha letto alle 6."},{"id":"o2","q":"Le pillole di Cosimo sono sparite, anche la scatola nuova.","req":["d6"],"a":"Le avrò buttate io. Non lo so. Che importanza hanno delle pillole, adesso?","aside":"Gli occhi le vanno alla borsa.","insight":"Sulle pillole sparite Dora dice «le avrò buttate io» e guarda la sua borsa.","lie":true},{"id":"o3","q":"La polizza è stata triplicata a marzo.","req":["d7"],"a":"L'ha voluta lui. Il mare è traditore, diceva sempre. Io non volevo nemmeno firmare.","insight":"Dora dice che la polizza triplicata a marzo l'ha voluta Cosimo."}]}],"contradictions":[{"id":"x1","a":"o1","b":"d4","who":"dora","reply":"Non riuscivo a dormire. Sono andata a guardare il mare, dove va lui. Che c'è di strano?","aside":"Stringe il telefono. Lido Pizzo è a dodici chilometri da casa.","insight":"Dora ammette di essere stata a Lido Pizzo alle 4:21, «a guardare il mare».","lie":true},{"id":"x2","a":"n3","b":"s4","who":"nando","reply":"Gli ho mandato due ragazzi a ricordargli la scadenza. Ricordargli. La barca non l'ha toccata nessuno.","aside":"Il telefono squilla. Lo lascia squillare.","insight":"Nando ammette di aver mandato lunedì due uomini da Cosimo per la scadenza.","lie":true},{"id":"x3","a":"s2","b":"n4","who":"samuele","reply":"Me li ha dati lui, ieri sera. Duecento euro. «Per la settimana che non lavori.» Non l'ho detto a nessuno, sembrava che l'avessi venduto.","aside":"Guarda il mare aperto.","insight":"Samuele ammette che ieri sera Cosimo gli ha dato 200 € «per la settimana che non lavori».","lie":true}],"bluff":{"text":"Annunci che un peschereccio ha ripescato un corpo vicino a Sant'Andrea e che serve qualcuno della famiglia per il riconoscimento.","reactions":{"nando":"«Porca miseria.» Si siede su una cassetta del pesce e tira fuori un taccuino.","samuele":"Diventa bianco. «Non può essere», ripete. «Non può essere.»","dora":"«Vengo io.» Prende la borsa, poi si ferma a guardare il telefono prima di muoversi."},"insight":"Al bluff del corpo: Nando tira fuori un taccuino, Samuele ripete «non può essere», Dora guarda il telefono prima di muoversi."},"motive":{"options":["Far pagare a Cosimo le cambiali scadute, con le cattive.","Incassare la polizza con un finto annegamento e sparire dai debiti.","Prendersi la barca per lavorare in proprio.","Liberarsi di un marito per rifarsi una vita."],"correct":1},"culprit":"dora","key":["x1","o2","o3"],"solution":"Cosimo non è annegato: è scappato, e Dora l'ha aiutato. Con le cambiali di Nando in scadenza, hanno deciso di farlo sparire in mare e incassare la polizza triplicata a marzo. Stanotte Cosimo è uscito da solo, dopo aver pagato in anticipo il mozzo; non ha calato le reti, ha lasciato a bordo il telefono con un messaggio d'addio, ha spento il motore ed è sceso a riva col canotto. Alle 4:21 Dora lo aspettava a Lido Pizzo con la Panda e le sue pillole per la pressione. Nando nascondeva di averlo fatto minacciare lunedì, Samuele i 200 € che Cosimo gli aveva dato «per la settimana che non lavori». Il corpo che cerca la capitaneria sta bene, ed è nascosto a mezz'ora da qui."},{"id":"fornocolonna","title":"Il criscito","place":"Forno Colonna, centro storico di Altamura","teaser":"Alle quattro il pane non esce. Esce solo il fumo.","intro":"Da cent'anni il Forno Colonna accende la legna alle due e mezza di notte. Stamattina, alle quattro, il garzone trova la stanza piena di fumo e Peppino Colonna, 71 anni, seduto accanto al forno, come se dormisse. Per i vigili del fuoco è una disgrazia: canna fumaria sporca. Ma Peppino quella canna la puliva ogni mese, e il paese lo sa.","details":[{"id":"d1","label":"La canna fumaria","text":"La serranda in basso è aperta. Eppure il tiraggio è zero: il fumo di una candela torna indietro.","insight":"La serranda in basso è aperta ma il tiraggio è zero: la canna è ostruita più in alto."},{"id":"d2","label":"Il terrazzo","text":"Si sale dalla scala del palazzo, porta con lucchetto a combinazione. Nel comignolo è infilato un sacco di juta del mulino, annerito. La combinazione la sanno i condomini, Tommaso Colonna e una signora di novant'anni, e Karim, che sale a stendere i grembiuli del forno.","insight":"Il comignolo è tappato con un sacco di juta, dal terrazzo. La combinazione del lucchetto la sanno Tommaso, una vicina di novant'anni e Karim."},{"id":"d3","label":"La bozza del testamento","text":"Nel cassetto della cassa, la bozza di un notaio di Altamura, datata la settimana scorsa: «Il forno e il marchio Colonna a Karim Benali.» Appuntamento per la firma: lunedì.","insight":"Bozza di testamento della settimana scorsa: il forno e il marchio a Karim Benali. Firma prevista lunedì."},{"id":"d4","label":"La madia","text":"Dentro, il criscito: il lievito madre di famiglia, cent'anni. Ha il segno fresco di un cucchiaio: qualcuno stanotte ne ha preso un pezzo.","insight":"Stanotte qualcuno ha preso un pezzo del criscito, il lievito madre di cent'anni."},{"id":"d5","label":"Peppino","text":"Seduto sulla sedia di paglia accanto al forno, il grembiule addosso. La pelle è rosea, quasi colorita.","insight":"Peppino ha la pelle rosea: è il segno dell'avvelenamento da monossido di carbonio."},{"id":"d6","label":"Il preliminare","text":"In una cartellina sotto il bancone: un preliminare di vendita del marchio «Forno Colonna 1921» a un gruppo industriale di Bari. Firmato da Tommaso. Manca la firma del titolare.","insight":"Un preliminare per vendere il marchio a un gruppo industriale di Bari. Firmato da Tommaso; manca la firma di Peppino."},{"id":"d7","label":"Il rilevatore di fumo","text":"Sopra la porta, il rilevatore di monossido. Senza batteria. La batteria è nel cassetto sotto, ancora nuova.","insight":"Il rilevatore di monossido è senza batteria. La batteria, nuova, è nel cassetto sotto."}],"suspects":[{"id":"karim","name":"Karim Benali","role":"Garzone, 24 anni","look":"Felpa infarinata, occhi rossi, il berretto di Peppino stretto in mano.","tell":"Voce roca, occhi che lacrimano. Stringe il berretto di Peppino e non lo molla mai. Il telefono gli vibra in tasca di continuo: lo guarda, rifiuta la chiamata, lo rimette via.","questions":[{"id":"k1","q":"Cosa è successo stanotte?","a":"Alle quattro meno cinque apro, e la stanza è grigia. Peppino sulla sedia, rosso in faccia come se dormisse. L'ho trascinato fuori. Troppo tardi. Il fumo dal camino non usciva, usciva tutto dentro."},{"id":"k2","q":"Peppino le lasciava il forno.","req":["d3"],"a":"Me l'ha detto la settimana scorsa, qui, davanti a Tommaso. Tommaso ha buttato a terra un vassoio di taralli e se n'è andato. Io non volevo niente. Volevo lui.","insight":"Secondo Karim, la settimana scorsa Peppino ha annunciato il testamento davanti a Tommaso, che ha buttato a terra un vassoio."},{"id":"k3","q":"Dov'era prima delle quattro?","a":"In pizzeria a Gravina fino alle due, a pulire. Poi il titolare mi ha dato un passaggio, mi ha lasciato qui davanti alle quattro meno cinque. Può chiamarlo.","insight":"Karim dice di aver lavorato a Gravina fino alle 2, poi un passaggio del titolare fino al forno, alle 3:55.","lie":true}]},{"id":"donato","name":"Donato Mastrangelo","role":"Fornaio rivale, 66 anni","look":"Grembiule ancora addosso, mani screpolate, un taglio fresco sul pollice.","tell":"Arrossisce ogni volta che il suo sguardo cade sulla madia di Peppino. Parla di Peppino con rabbia, ma al presente. Tiene il pollice tagliato chiuso nel pugno.","questions":[{"id":"o1","q":"Dov'era stanotte?","a":"Nel mio forno, qui di fronte, da mezzanotte. Come ogni notte da quarant'anni. Da solo. Di qua non ci metto piede.","insight":"Donato dice di non aver messo piede nel Forno Colonna stanotte."},{"id":"o2","q":"Stanotte qualcuno ha preso un pezzo del criscito.","req":["d4"],"a":"(Diventa viola.) A mezzanotte. La porta di servizio non la chiude nessuno. Il mio lievito muore ogni estate, il suo ha cent'anni... Il forno era freddo, Peppino non c'era ancora. E uscendo, verso mezzanotte e dieci, ho visto una torcia sul terrazzo, sopra il forno. Ho pensato ai ladri. Ladro ero io.","insight":"Donato ammette di aver preso il criscito a mezzanotte. Uscendo, verso le 00:10, ha visto una torcia sul terrazzo sopra il forno.","lie":true},{"id":"o3","q":"Chi ci guadagna dalla morte di Peppino?","a":"Io, dicono. Un concorrente in meno. Ma il marchio Colonna lo voleva l'industria, mica io. E Tommaso con quelli ci andava a pranzo, a Bari. Tutte le settimane.","insight":"Secondo Donato, Tommaso pranzava ogni settimana a Bari con l'industria che voleva il marchio."},{"id":"o4","q":"Ha visto qualcuno arrivare al forno, stanotte?","a":"Alle tre sforno la prima teglia e mi affaccio sempre. La bici di Karim era già legata al palo, qui davanti. Lui seduto sul gradino della chiesa, col telefono in mano. Alle tre, non alle quattro.","insight":"Alle 3 Donato ha visto Karim seduto sul gradino davanti al forno, con la bici già legata al palo."}]},{"id":"tommaso","name":"Tommaso Colonna","role":"Nipote, 38 anni, abita sopra il forno","look":"Camicia pulita, barba fatta, profumo. Alle cinque del mattino.","tell":"Mani curatissime, unghie spazzolate da poco. Sotto l'unghia del pollice destro resta un segno nero. Si è fatto la barba stamattina. Quando si parla del terrazzo si gratta il pollice.","questions":[{"id":"m1","q":"Dov'era stanotte?","a":"A letto, qui sopra. Ho il sonno pesante, non mi sono mai alzato. Mi ha svegliato Karim che urlava.","insight":"Tommaso dice di non essersi mai alzato stanotte."},{"id":"m2","q":"Ha firmato un preliminare per vendere il marchio.","req":["d6"],"a":"Lo zio aveva settantun anni. Prima o poi doveva lasciare. Ci avrebbe ripensato.","aside":"Si liscia la camicia.","insight":"Tommaso conferma il preliminare: «Lo zio prima o poi doveva lasciare.»"},{"id":"m3","q":"Chi erediterà il forno?","a":"Io, credo. Sono l'unico parente. Lo zio di testamenti non ha mai parlato.","insight":"Tommaso dice di non sapere niente di un testamento."},{"id":"m4","q":"Ha del nero sotto l'unghia, e il comignolo è stato tappato dal terrazzo.","req":["d2","t_tommaso"],"a":"Ho pulito il barbecue sul terrazzo. Domenica.","aside":"Mette la mano in tasca.","insight":"Tommaso dice che il nero sotto l'unghia viene dal barbecue sul terrazzo, pulito domenica. Oggi è giovedì.","lie":true}]}],"bluff":{"text":"Annunci che il mulino numera i suoi sacchi e che tra un'ora saprai a chi è stato consegnato quello nel comignolo.","reactions":{"karim":"«I sacchi li scarico io, ogni lunedì. Controllate pure.» Il telefono gli vibra ancora in tasca.","donato":"«Io compro da un altro mulino, da trent'anni. Per principio.» Chiude il pollice nel pugno.","tommaso":"«Quei sacchi vuoti li teniamo tutti sul terrazzo. Ci sale chiunque.»"},"insight":"Al bluff del sacco Karim ha detto di scaricarli lui, Donato di comprare da un altro mulino, Tommaso che i sacchi vuoti stanno sul terrazzo."},"motive":{"options":["Togliere di mezzo il concorrente di sempre.","Prendersi subito il forno che gli era stato promesso.","Evitare che Peppino scoprisse il furto del criscito.","Salvare la vendita del marchio prima che il forno andasse a Karim."],"correct":3},"culprit":"tommaso","key":["x1","m4","o2"],"solution":"Peppino avrebbe firmato lunedì un testamento che lasciava il forno a Karim, e Tommaso aveva già promesso il marchio all'industria. Verso mezzanotte Tommaso sale sul terrazzo e infila un sacco nel comignolo: Donato, che stava rubando il lievito, vede la sua torcia. Toglie anche la batteria al rilevatore. Alle due e mezza Peppino accende la legna, il fumo non esce, e il monossido lo addormenta per sempre. Tommaso si è spazzolato le unghie, ma la fuliggine sotto il pollice è rimasta. Karim sapeva la combinazione, ma a mezzanotte era ancora a Gravina: il titolare l'ha cacciato all'una per cinquanta euro presi dalla cassa, e lui dalle tre aspettava fuori per non doverlo confessare a Peppino. Donato era entrato davvero, ma solo per il criscito.","contradictions":[{"id":"x1","a":"m3","b":"k2","who":"tommaso","reply":"Sì, lo sapevo. Una sparata da vecchio. Non l'avrebbe mai firmato.","aside":"L'appuntamento dal notaio era per lunedì.","insight":"Tommaso ammette di sapere del testamento a favore di Karim: «Non l'avrebbe mai firmato.»","lie":true},{"id":"x2","a":"k3","b":"o4","who":"karim","reply":"(Stringe il berretto.) Il titolare mi ha cacciato all'una. Mi ha visto prendere cinquanta euro dalla cassa. Niente passaggio, sono tornato in bici. Alle tre ero qui, ma non entravo. Come glielo dicevo, a Peppino, che rubavo? Ho aspettato l'ora solita.","aside":"Il telefono vibra. Lui non lo guarda.","insight":"Karim ammette: licenziato all'una a Gravina per 50 € presi dalla cassa. Dalle 3 era seduto davanti al forno, e non è entrato fino alle 3:55.","lie":true}]},{"id":"marpiccolo","title":"Filare sette","place":"Impianto di mitilicoltura, secondo seno del Mar Piccolo, Taranto","teaser":"Un uomo che conosceva ogni palo del Mar Piccolo. Annegato tra i suoi.","intro":"All'alba i colleghi trovano Cataldo Fornaro, 58 anni, impigliato nelle cime del suo impianto di cozze, faccia in giù nell'acqua bassa. La Capitaneria parla di malore e caduta. La figlia dice che suo padre nuotava prima di camminare. Sul molo, mezzo quartiere indica già il vicino con cui litigava da un anno.","details":[{"id":"d1","label":"I polsi di Cataldo","text":"Su tutti e due i polsi, segni rossi a spirale, come di una cima stretta con forza.","insight":"Su tutti e due i polsi di Cataldo, segni rossi a spirale, come di una cima stretta."},{"id":"d2","label":"Le calze del filare 7","text":"Tra le retine bianche di Cataldo, sei calze di cozze avvolte in una retina arancione. Le cozze dentro hanno il guscio nero opaco.","insight":"Sul filare 7, tra le retine bianche, sei calze in retina arancione. Le cozze dentro hanno il guscio nero opaco."},{"id":"d3","label":"L'ordinanza sul pontile","text":"Un foglio plastificato: «Primo seno: vietata la raccolta di mitili per la vendita. Contaminazione.»","insight":"Ordinanza: nel primo seno è vietata la raccolta di mitili per la vendita, per contaminazione."},{"id":"d4","label":"La barca di Cataldo","text":"Una barca a remi, legata al palo del filare 7, nascosta dietro le calze. Dentro, una torcia frontale spenta e un thermos di caffè a metà.","insight":"La barca a remi di Cataldo era legata al palo del filare 7, dietro le calze: torcia frontale spenta, thermos a metà."},{"id":"d5","label":"Il quaderno di bordo","text":"Nella cassetta della barca, grafia grossa: «Filare 7: sei calze arancioni. Non sono mie. Guscio nero, vengono dal primo seno. Stanotte vedo chi viene.»","insight":"Quaderno di Cataldo: sei calze arancioni «non sono mie», guscio nero, «vengono dal primo seno». «Stanotte vedo chi viene.»"},{"id":"d6","label":"La diffida e il confine","text":"Lettera dell'avvocato di Nunzio Blasi: «I pali del suo impianto invadono la concessione del mio assistito per quattro metri.» Sul confine, due pali di Cataldo sono segati a metà, sotto il pelo dell'acqua. Il taglio è chiaro, fresco.","insight":"Nunzio e Cataldo erano in causa per quattro metri di confine. Sul confine, due pali di Cataldo sono segati di fresco."},{"id":"d7","label":"Le mani di Cataldo","text":"Sotto le unghie della mano destra, pelle e sangue. Sulle mani di Cataldo non c'è un graffio.","insight":"Sotto le unghie della mano destra di Cataldo: pelle e sangue. Le sue mani non hanno graffi."}],"suspects":[{"id":"nunzio","name":"Nunzio Blasi","role":"Mitilicoltore, impianto confinante","look":"Maglione sformato, stivaloni fino all'inguine, una voce che si sente dall'altra riva.","tell":"Urla, gesticola, si batte il petto. Si asciuga la fronte con un fazzoletto di carta azzurra, ruvida. Sui polsini del maglione ha trucioli chiari di legno, che si toglie quando vede che li guardi.","questions":[{"id":"n1","q":"Lei e Cataldo eravate in causa. E al bar ha detto che l'avrebbe annegato.","req":["d6"],"a":"Per quattro pali! Sì, l'ho detto. Qui si dice. Stanotte a mezzanotte mia moglie si è sentita male: ho chiamato il 118 alle 00:02 e sono stato al pronto soccorso con lei fino alle sette. C'è il foglio del triage.","insight":"Nunzio ammette la minaccia al bar. Dice: 118 chiamato alle 00:02 per la moglie, al pronto soccorso con lei fino alle sette. Ha il foglio del triage."},{"id":"n2","q":"Ha visto qualcosa ieri sera?","a":"Poco prima di mezzanotte, fumavo sul pontile. Un barchino a motore senza luci andava verso i pali di Cataldo. Fuoribordo piccolo. Cataldo no: lui va a remi, per non sbattere contro i pali.","insight":"Nunzio: poco prima di mezzanotte, dal pontile, ha visto un barchino a motore senza luci andare verso i pali di Cataldo. Cataldo va a remi."},{"id":"n3","q":"Che uomo era Cataldo?","a":"Testardo come un palo. Ma onesto. Troppo, per questo mare."},{"id":"n4","q":"Sul confine due pali di Cataldo sono segati a metà. Taglio fresco.","req":["d6"],"a":"Le mareggiate. Il legno marcisce. (Si guarda i polsini.) Io ho un alibi, gliel'ho detto. Il foglio del triage.","insight":"Nunzio dice che i pali segati sono colpa delle mareggiate e torna a parlare del suo alibi.","lie":true}]},{"id":"carmela","name":"Carmela Fornaro","role":"Figlia di Cataldo, 29 anni","look":"Il giaccone del padre, due taglie più grande. Occhi asciutti, mascella stretta.","tell":"Parla del padre al presente e stringe il giaccone con tutte e due le mani. Il telefono vibra in tasca: lo tira fuori, lo gira a faccia in giù, lo rimette via. Tre volte.","questions":[{"id":"c1","q":"Quando è uscito suo padre?","a":"Alle undici. Ha detto: vado a vedere chi mi ruba il mare. Ha preso la torcia e il thermos, e basta.","insight":"Carmela: il padre è uscito alle 23 con torcia e thermos, dicendo «vado a vedere chi mi ruba il mare»."},{"id":"c2","q":"Queste retine arancioni le conosce?","req":["d2"],"a":"Qui usiamo tutti la bianca. L'arancione la compra solo Rino Caforio, in Grecia, perché costa meno. Ne ha la barca piena.","insight":"Carmela: qui usano tutti la retina bianca; quella arancione la compra solo Rino Caforio, in Grecia."},{"id":"c3","q":"Suo padre aveva nemici?","a":"Nunzio, per i pali. Ma Nunzio abbaia e basta. Da una settimana papà era strano: non dormiva, contava le calze.","insight":"Carmela: da una settimana il padre non dormiva e contava le calze."},{"id":"c4","q":"Chi continua a scriverle?","req":["t_carmela"],"a":"Un'agenzia di Brindisi. (Silenzio.) Volevo vendere la concessione. Ho già firmato un preliminare, papà non lo sapeva. Ieri sera gliel'ho detto e abbiamo urlato. È uscito sbattendo la porta.","insight":"Carmela ha firmato di nascosto un preliminare per vendere la concessione. Ieri sera ha litigato con il padre, poco prima che uscisse.","lie":true}]},{"id":"rino","name":"Rino Caforio","role":"Trasportatore di cozze, 47 anni","look":"Canottiera, braccia da scaricatore. Il suo barchino col fuoribordo è ormeggiato al molo.","tell":"Tiene la mano destra in tasca o sotto l'ascella. Accende una sigaretta con la sinistra. Quando la destra esce, sul dorso ci sono tre graffi dritti, paralleli, ancora gonfi.","questions":[{"id":"r1","q":"Ha mai lavorato sull'impianto di Cataldo?","a":"Mai messo piede. Io carico e porto a Bari, per i grossisti. Coi pali ho chiuso da anni.","insight":"Rino dice di non aver mai messo piede sull'impianto di Cataldo: lui carica e porta a Bari."},{"id":"r2","q":"Dov'era stanotte?","a":"A letto dalle dieci. Alle cinque ero al mercato ittico, chieda a chi vuole.","insight":"Rino dice di essere stato a letto dalle dieci; alle cinque era al mercato ittico."},{"id":"r3","q":"Cataldo ha pelle sotto le unghie. Lei ha tre graffi freschi sulla mano.","req":["d7","t_rino"],"a":"Cozze. Chi lavora le cozze ha le mani a pezzi.","aside":"Tre segni dritti, alla stessa distanza l'uno dall'altro.","insight":"Rino dice che i tre graffi sulla mano sono tagli da cozze.","lie":true},{"id":"r4","q":"Chi ce l'aveva con Cataldo?","a":"Nunzio. Ieri pomeriggio stava sul confine col seghetto, in acqua fino alla cintura. Chieda a lui cosa segava.","insight":"Rino: ieri pomeriggio Nunzio era sul confine con un seghetto, in acqua fino alla cintura."}]}],"bluff":{"text":"Dici che la Capitaneria ha una telecamera termica sul ponte girevole che di notte riprende tutto il Mar Piccolo.","reactions":{"nunzio":"«E allora vedranno che io stavo in ambulanza!» Poi chiede se la telecamera riprende anche di giorno.","carmela":"«Voglio vederlo.» Il telefono vibra; lei non lo guarda.","rino":"Chiede se la termica arriva fino al canale tra il primo e il secondo seno, o si ferma prima."},"insight":"Al bluff della telecamera: Nunzio ha chiesto se riprende anche di giorno; Rino fin dove arriva verso il primo seno."},"culprit":"rino","key":["r3","x1","d7"],"motive":{"options":["Chiudere la causa per i quattro metri di confine","Vendere la concessione senza il padre di mezzo","Vendicarsi della diffida e delle minacce al bar","Continuare a ripulire le cozze del primo seno sul filare 7"],"correct":3},"solution":"Qualcuno spostava di nascosto cozze dal primo seno, dove non si possono vendere, sul filare 7 di Cataldo, per farle «ripulire» e rivenderle come buone. Cataldo se n'è accorto dal guscio nero e stanotte l'ha aspettato al buio, nascosto con la barca a remi. Poco prima di mezzanotte arriva un barchino a motore senza luci, come ha visto Nunzio, e le retine arancioni sono quelle che compra solo Rino. Cataldo lo affronta e gli graffia la mano; Rino lo tiene sott'acqua con una cima e lo lascia impigliato tra i filari. Nunzio aveva minacciato di annegarlo, ma a quell'ora era in ambulanza con la moglie. Nunzio aveva segato di nascosto i pali del confine, e Carmela aveva firmato un preliminare per vendere la concessione: per questo avevano litigato, ma nessuno dei due era in acqua a mezzanotte.","contradictions":[{"id":"x1","a":"r1","b":"c2","who":"rino","reply":"Va bene, le calze sono mie. Da lui crescono meglio e lui non se ne accorgeva. È un furto d'acqua, non un omicidio.","aside":"Si accende un'altra sigaretta con la sinistra.","insight":"Rino ammette che le sei calze arancioni del filare 7 sono sue. Dice che da Cataldo «crescono meglio» e che «lui non se ne accorgeva».","lie":true},{"id":"x2","a":"n4","b":"r4","who":"nunzio","reply":"Va bene, li ho segati io. Ieri alle sei, con la luce. Quattro metri sono miei e il giudice ci mette tre anni. Ma a mezzanotte io ero in ambulanza.","insight":"Nunzio ammette di aver segato ieri pomeriggio i due pali di Cataldo sul confine.","lie":true}]},{"id":"pizzica-palco","title":"Silenzio in piazza","place":"Festival «Luna e Tamburi», Corigliano d'Otranto","teaser":"Cinquemila persone in piazza. Alle 20:50 si spegne tutto.","intro":"Il festival «Luna e Tamburi» aspettava cinquemila persone per la serata finale, con Assunta Rizzo, la voce più amata della pizzica. Alle 20:50, dieci minuti prima dell'inizio, il palco è diventato buio: qualcuno ha tagliato il cavo principale dietro le roulotte degli artisti. Concerto annullato, piazza in rivolta. L'organizzatore giura che è stato il tecnico licenziato due giorni fa. Tu prima vuoi vedere il cavo.","details":[{"id":"d1","label":"Il cavo tagliato","text":"Il cavo di potenza è tagliato netto dietro le roulotte degli artisti, in piena vista. Accanto, nell'erba, delle cesoie da giardino nuove, col cartellino di una ferramenta di Maglie ancora attaccato.","insight":"Cavo tagliato dietro le roulotte degli artisti. Nell'erba, cesoie da giardino nuove col cartellino di una ferramenta di Maglie."},{"id":"d2","label":"Il generatore","text":"Spento con il pulsante d'emergenza, un grosso fungo rosso con la scritta STOP. Sulla plastica rossa, qualche brillantino dorato.","insight":"Generatore spento col fungo rosso d'emergenza. Sulla plastica, brillantini dorati."},{"id":"d3","label":"I bagni chimici","text":"In fila accanto al generatore, dalla parte opposta del palco rispetto alle roulotte.","insight":"I bagni chimici sono accanto al generatore, dalla parte opposta alle roulotte."},{"id":"d4","label":"Il contratto di Assunta","text":"Cachet: 18.000 euro. Clausola 9: se il concerto è annullato per cause tecniche imputabili all'organizzazione, il cachet è dovuto per intero. Clausola 10: se è l'artista a rinunciare, penale di 30.000 euro.","insight":"Contratto di Assunta: con un guasto dell'organizzazione incassa 18.000 € (clausola 9). Se rinuncia lei, paga 30.000 € (clausola 10)."},{"id":"d5","label":"Il foglio delle prevendite","text":"4.800 biglietti venduti su 5.000. Tutti da rimborsare.","insight":"4.800 biglietti venduti su 5.000, tutti da rimborsare."},{"id":"d6","label":"La polizza del festival","text":"Nel furgone della produzione: polizza annullamento evento, scaduta il 30 giugno. Mai rinnovata.","insight":"La polizza annullamento del festival è scaduta il 30 giugno e non è stata rinnovata."},{"id":"d7","label":"La roulotte di Assunta","text":"Spray per la gola, miele, tre thermos d'acqua calda. Sul tavolino, un certificato di un foniatra di Bari, datato martedì: «Noduli alle corde vocali. Riposo vocale assoluto per 15 giorni.»","insight":"Certificato del foniatra, martedì: noduli alle corde vocali, riposo vocale assoluto per 15 giorni."}],"suspects":[{"id":"rino","name":"Rino Calò","role":"Tecnico luci, licenziato due giorni fa","look":"Maglietta nera della crew, tronchese alla cintura per abitudine. Sa di birra.","tell":"Le mani gli tremano un po' e parla troppo forte. Davanti al cavo tagliato fa una smorfia. Ogni tanto guarda verso il furgone della produzione, poi distoglie gli occhi.","questions":[{"id":"r1","q":"Lei ha detto che senza di lei il palco non si accende.","a":"Ho detto che non si accende bene. Mica che lo spegnevo io. Alle nove meno venti ero al bar della piazza, e c'è il video di un amico che lo prova: guardi, 20:41, io con la birra in mano. Da lì non mi sono mosso.","insight":"Rino è in un video al bar della piazza alle 20:41. Dice di non essersi più mosso da lì.","lie":true},{"id":"r2","q":"Il cavo è stato tagliato con delle cesoie nuove.","req":["d1"],"a":"Cesoie da giardino? Io ho questa. (Batte sulla tronchese.) E se lo tagliavo io, lo facevo sotto il palco, dove ci mettevano due ore a trovarlo. Questo l'ha fatto un dilettante, in piena vista, dietro le roulotte degli artisti.","insight":"Rino dice che lui avrebbe usato la tronchese e tagliato sotto il palco, dove non si trova."},{"id":"r3","q":"Perché l'hanno licenziata?","a":"Perché bevo, dice Walter. E perché gli ho detto davanti a tutti che la polizza era scaduta, e lui non voleva sentirselo dire.","insight":"Rino sapeva che la polizza del festival era scaduta, e l'ha detto davanti a tutti."}]},{"id":"assunta","name":"Assunta Rizzo","role":"Cantante, 41 anni","look":"Abito bianco di scena, fazzoletto rosso al collo, trucco di scena dorato. Una tazza fumante sempre in mano.","tell":"Parla sottovoce, conta le parole, quando può annuisce. Quando nomini il concerto annullato non guarda il palco e si tocca la gola.","questions":[{"id":"a1","q":"Dov'era alle 20:45?","a":"In roulotte. A scaldare la voce. Non sono uscita fino al buio.","insight":"Assunta dice di essere rimasta in roulotte fino al blackout."},{"id":"a2","q":"Il foniatra le ha ordinato quindici giorni di silenzio.","req":["d7"],"a":"(Sussurra.) I medici esagerano. Ho cantato con quaranta di febbre, io. Stasera avrei cantato.","aside":"Lo dice in un soffio, pesando ogni sillaba.","insight":"Assunta dice che, noduli o no, stasera avrebbe cantato.","lie":true},{"id":"a3","q":"Il suo contratto le paga il cachet se il concerto salta per un guasto.","req":["d4"],"a":"La clausola nove? Le scrive il mio agente, io non le leggo.","insight":"Assunta dice di non leggere i contratti. Il numero della clausola l'ha detto lei."}]},{"id":"walter","name":"Walter Monaco","role":"Organizzatore del festival, 50 anni","look":"Camicia sudata, due telefoni, un auricolare. Non si è ancora seduto.","tell":"Ti risponde e intanto scrive messaggi. Gli aloni sotto le ascelle crescono. Quando qualcuno dice «rimborsi» o «assicurazione» smette di scrivere per un attimo.","questions":[{"id":"w1","q":"Chi ci guadagna, se il concerto salta?","a":"Nessuno! Io ci perdo tutto: quattromilaottocento biglietti da rimborsare, gli sponsor, i service. È stato Rino, ve lo dico io.","insight":"Walter dice che con l'annullamento perde tutto, e accusa Rino."},{"id":"w2","q":"La polizza del festival è scaduta a giugno.","req":["d6"],"a":"(Abbassa la voce.) Non avevo i soldi per rinnovarla. Se lo sanno gli sponsor, in Puglia non lavoro più. Ma le pare che mi sabotavo da solo, senza assicurazione?","insight":"Walter ammette di non aver rinnovato la polizza e di averlo nascosto agli sponsor.","lie":true},{"id":"w3","q":"Ha visto qualcuno dietro il palco prima del blackout?","a":"Alle nove meno un quarto ho bussato alla roulotte di Assunta per il cambio d'abito. Porta aperta, luce accesa, dentro nessuno. Ho pensato che fosse andata in bagno.","insight":"Walter dice che alle 20:45 la roulotte di Assunta era aperta, con la luce accesa, e vuota."},{"id":"w4","q":"Rino è ripassato di qua, stasera?","a":"Verso le nove meno tredici usciva dal retropalco con un flight case in spalla. L'ho detto ai carabinieri: eccolo, il vostro uomo.","insight":"Walter dice di aver visto Rino uscire dal retropalco con un flight case verso le 20:47."}]}],"contradictions":[{"id":"x1","a":"a1","b":"w3","who":"assunta","reply":"Ero... ai bagni chimici. Due minuti.","aside":"Si guarda le mani.","insight":"Assunta ammette di essere andata ai bagni chimici verso le 20:45.","lie":true},{"id":"x2","a":"r1","b":"w4","who":"rino","reply":"Va bene, sono tornato dietro. Cinque minuti. I radiomicrofoni li ho comprati io, tre anni fa, e Walter non me li ha mai pagati. Me li sono ripresi. Il cavo non l'ho nemmeno visto.","aside":"Guarda il furgone della produzione.","insight":"Rino ammette di essere passato dal retropalco verso le 20:47 e di aver portato via i radiomicrofoni.","lie":true}],"bluff":{"text":"Annunci che da Lecce sta arrivando un generatore di riserva: il cavo si ripara in mezz'ora e il concerto si fa alle dieci.","reactions":{"rino":"«E chi lo monta, voi?» Poi guarda il furgone della produzione.","assunta":"Si porta la mano alla gola. Cerca con gli occhi il suo agente.","walter":"Chiude una telefonata a metà frase. «E il generatore chi lo paga?»"},"insight":"Al bluff del generatore: Rino guarda il furgone, Assunta si tocca la gola e cerca l'agente, Walter chiede chi paga."},"motive":{"options":["Vendicarsi del licenziamento di due giorni fa.","Incassare l'assicurazione sull'annullamento.","Coprire il furto dei radiomicrofoni.","Evitare la penale senza dire di non poter cantare."],"correct":3},"culprit":"assunta","key":["x1","d2","a2"],"solution":"Assunta non poteva cantare: da martedì aveva i noduli e l'ordine di stare zitta per quindici giorni. Rinunciare le sarebbe costato 30.000 euro di penale, mentre un guasto dell'organizzazione gliene faceva incassare 18.000. Ha comprato le cesoie a Maglie, alle 20:45 è uscita dalla roulotte, ha premuto il fungo rosso del generatore lasciandoci i brillantini del trucco di scena e ha tagliato il cavo dietro le roulotte. Rino nascondeva di essere tornato alle 20:47 a prendersi i radiomicrofoni, ma aveva le mani pulite dal trucco. Walter nascondeva agli sponsor la polizza scaduta: senza assicurazione, era l'ultimo ad avere interesse a spegnere il suo palco."},{"id":"scoglimonopoli","title":"Luce d'oro","place":"Cala Pietrabianca, Monopoli","teaser":"Un milione di follower, un tramonto perfetto, un passo indietro.","intro":"Giada Leone, 24 anni, un milione di follower, sta posando sugli scogli di Cala Pietrabianca al tramonto. Fa un passo indietro per la foto e scivola giù per quattro metri. È viva, in coma al Policlinico di Bari. I carabinieri parlano di imprudenza. Ma Giada su quegli scogli ci è cresciuta, e sua madre ti ha chiesto di guardare la troupe.","details":[{"id":"d1","label":"Lo scoglio del set","text":"Sul punto esatto della posa, una chiazza unta e lucida. Profuma di cocco. Il mare lì non arriva nemmeno con la tramontana.","insight":"Sul punto della posa c'è una chiazza unta che profuma di cocco. Il mare lì non arriva."},{"id":"d2","label":"Il video del drone","text":"La caduta ripresa dall'alto. Giada è sola sul bordo, nessuno a meno di trenta metri. Fa un passo indietro e il piede parte come sul ghiaccio.","insight":"Nel video del drone nessuno è a meno di trenta metri da Giada. Il piede le scivola come sul ghiaccio."},{"id":"d3","label":"Il volo delle 11:30","text":"Sulla scheda del drone c'è anche un volo di prova di stamattina. In un angolo, sugli scogli deserti, una donna con un cappello di paglia a tesa larga, accovacciata proprio sul punto della caduta.","insight":"Stamattina alle 11:30 una donna con un cappello di paglia a tesa larga era accovacciata sul punto della caduta."},{"id":"d4","label":"Il cestino del parcheggio","text":"Un flacone di olio abbronzante al cocco, vuoto. Attaccato col nastro, lo scontrino di una farmacia di Monopoli: ore 11:05 di oggi.","insight":"Nel cestino del parcheggio: un flacone vuoto di olio abbronzante al cocco, comprato a Monopoli oggi alle 11:05."},{"id":"d5","label":"Il telefono di Giada","text":"Ultima mail inviata ieri, a un avvocato: «Voglio vedere tutti i contratti che Martina ha firmato a mio nome. Credo che mi rubi.»","insight":"Ieri Giada ha scritto a un avvocato: vuole vedere i contratti firmati da Martina a suo nome. «Credo che mi rubi.»"},{"id":"d6","label":"La storia di Mattia","text":"Uno screenshot girato tra i follower. Storia di Mattia, tre settimane fa, poi cancellata: «Chi ti tocca si fa male. Ricordatelo.»","insight":"Tre settimane fa Mattia ha pubblicato, e poi cancellato: «Chi ti tocca si fa male. Ricordatelo.»"},{"id":"d7","label":"I sandali di Giada","text":"Suola di corda, liscia. Sul tallone destro, una patina unta che profuma di cocco.","insight":"La suola del sandalo destro di Giada è unta e profuma di cocco."}],"suspects":[{"id":"mattia","name":"Mattia Scarcia","role":"Fotografo ed ex fidanzato, 29 anni","look":"Radiocomando del drone ancora al collo, nocche sbucciate.","tell":"Guarda il radiocomando quando nomini Giada. Sulle nocche, croste già scure. Quando si parla della sua storia su Instagram si strofina le nocche col pollice.","questions":[{"id":"m1","q":"Dov'era quando è caduta?","a":"Al radiocomando, trenta metri indietro. Un drone con il vento di stasera non si pilota con una mano. L'ho vista cadere dallo schermo.","insight":"Mattia dice di aver pilotato il drone da trenta metri, a due mani."},{"id":"m2","q":"«Chi ti tocca si fa male.» L'ha scritto lei.","req":["d6"],"a":"Per un tizio che la molestava nei commenti, non per lei! Letta così sembra altro, lo so. Per questo l'ho cancellata.","insight":"Mattia dice che «Chi ti tocca si fa male» era rivolta a un molestatore dei commenti.","lie":true},{"id":"m3","q":"Chi ha scelto il punto dello scatto?","a":"Martina. Io volevo la caletta a nord, la luce è migliore. Lei ha insistito: quello scoglio lì, nessun altro. Non l'ho mai vista insistere su una luce.","insight":"Secondo Mattia, lo scoglio l'ha voluto Martina. Lui preferiva la caletta a nord."}]},{"id":"martina","name":"Martina Fanelli","role":"Manager di Giada, 41 anni","look":"Pelle chiarissima, crema bianca sul naso, cappello di paglia a tesa larga.","tell":"Pelle chiarissima, nessun segno di costume, protezione 50 sul naso. Tiene le braccia all'ombra del cappello. Quando parli di Giada abbassa la tesa.","questions":[{"id":"r1","q":"Quando è arrivata qui?","a":"Alle sette, in macchina con Giada. Prima ero in ufficio a Bari tutto il giorno. Questi scogli li ho visti stasera per la prima volta.","insight":"Martina dice di non essere mai stata sugli scogli prima delle 19."},{"id":"r2","q":"Giada aveva scritto a un avvocato per i suoi contratti.","req":["d5"],"a":"Non ne sapevo niente.","aside":"Abbassa la tesa del cappello.","insight":"Martina dice di non sapere niente dell'avvocato di Giada.","lie":true},{"id":"r3","q":"Chi ha scelto lo scoglio?","a":"Il fotografo. Io mi occupo dei contratti, non della luce.","insight":"Martina dice che il punto l'ha scelto Mattia."}]},{"id":"noemi","name":"Noemi Russo","role":"Truccatrice, 26 anni","look":"Unghie perfette, trousse aperta, un cappello di paglia appeso alla borsa, il telefono sempre in mano.","tell":"Tiene la fotocamera frontale accesa e si guarda nello schermo mentre ti parla. Quando dice «ero accanto alle borse» il pollice scorre verso la galleria video, poi si ferma.","questions":[{"id":"n1","q":"Che olio ha messo a Giada?","a":"Illuminante alla vaniglia, sulle gambe. Sulle piante dei piedi mai, non sono scema. Senta, profuma ancora.","insight":"Noemi dice di aver messo a Giada un illuminante alla vaniglia, solo sulle gambe."},{"id":"n2","q":"Dov'era quando Giada è caduta?","a":"Accanto alle borse, a sistemare i trucchi. Non ho visto niente.","insight":"Noemi dice di essere stata accanto alle borse e di non aver visto niente."},{"id":"n3","q":"Lei non sistemava i trucchi. Si stava filmando.","req":["t_noemi"],"a":"(Arrossisce.) Un video per il mio profilo, col tramonto. Ho duemila follower, lei un milione. Guardi: dietro di me c'è tutta la troupe. Mattia al drone. Martina ferma, sotto il cappello. Quando Giada cade Mattia molla tutto e corre. Martina resta dov'è.","insight":"Nel video di Noemi, quando Giada cade, Mattia molla il drone e corre. Martina resta ferma.","lie":true},{"id":"n4","q":"Com'erano le cose tra Giada e Mattia?","a":"Si erano lasciati. Lei usciva con Dario, uno del lido. Ieri sera, fuori dal lido, Mattia gli ha messo le mani addosso. C'ero io. Giada piangeva.","insight":"Secondo Noemi, ieri sera Mattia ha picchiato Dario, il nuovo ragazzo di Giada."}]}],"bluff":{"text":"Annunci che dal Policlinico hanno chiamato: Giada ha aperto gli occhi e tra poco potrà parlare.","reactions":{"mattia":"«Ha detto qualcosa? Ha parlato di me?» Si alza prima di finire la frase.","noemi":"«Oddio, meno male!» Scrive un messaggio, poi lo cancella.","martina":"Si aggiusta il cappello. «Con una botta così non ricorderà niente, poverina.»"},"insight":"Al bluff del risveglio Mattia ha chiesto se Giada avesse parlato di lui, Martina ha detto che non ricorderà niente, Noemi ha scritto e cancellato un messaggio."},"motive":{"options":["Vendicarsi di Giada, che l'aveva lasciato per un altro.","Fermare Giada prima che l'avvocato leggesse i contratti.","Un video virale della caduta per il proprio profilo.","Impedire che Giada raccontasse del pestaggio di ieri sera."],"correct":1},"culprit":"martina","key":["x1","d4","x2"],"solution":"Giada aveva capito che Martina le rubava sui contratti e aveva chiamato un avvocato. Stamattina Martina compra l'olio al cocco a Monopoli e alle 11:30 va a ungere lo scoglio: il volo di prova del drone la riprende col suo cappello. Una donna che non si abbronza mai non ha altri motivi per comprare olio abbronzante. La sera impone quel punto preciso per la foto, e aspetta. Mattia ieri aveva picchiato il nuovo ragazzo di Giada, ed era per lui la storia minacciosa, ma al momento della caduta pilotava il drone a trenta metri. Noemi si filmava invece di lavorare, e il suo olio sa di vaniglia.","contradictions":[{"id":"x1","a":"r1","b":"d3","who":"martina","reply":"Va bene, sono passata stamattina. Un sopralluogo. Non è un reato.","insight":"Martina ammette di essere stata sugli scogli stamattina, «per un sopralluogo».","lie":true},{"id":"x2","a":"r3","b":"m3","who":"martina","reply":"Ho detto che quello scoglio era carino. Mattia esagera sempre.","insight":"Martina ammette di aver indicato lei quello scoglio: «era carino».","lie":true},{"id":"x3","a":"m2","b":"n4","who":"mattia","reply":"(Si guarda le nocche.) Sì. Dario. Il molestatore, per me, era lui. Ieri gli ho spaccato il labbro, le nocche sono quelle. Se Giada si sveglia non mi vorrà più vedere.","insight":"Mattia ammette di aver picchiato ieri sera Dario, il nuovo ragazzo di Giada. La frase «Chi ti tocca si fa male» era per lui.","lie":true}]},{"id":"rinascita","title":"Rinascere","place":"Eremo delle Querce, Foresta Umbra, Gargano","teaser":"Dieci giorni per rinascere. Chiara non ha finito il terzo.","intro":"Nell'eremo in mezzo alla Foresta Umbra, trenta persone digiunano, meditano e pagano duemila euro a testa per «rinascere» con il Maestro Anael. Stamattina Chiara Ventura, 41 anni, è stata trovata morta nella sua cella: arresto cardiaco, dicono, colpa del digiuno. Il marito ha chiamato te. Il Maestro, quando ti vede, sorride come chi riconosce un collega.","details":[{"id":"d1","label":"La tazza di Chiara","text":"Sul comodino, una tazza di terracotta con il suo nome inciso. Sul fondo, un residuo verde scuro e un frammento di foglia lunga, dura, a punta.","insight":"Nella tazza di Chiara: residuo verde scuro e un frammento di foglia lunga, dura, a punta."},{"id":"d2","label":"Il pentolone della tisana","text":"In sala comune, mezzo pieno. Odore di malva e menta. Tutti gli altri ne hanno bevuto e stanno bene.","insight":"Il pentolone della tisana comune sa di malva e menta. Tutti gli altri ne hanno bevuto e stanno bene."},{"id":"d3","label":"Il giardino delle erbe","text":"Lungo il muro, una siepe di oleandri. Un ramo è spezzato di fresco e la linfa bianca è ancora appiccicosa.","insight":"Nella siepe di oleandri del giardino, un ramo spezzato di fresco: la linfa bianca è ancora appiccicosa."},{"id":"d4","label":"L'atto di donazione","text":"Nella cella di Chiara: la sua casa di Trani donata alla «Comunità Rinascere». Appuntamento dal notaio dopodomani. Non firmato.","insight":"Chiara stava per donare la sua casa di Trani alla Comunità Rinascere: notaio dopodomani, atto non firmato."},{"id":"d5","label":"Il quaderno di Chiara","text":"Conti a matita: «4 ritiri × 30 persone × 2.000 €. Sul conto della comunità ne arriva la metà.» Sotto: «Domani ne parlo con V., prima che col Maestro.»","insight":"Quaderno di Chiara: «4 ritiri × 30 persone × 2.000 €. Sul conto della comunità ne arriva la metà.» «Domani ne parlo con V., prima che col Maestro.»"},{"id":"d6","label":"La bacheca dei turni","text":"«Tisana della sera: Viola. Ognuno prende la sua tazza dal vassoio in sala.»","insight":"Bacheca: tisana della sera a cura di Viola. «Ognuno prende la sua tazza dal vassoio in sala.»"},{"id":"d7","label":"Il registro della meditazione","text":"Meditazione notturna, dalle 22 alle 2. Tredici firme, in testa quella del Maestro. L'ultima, di Viola, è in fondo e con una penna blu: tutte le altre sono nere.","insight":"Meditazione dalle 22 alle 2: tredici firme, la prima del Maestro. L'ultima, di Viola, è in penna blu; le altre sono nere."}],"suspects":[{"id":"viola","name":"Viola Serracchia","role":"Braccio destro del Maestro, 36 anni","look":"Tunica bianca e velo, come tutte le donne dell'eremo. Voce dolcissima. Porta il tè a tutti senza che nessuno lo chieda.","tell":"Tiene le mani nelle maniche larghe della tunica. Quando le tira fuori per sistemarsi il velo, i polpastrelli di pollice e indice destro sono arrossati e lucidi.","questions":[{"id":"v1","q":"Che cosa ha fatto ieri sera?","a":"Alle nove e mezza ho preparato la tisana e ho lasciato il vassoio in sala, come sempre. Ognuno prende la sua tazza. Poi sono andata alla meditazione.","insight":"Viola: alle 21:30 ha preparato la tisana e lasciato il vassoio in sala, dove ognuno prende la sua tazza. Poi è andata alla meditazione."},{"id":"v2","q":"Chiara voleva parlare con «V.» dei soldi della comunità.","req":["d5"],"a":"«V.»? Qui siamo in tre con la V. E io non tocco soldi: i conti li tiene il Maestro.","insight":"Viola: nell'eremo le persone con la V sono tre. Dice di non toccare soldi: i conti li tiene il Maestro."},{"id":"v3","q":"Qualcuno ha spezzato un oleandro stanotte. E lei ha le dita irritate.","req":["d3","t_viola"],"a":"Ortica. Ieri ho pulito l'orto.","aside":"Il rossore è solo sulla punta di pollice e indice destro. Il dorso della mano è liscio.","insight":"Viola dice che il rossore sulle dita è ortica, presa ieri pulendo l'orto.","lie":true},{"id":"v4","q":"Ha visto qualcuno nel corridoio delle celle, ieri sera?","a":"Il marito. Alle dieci e mezza, mentre andavo alla meditazione. Dentro, nel corridoio, non nel parcheggio. Aveva una busta in mano. Io ho visto lui, lui non ha visto me.","insight":"Viola: alle 22:30, andando alla meditazione, ha visto Gabriele dentro l'eremo, nel corridoio delle celle, con una busta in mano."}]},{"id":"anael","name":"Maestro Anael","role":"Guida spirituale, al secolo Aldo Scarpiello","look":"Barba bianca curata, piedi nudi, un sorriso che non arriva agli occhi.","tell":"Voce morbida, pause lunghe, ti tocca il braccio mentre parla. Quando si parla dell'atto di donazione guarda il telefono. Al polso sinistro porta un braccialetto di cuoio sottile, da donna, e lo gira con le dita.","questions":[{"id":"a1","q":"Quel braccialetto da donna al polso?","req":["t_anael"],"a":"(Lo copre con la manica.) Un dono. Tutti mi fanno doni. Io non ne chiedo nessuno.","insight":"Anael porta al polso un braccialetto di cuoio da donna. Dice che è un dono; non dice di chi.","lie":true},{"id":"a2","q":"Chiara stava per donarvi la sua casa.","req":["d4"],"a":"Dopodomani, dal notaio. Capisce perché non avevo nessun motivo di volerla morta? Anzi.","insight":"Anael: con la morte di Chiara la donazione della casa di Trani salta."},{"id":"a3","q":"Chi gestisce i soldi della comunità?","a":"Viola. Io sono una guida, non un ragioniere. Non so nemmeno la password della banca.","insight":"Anael: i soldi della comunità li gestisce Viola. Lui dice di non sapere nemmeno la password della banca."},{"id":"a4","q":"Dov'era stanotte?","a":"In meditazione con dodici anime, dalle dieci alle due. Anche Viola, arrivata un po' tardi. Aveva da sistemare le tazze, credo.","insight":"Anael: in meditazione dalle 22 alle 2 con dodici persone. Viola è arrivata tardi: «doveva sistemare le tazze, credo»."}]},{"id":"gabriele","name":"Gabriele Ferrante","role":"Marito di Chiara, 45 anni","look":"Barba di due giorni, la camicia di ieri, gli occhi rossi.","tell":"Stringe le chiavi della macchina come un rosario. Alza la voce quando parla della comunità, la perde quando parla di Chiara. Le sue scarpe sono sporche di terra, con un filo d'erba nei lacci. Il parcheggio è asfaltato.","questions":[{"id":"g1","q":"Perché era qui?","a":"Per portarmela a casa. Questa gente le aveva preso tutto, ora anche la casa. Ieri sera mi ha detto di no. Ho dormito in macchina nel parcheggio: senza di lei non me ne andavo.","insight":"Gabriele dice di aver passato la notte in macchina nel parcheggio, senza entrare nell'eremo."},{"id":"g2","q":"Dal parcheggio ha visto qualcosa?","a":"Dal parcheggio si vede il corridoio delle celle. Alle dieci e un quarto una donna in tunica, col velo, ha bussato da Chiara con una tazza in mano. È uscita a mani vuote. Da lontano sono tutte uguali.","insight":"Gabriele: alle 22:15 una donna in tunica e velo ha bussato alla cella di Chiara con una tazza ed è uscita a mani vuote."},{"id":"g3","q":"Avevate litigato?","a":"Urlato. L'ultima cosa che le ho detto è «Sei in una setta». Lei ha riso. E non portava più il braccialetto di cuoio che le avevo preso a Matera. In dodici anni non se l'era mai tolto.","insight":"Gabriele: Chiara non portava più il braccialetto di cuoio che lui le aveva regalato a Matera."}]}],"bluff":{"text":"Annunci che sulla tazza di Chiara ci sono impronte che non sono sue, e che stanno per confrontarle.","reactions":{"viola":"«Le tazze le ho lavate io, ieri pomeriggio. Tutte. Le mie impronte ci sono per forza.»","anael":"«Io non tocco le tazze degli altri. Io non tocco niente.» Tira giù la manica sul polso.","gabriele":"Si alza. «Anche le maniglie? Le porte?» Poi si risiede e guarda le chiavi."},"insight":"Al bluff delle impronte: Viola ha detto che le sue ci sono per forza; Anael si è coperto il polso; Gabriele ha chiesto delle maniglie."},"culprit":"viola","key":["x2","v3","x1"],"motive":{"options":["Impedire che la casa di Trani finisse alla comunità","Impedire a Chiara di raccontare dei soldi che sparivano dal conto","Non far scoprire la relazione segreta con Chiara","Gelosia: Chiara aveva un altro uomo nell'eremo"],"correct":1},"solution":"Il Maestro è un venditore di fumo, ma la morte di Chiara gli costava una casa. Era Viola a tenere i soldi della comunità, e se ne teneva metà: Chiara aveva fatto i conti e voleva parlarne con «V.» prima che col Maestro. Ieri sera Viola ha spezzato un ramo di oleandro, lasciandosi la linfa sulle dita, ha messo le foglie nella tazza di Chiara e gliel'ha portata in cella alle 22:15, come ha visto Gabriele dal parcheggio. Poi è andata alla meditazione, in ritardo, e ha firmato per ultima con un'altra penna. La tisana di tutti era innocua: il veleno era solo in quella tazza. Anael nascondeva la relazione con Chiara, e Gabriele di essere entrato di notte fino alla sua porta: due segreti, nessuno dei due con l'oleandro sulle dita.","contradictions":[{"id":"x1","a":"v2","b":"a3","who":"viola","reply":"Va bene, i bonifici li faccio io. Il Maestro non sa accendere un computer. Dieci anni di lavoro gratis: qualcosa mi spettava.","aside":"Guarda le sue dita, poi le rimette nelle maniche.","insight":"Viola ammette che i bonifici della comunità li fa lei. Dice: «Dieci anni di lavoro gratis: qualcosa mi spettava.»","lie":true},{"id":"x2","a":"v1","b":"g2","who":"viola","reply":"Chiara era debole per il digiuno. Le ho portato la tazza in cella, per gentilezza. Non volevo che pensaste male.","aside":"Poco dopo è arrivata alla meditazione, per ultima.","insight":"Viola ammette di aver portato lei la tazza a Chiara in cella, alle 22:15. Dice: per gentilezza, perché era debole.","lie":true},{"id":"x3","a":"g1","b":"v4","who":"gabriele","reply":"Sono entrato dalla cucina. Volevo lasciarle una lettera sotto la porta. Ho sentito che respirava forte, pensavo dormisse. Me ne sono andato. Non l'ho detto perché... perché avrei potuto aprire.","insight":"Gabriele ammette di essere entrato nell'eremo verso le 22:30 e di essere arrivato alla porta di Chiara. Dice che respirava forte e che non ha aperto.","lie":true},{"id":"x4","a":"a1","b":"g3","who":"anael","reply":"(Una pausa lunga.) Me l'ha dato lei. Venerdì notte, nella torre. Ci vedevamo da qualche settimana. Anche un maestro è un uomo. Nessuno qui deve saperlo.","insight":"Anael ammette una relazione segreta con Chiara da qualche settimana. Il braccialetto glielo ha dato lei venerdì notte.","lie":true}]},{"id":"guaritore-nardo","title":"L'acqua di luce","place":"Villa Perrone, Nardò","teaser":"Un guaritore, una bottiglietta benedetta, un morto nel letto.","intro":"Da maggio, ogni martedì, il «Maestro» Elio Fanizza impone le mani a Donato Perrone, 76 anni, diabetico, per novanta euro a bottiglietta. Stamattina Donato è stato trovato morto nel suo letto: coma ipoglicemico, troppa insulina. La figlia ha già chiamato i giornali: «Il ciarlatano ha ucciso mio padre». I ciarlatani li conosci bene. Proprio per questo vuoi guardare prima di dare ragione a qualcuno.","details":[{"id":"d1","label":"La penna d'insulina","text":"Sul comodino. Il selettore è fermo su 40 unità. Sul foglio della terapia attaccato all'armadio, il medico ha scritto: «8 unità la sera».","insight":"Penna d'insulina ferma su 40 unità. La terapia prescrive 8 unità la sera."},{"id":"d2","label":"L'acqua di luce","text":"Una bottiglietta con l'etichetta dorata: «Acqua di luce – 90 €». Dentro: acqua, sale e un rametto di rosmarino.","insight":"L'«acqua di luce» da 90 €: acqua, sale e un rametto di rosmarino."},{"id":"d3","label":"Il volantino del Maestro","text":"In fondo, in piccolo: «Non sospendete né modificate le terapie del vostro medico. Il Maestro affianca, non sostituisce.»","insight":"Volantino del Maestro: «Non sospendete né modificate le terapie del vostro medico.»"},{"id":"d4","label":"Il glucometro","text":"In memoria, due misurazioni di ieri: 20:52, glicemia 190. 22:48, glicemia 176.","insight":"Glucometro, ieri: misurazioni alle 20:52 (190) e alle 22:48 (176)."},{"id":"d5","label":"Il testamento","text":"Nello studio, la bozza di un nuovo testamento, non firmata: la villa e gli uliveti a Rosaria Mazzotta, «per l'affetto e la cura». Un post-it: «Notaio, giovedì ore 10».","insight":"Bozza di testamento non firmata: villa e uliveti a Rosaria. Post-it: «Notaio, giovedì ore 10»."},{"id":"d6","label":"La serratura elettronica","text":"Registro degli ingressi di ieri: 21:02 uscita badge 2. 22:41 ingresso badge 2. 22:58 uscita badge 2.","insight":"Serratura, ieri: badge 2 esce alle 21:02, rientra alle 22:41, esce alle 22:58."},{"id":"d7","label":"Le ricevute","text":"Sei ricevute del Maestro, 250 euro a seduta. Pagate tutte con la carta di Loredana Perrone.","insight":"Sei sedute del Maestro, 250 € l'una, pagate con la carta di Loredana."}],"suspects":[{"id":"elio","name":"Elio Fanizza, «il Maestro»","role":"Guaritore, 58 anni","look":"Camicia di lino bianca, tre braccialetti di legno, voce da radio notturna. Ti ha già toccato il braccio due volte.","tell":"Frasi aperte, pause: aspetta di vedere dove annuisci. Quando si parla della penna d'insulina fa un passo indietro e mette le mani in tasca. Controlla spesso l'orologio.","questions":[{"id":"e1","q":"Cosa ha fatto ieri sera a Donato?","a":"Imposizione delle mani, venti minuti. L'acqua di luce. Alle otto e mezza me ne sono andato, e dalle dieci ero in diretta sulla mia pagina: novanta persone collegate a pregare con me, fino a mezzanotte.","insight":"Il Maestro dice di essere andato via alle 20:30 e di essere stato in diretta dalle 22 a mezzanotte, con novanta persone."},{"id":"e2","q":"La sua acqua di luce è acqua e sale.","req":["d2"],"a":"Acqua, sale, rosmarino. E fede. La fede ce la mette il cliente.","aside":"Non si scompone.","insight":"Il Maestro ammette che la sua acqua è acqua, sale e rosmarino.","lie":true},{"id":"e3","q":"Chi l'ha chiamata in questa casa?","a":"La figlia. Mi ha cercato lei, a maggio: «Papà non crede ai medici, crede a lei.» Strano. Il vecchio a me non credeva per niente. Credeva solo alla badante. A Pasqua le ha comprato un anello, ho visto l'astuccio sul comò.","insight":"Loredana ha portato il Maestro in casa. Donato, dice lui, non gli credeva. A Pasqua Donato ha comprato un anello per Rosaria."}]},{"id":"rosaria","name":"Rosaria Mazzotta","role":"Badante, 53 anni","look":"Occhi gonfi, grembiule ancora addosso. Al dito una fede sottile, nuova.","tell":"Gira la fede col pollice senza accorgersene. Quando parla di Donato dice «lui», mai «il signore». Quando nomini Loredana si irrigidisce e guarda la porta.","questions":[{"id":"b1","q":"Dov'era ieri sera?","a":"Era la mia sera libera. La signora Loredana ha detto che l'insulina delle nove gliela faceva lei, e di andare pure. Ero a Galatone da mia sorella, a cena. Eravamo in dieci.","insight":"Rosaria dice di essere stata a cena a Galatone con dieci persone. L'insulina delle 21 doveva farla Loredana."},{"id":"b2","q":"Di chi è il badge 2?","req":["d6"],"a":"Il badge 1 è il mio, ed era nella mia borsa a Galatone. Il 2 è della signora Loredana. Il 3 era di lui, ma non usciva più di casa.","insight":"Secondo Rosaria il badge 2 è di Loredana. Il suo, il badge 1, era con lei a Galatone."},{"id":"b3","q":"Quella fede è nuova.","req":["t_rosaria"],"a":"Un regalo. Di famiglia.","aside":"Copre l'anello con l'altra mano.","insight":"Rosaria dice che la fede nuova è un regalo di famiglia.","lie":true},{"id":"b4","q":"Ha visto la diretta del Maestro, ieri sera?","a":"Mia sorella la guarda sempre, l'avevamo accesa dopo cena. Strano, però: dietro di lui, dalla finestra, entrava il sole. Alle dieci di sera.","insight":"Rosaria dice che nella diretta del Maestro delle 22, dalla finestra dietro di lui entrava il sole."}]},{"id":"loredana","name":"Loredana Perrone","role":"Figlia di Donato, 47 anni","look":"Tailleur grigio, occhiali da sole in casa. Il telefono sempre in mano: risponde ai giornalisti.","tell":"Occhiali da sole in casa. Parla del padre al passato, senza esitare. Qualunque sia la domanda, la risposta finisce sul Maestro. Quando nomini Rosaria stringe il telefono.","questions":[{"id":"l1","q":"A che ora è andata via ieri sera?","a":"Alle nove, dopo avergli fatto l'insulina. Otto unità, come sempre. Poi a casa mia, a Lecce. Non sono più tornata.","insight":"Loredana dice di essere andata via alle 21, dopo l'insulina, e di non essere più tornata."},{"id":"l2","q":"Il guaritore lo pagava lei.","req":["d7"],"a":"Papà ci credeva, io volevo solo farlo contento. E adesso guardate cosa ha combinato quel ciarlatano.","aside":"Mentre risponde, scrive un messaggio sul telefono.","insight":"Loredana dice di aver pagato il guaritore per far contento il padre.","lie":true},{"id":"l3","q":"Giovedì suo padre lasciava la villa a Rosaria.","req":["d5"],"a":"La villa di mio nonno a una badante? Papà non era più lucido. Quello gli aveva confuso la testa con le sue acque.","insight":"Loredana sapeva del nuovo testamento a favore di Rosaria."}]}],"contradictions":[{"id":"x1","a":"l1","b":"b2","who":"loredana","reply":"Va bene, sono tornata. Avevo dimenticato il caricabatterie. Dieci minuti, papà dormiva.","aside":"Si toglie gli occhiali da sole, poi li rimette.","insight":"Loredana ammette di essere rientrata in villa col badge 2 alle 22:41, «per il caricabatterie».","lie":true},{"id":"x2","a":"e1","b":"b4","who":"elio","reply":"(Sorride.) La diretta la registro il pomeriggio. La gente prega lo stesso. Ieri sera ero a Gallipoli, a cena con una signora. Sposata. Il nome non glielo do.","aside":"Controlla l'orologio.","insight":"Il Maestro ammette che la diretta era registrata. Dice che ieri sera era a cena a Gallipoli con una donna sposata, senza fare il nome.","lie":true},{"id":"x3","a":"b3","b":"e3","who":"rosaria","reply":"Me l'ha data lui, a Pasqua. Ci sposavamo a settembre, in comune, senza feste. Lo sapeva solo il notaio. E forse lei.","aside":"Guarda la porta.","insight":"Rosaria ammette che lei e Donato dovevano sposarsi a settembre.","lie":true}],"bluff":{"text":"Annunci che la penna d'insulina di Donato è di quelle nuove: registra ora e dose di ogni iniezione.","reactions":{"elio":"«Visto? Adesso si vede che io non c'entro.» Poi controlla l'orologio.","rosaria":"Stringe la fede e chiude gli occhi. «Allora sapremo chi.»","loredana":"«La seconda se l'è fatta lui, papà. Si confondeva sempre con le dosi.»"},"insight":"Al bluff della penna: Elio controlla l'orologio, Rosaria stringe la fede, Loredana dice che «la seconda» il padre se l'è fatta da solo."},"motive":{"options":["Tenersi la villa prima che il padre cambiasse il testamento.","Evitare che la famiglia lo denunciasse per truffa.","Incassare prima l'eredità promessa.","Liberarsi di un cliente che voleva smettere di pagare."],"correct":0},"culprit":"loredana","key":["x1","l3","l2"],"solution":"Il ciarlatano era un parafulmine. Loredana ha cercato il Maestro a maggio, quando ha capito che il padre voleva sposare Rosaria e lasciarle la villa, e l'ha pagato lei perché in casa ci fosse un colpevole pronto. Ieri sera ha mandato via Rosaria, è uscita alle 21:02 ed è rientrata alle 22:41 col suo badge. Ha misurato la glicemia al padre addormentato e gli ha iniettato 40 unità; alle 22:58 era già fuori. Il Maestro nascondeva che la sua diretta era registrata, perché ieri sera cenava con una donna sposata: truffatore sì, assassino no. Rosaria nascondeva il matrimonio con Donato, previsto per settembre."},{"id":"paliomurgia","title":"Scirocco non corre","place":"Masseria Pozzo Nuovo, tra Santeramo e Gioia del Colle","teaser":"Il favorito del palio sta morendo nel box. Il cane non ha abbaiato.","intro":"Scirocco è il cavallo da battere al Palio dei Casali, tra sei giorni. Stanotte alle undici la veterinaria lo trova nel box in un bagno di sudore, col cuore che batte a scatti. Vivrà, forse. Correre, mai. Il proprietario ha un nome in testa, quello del suo rivale, e ti ha chiamato per sentirselo confermare.","details":[{"id":"d1","label":"La mangiatoia","text":"Nella biada, frammenti di foglie verdi, lunghe e coriacee, sminuzzate a mano. Oleandro.","insight":"Nella biada di Scirocco: foglie di oleandro sminuzzate a mano."},{"id":"d2","label":"La siepe","text":"Lungo il viale d'ingresso, la siepe di oleandri ha rami strappati di fresco. Strappati, non tagliati. Il lattice bianco è ancora appiccicoso.","insight":"Rami di oleandro strappati a mano poche ore fa. Il lattice bianco dell'oleandro irrita la pelle."},{"id":"d3","label":"Il cancello elettrico","text":"La memoria registra: «20:47 apertura, telecomando n. 3 (fantino)». «21:12 uscita, telecomando n. 3.»","insight":"Ieri sera il cancello si è aperto alle 20:47 col telecomando n. 3, quello del fantino. Uscita alle 21:12."},{"id":"d4","label":"Il cane","text":"Brigante, pastore maremmano, abbaia a chiunque non sia di casa. Il custode giura che ieri sera non ha fatto un verso.","insight":"Brigante abbaia a chiunque non sia di casa. Ieri sera, secondo il custode, non ha fatto un verso."},{"id":"d5","label":"Il biglietto del padrone","text":"Sulla bacheca della selleria, datato ieri: «Enzo, grazie di tutto. Al palio Scirocco lo monta il ragazzo.»","insight":"Ieri il padrone ha scritto a Enzo: al palio Scirocco lo monta «il ragazzo»."},{"id":"d6","label":"L'armadietto della veterinaria","text":"Siringhe usate, un flacone di cortisone quasi finito. Nel registro dei trattamenti di Scirocco mancano due pagine, strappate.","insight":"Nell'armadietto della veterinaria: siringhe e cortisone quasi finito. Dal registro di Scirocco mancano due pagine, strappate."},{"id":"d7","label":"Il fango del paddock","text":"Impronte fresche verso il box: stivaletti piccoli, numero 39, con la suola liscia da equitazione.","insight":"Impronte fresche verso il box: numero 39, suola liscia da stivaletto."}],"suspects":[{"id":"enzo","name":"Enzo Cassano","role":"Fantino, 31 anni","look":"Piccolo e asciutto, stivaletti da monta lucidi, guanti infilati in tasca.","tell":"Si strofina i palmi sui calzoni di continuo. Sono arrossati, con vesciche piccole come chicchi di riso. Ha i guanti da monta in tasca e non se li mette, anche se fa freddo.","questions":[{"id":"e1","q":"Dov'era ieri sera?","a":"A Santeramo, a cena con gli amici, dalle otto a mezzanotte. In scuderia non ci ho messo piede.","insight":"Enzo dice di essere stato a cena a Santeramo dalle 20 a mezzanotte, mai in scuderia."},{"id":"e2","q":"Ieri le hanno tolto Scirocco.","req":["d5"],"a":"Il padrone è libero. Ci sono altri cavalli, altri palii. Io sono giovane.","aside":"Sorride. Il sorriso si ferma sotto gli occhi.","insight":"Enzo dice che perdere Scirocco non conta: «ci sono altri palii»."},{"id":"e3","q":"Ha i palmi pieni di vesciche. Il lattice dell'oleandro fa così.","req":["d2","t_enzo"],"a":"Le redini. Sono un fantino, cosa si aspetta?","aside":"Si infila le mani in tasca, sopra i guanti.","insight":"Enzo dice che le vesciche sui palmi sono delle redini.","lie":true}]},{"id":"gino","name":"Gino Pastore","role":"Allevatore rivale, 58 anni","look":"Due metri di uomo, scarpe numero 46, voce che riempie il cortile.","tell":"Urla, gesticola, ti punta il dito addosso. Quando parla di Scirocco malato abbassa la voce e chiede come respira. Ogni tanto guarda verso la casetta del custode.","questions":[{"id":"g1","q":"In piazza ha detto che Scirocco al palio non ci arriva.","a":"Intendevo che lo battevo io, con Tramontana! Ieri sera ero alla fiera di Foggia, col camion e due puledri. Rientrato alle due. C'è la ricevuta del casello.","insight":"Gino dice di essere stato alla fiera di Foggia, rientro alle due. Ha la ricevuta del casello."},{"id":"g2","q":"Come funzionano le cose al palio?","a":"Male. I fantini si comprano. I rioni non pagano per vincere, pagano per far perdere gli altri. E quest'anno il rione Borgo ha soldi da buttare e paura di Scirocco.","insight":"Secondo Gino al palio i rioni pagano i fantini per far perdere gli altri, e il rione Borgo ha paura di Scirocco."},{"id":"g3","q":"Il cane della masseria non ha abbaiato.","req":["d4"],"a":"Brigante? Quello a me mi mangia vivo. L'anno scorso mi ha strappato un pantalone qui al cancello. Chiedete al custode.","insight":"Secondo Gino, Brigante gli abbaia sempre: l'anno scorso gli ha strappato i pantaloni al cancello."},{"id":"g4","q":"Conosce il custode della masseria?","a":"Come tutti. Buongiorno e buonasera. Che c'entra il custode?","insight":"Gino dice di conoscere il custode solo di vista.","lie":true}]},{"id":"anna","name":"Anna Mele","role":"Veterinaria, 45 anni","look":"Stivaletti infangati, camice sporco, stetoscopio in tasca. Non dorme da ieri.","tell":"Risponde con precisione su tutto. Quando si parla della zampa posteriore di Scirocco diventa vaga e si guarda le mani. Sta appoggiata con la schiena al suo armadietto.","questions":[{"id":"v1","q":"Come sta Scirocco?","a":"Vivo, per ora. Il cuore batte a scatti. Al palio non ci va, questo è sicuro."},{"id":"v2","q":"Cortisone, e due pagine strappate dal registro.","req":["d6"],"a":"Un'infiammazione al garretto. Il padrone non voleva che si sapesse prima del palio, perdeva valore. Le pagine le ho strappate io. Ma il cortisone non avvelena nessuno, e io quel cavallo lo curo da quando è nato.","insight":"Anna ammette di aver strappato lei le pagine: una cura al garretto tenuta nascosta, dice, su richiesta del padrone.","lie":true},{"id":"v3","q":"Chi dà la biada la sera?","a":"L'artiere, alle sei in punto. Dopo quell'ora nessuno ha motivo di toccare la mangiatoia. Le foglie ce le ha messe qualcuno dopo le sei.","insight":"Secondo Anna la biada si dà alle 18: l'oleandro è stato aggiunto dopo."},{"id":"v4","q":"Chi gira per la masseria, oltre a voi?","a":"Il custode. Stamattina l'ho visto dietro la stalla contare banconote, dopo una telefonata. Sullo schermo c'era scritto «Pastore». Ho fatto finta di niente.","insight":"Stamattina Anna ha visto il custode contare banconote dopo una telefonata di «Pastore»."}]}],"bluff":{"text":"Annunci che il rione Borgo ha già ammesso di aver pagato un fantino per questo palio.","reactions":{"enzo":"«Quale fantino? A palio siamo dieci.» Poi chiede, piano, se il Borgo ha fatto dei nomi.","gino":"«Era ora! Lo dico da vent'anni!» Poi guarda verso la casetta del custode.","anna":"«Io di rioni non so niente. Io curo cavalli.» Chiude a chiave l'armadietto."},"insight":"Al bluff sul rione Borgo Enzo ha chiesto se sono stati fatti nomi, Gino ha guardato verso la casetta del custode, Anna ha chiuso a chiave l'armadietto."},"motive":{"options":["Far vincere Tramontana togliendo di mezzo il favorito.","Nascondere le cure al garretto prima del palio.","Rispettare il patto col rione Borgo dopo aver perso la monta.","Far crollare il prezzo di Scirocco per comprarlo."],"correct":2},"culprit":"enzo","key":["x1","e3","d7"],"solution":"Il rione Borgo aveva pagato Enzo per far perdere Scirocco. Ieri il padrone gli toglie la monta: Enzo non può più perdere apposta, e il patto salta. Allora toglie di mezzo il cavallo. Alle 20:47 entra col suo telecomando, il cane lo conosce e tace, strappa l'oleandro a mani nude e lo mescola alla biada. Le vesciche sui palmi, lui che monta coi guanti, e gli stivaletti del 39 nel fango lo tradiscono. Gino, il rivale che tutti accusano, pagava il custode per spiare gli allenamenti di Scirocco, ma ieri sera era a Foggia e Brigante non lo sopporta. Anna nascondeva solo un garretto infiammato, per conto del padrone.","contradictions":[{"id":"x1","a":"e1","b":"d3","who":"enzo","reply":"Sono passato a salutarlo. Dieci minuti. Era il mio cavallo, no?","aside":"Venticinque minuti, dice il cancello.","insight":"Enzo ammette di essere entrato in scuderia ieri sera alle 20:47, «a salutare il cavallo».","lie":true},{"id":"x2","a":"g4","b":"v4","who":"gino","reply":"(Abbassa la voce, per una volta.) Va bene. Pago il custode da un mese. Mi dice i tempi di Scirocco agli allenamenti, e cosa mangia. Al palio si fa così. Ma io i cavalli li compro, non li avveleno.","insight":"Gino ammette di pagare il custode da un mese per avere i tempi e la dieta di Scirocco.","lie":true}]},{"id":"ulivetolisi","title":"Cenere d'ulivo","place":"Uliveto dei Lisi, campagne tra Ostuni e Carovigno","teaser":"Quaranta ulivi di cinquecento anni. Una notte sola per bruciarli.","intro":"Alle due di notte l'uliveto dei Lisi ha preso fuoco: quaranta ulivi monumentali, alcuni piantati prima della scoperta dell'America. Tutti guardano il pastore del terreno accanto, che ieri bruciava le stoppie e con i Lisi litiga da anni. L'assicurazione ti ha chiesto di dare un'occhiata prima di pagare seicentomila euro. Tu tocchi una foglia rimasta sui rami alti, e si sbriciola.","details":[{"id":"d1","label":"I rami alti","text":"I tronchi sono cavi e neri. Ma sui rami alti che il fuoco non ha raggiunto, le foglie sono color ruggine, arricciate, secche da mesi.","insight":"Sui rami alti che il fuoco non ha raggiunto, le foglie sono color ruggine, arricciate, secche da mesi."},{"id":"d2","label":"La tanica nel canale","text":"Nel canale di scolo, una tanica verde da cinque litri col tappo rosso. Odore di miscela per motosega.","insight":"Nel canale di scolo: una tanica verde da cinque litri, tappo rosso, odore di miscela per motosega."},{"id":"d3","label":"La polizza","text":"Stipulata ad aprile: 600.000 euro per quaranta ulivi monumentali «in ottimo stato vegetativo». Firmata da Vito Lisi, per conto dello zio. Allegata, la perizia dell'agronomo Sgobba.","insight":"Polizza di aprile: 600.000 euro per quaranta ulivi «in ottimo stato vegetativo». Firmata da Vito per conto dello zio. Allegata la perizia dell'agronomo Sgobba."},{"id":"d4","label":"Le stoppie del pastore","text":"Il campo accanto ha le stoppie bruciate. Il fuoco si è fermato alla fascia arata lungo il muretto. Oltre, un metro d'erba secca intatta. L'uliveto comincia dopo.","insight":"Le stoppie bruciate del pastore si fermano alla fascia arata lungo il muretto. Oltre c'è un metro d'erba secca intatta, poi l'uliveto."},{"id":"d5","label":"Il capanno degli attrezzi","text":"Nel capanno di Vito, la motosega col serbatoio vuoto. Sullo scaffale, nella polvere, il segno pulito e rettangolare di una tanica che non c'è più.","insight":"Nel capanno di Vito: la motosega col serbatoio vuoto e, nella polvere dello scaffale, il segno rettangolare di una tanica che non c'è."},{"id":"d6","label":"La lettera della Regione","text":"«Monitoraggio Xylella: sopralluogo previsto per il 15 del mese prossimo. In caso di positività, abbattimento obbligatorio.»","insight":"Regione: sopralluogo Xylella il 15 del mese prossimo. Se positivi, abbattimento obbligatorio."},{"id":"d7","label":"Le foto della perizia","text":"Ulivi verdi, rigogliosi, carichi di olive. In una foto, appeso a un tronco, un cartello scritto a mano: «Vendesi olio nuovo 2019».","insight":"In una foto della perizia, appeso a un tronco, un cartello: «Vendesi olio nuovo 2019»."}],"suspects":[{"id":"tommaso","name":"Tommaso Carrieri","role":"Pastore, terreno confinante","look":"Barba incolta, bastone di ulivo, odore di stalla. Ieri pomeriggio ha bruciato le stoppie.","tell":"Risponde a monosillabi e guarda in faccia. Sulle maniche ha sangue secco e paglia. Dietro di lui, sotto la tettoia della stalla, una catasta di ciocchi d'ulivo coi tagli chiari. Quando la guardi, si sposta davanti.","questions":[{"id":"p1","q":"Dov'era stanotte?","a":"Nella stalla. Una pecora non riusciva a partorire. Ho chiamato il veterinario alle due, è rimasto fino alle quattro. Le stoppie le avevo spente alle sei di ieri, col permesso del Comune.","insight":"Tommaso: dalle 2 alle 4 in stalla col veterinario, per una pecora che non riusciva a partorire. Stoppie spente alle 18 di ieri, col permesso del Comune."},{"id":"p2","q":"Che rapporti aveva con i Lisi?","a":"Col vecchio buoni. Col nipote no: mi ha denunciato due volte per le pecore nell'uliveto. Ma là dentro da due anni non c'era più niente da mangiare. Erba secca e alberi morti.","insight":"Tommaso: il nipote Lisi l'ha denunciato due volte per le pecore nell'uliveto. Dice che là dentro da due anni ci sono solo erba secca e alberi morti."},{"id":"p3","q":"Ha visto qualcuno stanotte?","a":"Verso l'una e mezza, andando alla stalla. Fari sulla stradina dell'uliveto, poi spenti a metà. Il pick-up bianco dei Lisi: lo riconosco dal rumore, ha la marmitta rotta da un anno.","insight":"Tommaso: verso l'1:30, fari sulla stradina dell'uliveto, poi spenti a metà. Riconosce il pick-up bianco dei Lisi dalla marmitta rotta."},{"id":"p4","q":"Da dove viene quella legna d'ulivo sotto la tettoia?","req":["t_tommaso"],"a":"Da un amico di Carovigno. (Guarda l'uliveto nero.) Legna è legna.","insight":"Tommaso dice che la catasta di legna d'ulivo gliel'ha data un amico di Carovigno.","lie":true}]},{"id":"vito","name":"Vito Lisi","role":"Nipote del proprietario, gestisce i terreni","look":"Camicia bianca, occhiali da sole in testa, pick-up bianco parcheggiato sulla strada.","tell":"Tiene le mani in tasca. Quando le tira fuori per indicare il pastore, sul dorso della destra i peli sono crespi e arricciati. Ripete «sani» ogni volta che parla degli ulivi.","questions":[{"id":"l1","q":"Dov'era stanotte?","a":"A casa, a Ostuni. Dormivo. Mi hanno svegliato i pompieri alle tre.","insight":"Vito dice di essere stato a casa a Ostuni, a dormire, finché i pompieri l'hanno svegliato alle tre."},{"id":"l2","q":"Com'erano gli ulivi?","a":"Sani! Monumenti. Mio nonno ci faceva l'olio migliore della contrada. Adesso è tutto cenere, per colpa di quello e delle sue stoppie.","insight":"Vito: gli ulivi erano sani, «monumenti». Dà la colpa alle stoppie del pastore."},{"id":"l3","q":"Dal suo capanno manca una tanica. E lei ha la mano bruciacchiata.","req":["d5","t_vito"],"a":"Ho acceso il barbecue, domenica. Una fiammata.","aside":"Domenica era quattro giorni fa.","insight":"Vito dice di essersi bruciato la mano domenica, accendendo il barbecue.","lie":true},{"id":"l4","q":"La Regione doveva controllare la Xylella tra un mese.","req":["d6"],"a":"Controlli di routine. Quegli alberi erano sani.","insight":"Vito sapeva del sopralluogo Xylella della Regione. Lo chiama «controllo di routine»."}]},{"id":"sgobba","name":"Enrico Sgobba","role":"Agronomo, autore della perizia","look":"Gilet con dieci tasche, occhiali spessi, una cartellina stretta al petto.","tell":"Si toglie gli occhiali e li pulisce ogni volta che la domanda si avvicina alla perizia. Sudore sul labbro. Stringe la cartellina al petto.","questions":[{"id":"e1","q":"Com'erano gli ulivi ad aprile?","a":"Sani. Esemplari monumentali. La perizia l'ho firmata io.","insight":"Sgobba dice che ad aprile gli ulivi erano sani, esemplari monumentali. La perizia è firmata da lui."},{"id":"e2","q":"In una foto della sua perizia c'è un cartello del 2019.","req":["d7"],"a":"(Pulisce gli occhiali a lungo.) Le foto me le ha date Vito. Quel giorno non sono andato. Mi ha pagato il doppio per fare in fretta. Non pensavo che...","insight":"Sgobba ammette di non essere andato all'uliveto ad aprile: ha usato foto date da Vito, pagato il doppio per fare in fretta.","lie":true},{"id":"e3","q":"Chi le ha chiesto la perizia?","a":"Vito. Lo zio non ne sapeva niente. «Non facciamolo preoccupare», diceva.","insight":"Sgobba: la perizia l'ha chiesta Vito. Lo zio non ne sapeva niente."},{"id":"e4","q":"Qualcun altro sapeva com'erano davvero quegli ulivi?","a":"Il pastore. Vito mi ha detto che da un anno gli taglia i rami di notte e se li vende come legna da camino. Voleva denunciarlo. Poi ha lasciato perdere.","insight":"Sgobba riferisce che, secondo Vito, Tommaso da un anno tagliava di notte i rami dell'uliveto per venderli. Vito non l'ha denunciato."}]}],"bluff":{"text":"Dici che ad agosto la Regione aveva già prelevato di nascosto un campione di rami dall'uliveto, e che i risultati arrivano domani.","reactions":{"tommaso":"«Allora vedrete che erano morti. Lo sa tutta la contrada.» Poi guarda la catasta sotto la tettoia.","vito":"«Ad agosto? E chi li ha fatti entrare? Il terreno è privato.» Poi: «Comunque erano sani.»","sgobba":"Si toglie gli occhiali. «Ad agosto? Nessuno mi ha avvisato.» Li pulisce a lungo."},"insight":"Al bluff delle analisi: Tommaso ha guardato la sua legna; Vito ha chiesto chi fosse entrato nel terreno; Sgobba ha detto che nessuno l'aveva avvisato."},"culprit":"vito","key":["x1","l3","x2"],"motive":{"options":["Vendicarsi delle due denunce per le pecore","Coprire i furti di legna nell'uliveto","Incassare la polizza prima che la Regione certificasse la Xylella","Far sparire le prove di una perizia firmata senza sopralluogo"],"correct":2},"solution":"Gli ulivi erano morti di Xylella da due anni, come dicono le foglie secche sui rami alti e come sa tutta la contrada. Ad aprile Vito li ha assicurati per 600.000 euro con una perizia fatta su foto vecchie, all'insaputa dello zio. Tra un mese la Regione avrebbe certificato l'infezione e la polizza non sarebbe valsa niente. Così all'1:30 Vito arriva col pick-up a fari spenti, versa la miscela della sua motosega e appicca il fuoco, bruciandosi la mano. Le stoppie di Tommaso si erano spente alla fascia arata, e alle due lui era in stalla col veterinario. Tommaso nascondeva la legna rubata dai rami secchi, e Sgobba una perizia firmata senza mai mettere piede nell'uliveto.","contradictions":[{"id":"x1","a":"l1","b":"p3","who":"vito","reply":"Sono passato a controllare. Rubano la legna degli ulivi vecchi, lo sanno tutti. Cinque minuti e sono tornato a casa.","aside":"Cinque minuti all'una e mezza. Il fuoco è partito alle due.","insight":"Vito ammette di essere stato all'uliveto all'1:30 col pick-up. Dice: un controllo di cinque minuti contro i ladri di legna.","lie":true},{"id":"x2","a":"l2","b":"e2","who":"vito","reply":"Le foto erano belle. Gli alberi erano quelli. Che differenza fa l'anno?","insight":"Vito ammette che le foto della perizia erano di anni prima. Dice: «Gli alberi erano quelli.»","lie":true},{"id":"x3","a":"p4","b":"e4","who":"tommaso","reply":"I rami secchi, sì. Li taglio da un anno, tanto erano morti. Il fuoco mi ha solo levato la legna di quest'inverno. E alle due io avevo le mani dentro una pecora.","insight":"Tommaso ammette di tagliare da un anno, di notte, i rami dell'uliveto dei Lisi.","lie":true}]},{"id":"otranto-recensione","title":"L'ultima recensione","place":"Dimora dei Sette Archi, Otranto","teaser":"Un ispettore di guide che non perdonava. Stanotte non ha fatto in tempo.","intro":"Fabrizio Landi scriveva per la Guida dei Cento Cortili, e mezzo sud tremava alle sue visite. Stamattina la cameriera l'ha trovato morto nella sua suite della Dimora dei Sette Archi: shock anafilattico. Era gravemente allergico alla frutta a guscio e girava sempre con l'adrenalina in tasca. Stanotte non l'aveva. La titolare, che ieri sera ci ha litigato davanti a tutti, ti ha chiamato prima che arrivino i giornali.","details":[{"id":"d1","label":"La giacca di Landi","text":"Sulla sedia della suite. Il taschino interno è deformato dalla sagoma di una penna d'adrenalina. È vuoto.","insight":"Giacca di Landi nella suite: il taschino interno ha la sagoma di una penna d'adrenalina ed è vuoto."},{"id":"d2","label":"I bicchierini sul terrazzo","text":"Due bicchierini da amaro sul tavolino d'angolo. In uno, un fondo scuro e denso che sa di mallo di noce.","insight":"Due bicchierini sul terrazzo. In uno, un fondo scuro che sa di mallo di noce."},{"id":"d3","label":"Il carrello del bar","text":"Amari della casa, tutti con l'etichetta della Dimora. Nessun nocino. Sotto il carrello, il tappo a vite di una mignon: «Nocino della Nonna – Vignola (MO)».","insight":"Sul carrello del bar nessun nocino. Sotto, il tappo di una mignon: «Nocino della Nonna – Vignola (MO)»."},{"id":"d4","label":"La cartella di Landi","text":"Fascicoli con nomi e cifre. «Carluccio – 15.000 – entro sabato.» Più sotto: «L.O. – foto 2019 – pagato tre volte. La quarta a Otranto.»","insight":"Cartella di Landi: «Carluccio – 15.000 – entro sabato.» «L.O. – foto 2019 – pagato tre volte. La quarta a Otranto.»"},{"id":"d5","label":"La telecamera della reception","text":"Registrazione dalle 23 all'1:10: Ottavia al bancone, sempre inquadrata. Un check-in tardivo, poi i conti.","insight":"Telecamera della reception: Ottavia è inquadrata al bancone dalle 23 all'1:10."},{"id":"d6","label":"La cucina","text":"Appeso sopra i fuochi, il menu scritto a mano dallo chef: «Tavolo 4 – ALLERGIA GRAVE FRUTTA A GUSCIO». Ogni piatto spuntato due volte. In fondo al frigo, una vaschetta di pasta di mandorle aperta ieri.","insight":"In cucina: menu del tavolo 4 con l'allergia, ogni piatto spuntato due volte. Nel frigo, pasta di mandorle aperta ieri."},{"id":"d7","label":"La vasca delle ninfee","text":"Nel cortile. Ci danno tre finestre del piano terra: la camera 2, la camera 3 e lo spogliatoio della cucina. Sul fondo, tra le radici, una penna d'adrenalina ancora sigillata.","insight":"Nella vasca del cortile, una penna d'adrenalina sigillata. Sulla vasca danno la camera 2, la camera 3 e lo spogliatoio della cucina."}],"suspects":[{"id":"livia","name":"Livia Orsini","role":"Ospite della Dimora, 42 anni","look":"Camicetta stirata di fresco, capelli raccolti, accento emiliano. Ha chiesto un caffè e non l'ha toccato.","tell":"Parlando del morto lo chiama «Fabrizio». Ha le unghie mangiate fino alla carne e chiude le mani quando la guardi. Il caffè davanti a lei si raffredda.","questions":[{"id":"v1","q":"Conosceva Landi?","a":"No. L'ho visto ieri a cena per la prima volta. Un amaro in terrazza, due chiacchiere, e alle dodici meno un quarto ero a letto.","insight":"Livia dice di aver conosciuto Landi ieri a cena, e di essere andata a letto alle 23:45."},{"id":"v2","q":"Nella cartella di Landi c'è una «L.O.» che paga dal 2019.","req":["d4"],"a":"Ci saranno mille persone con quelle iniziali, in Italia.","aside":"Risponde prima che tu finisca la frase.","insight":"Sulla sigla «L.O.» della cartella, Livia dice che ci sono mille persone con quelle iniziali.","lie":true},{"id":"v3","q":"Cosa avete bevuto in terrazza?","req":["d2"],"a":"Un amaro della casa. L'ha versato lui, dal carrello.","insight":"Livia dice che in terrazza hanno bevuto un amaro della casa, versato da Landi dal carrello."}]},{"id":"ottavia","name":"Ottavia Carluccio","role":"Titolare della Dimora, 55 anni","look":"Lino bianco, voce ferma, occhi rossi di rabbia più che di pianto.","tell":"Guarda dritto, alza il mento quando parla del litigio. Abbassa la voce solo sulla reputazione della Dimora. Porta un mazzo di chiavi alla cintura e lo tocca quando si parla delle suite.","questions":[{"id":"o1","q":"Ieri sera ha litigato con Landi.","a":"Mi ha chiesto quindicimila euro per una recensione buona. Gli ho detto di andare al diavolo, davanti a tutta la sala. Ne vado fiera.","insight":"Landi ha chiesto 15.000 € a Ottavia per una recensione buona. Lei ha rifiutato davanti alla sala."},{"id":"o2","q":"Dov'era ieri sera, dopo cena?","a":"Alla reception, dalla fine della cena in poi. Una coppia arrivata tardi da Monaco, poi la cassa. La telecamera mi inquadra tutta la notte, se vuole guardarla.","insight":"Ottavia dice di essere stata alla reception dalla fine della cena in poi, sotto la telecamera.","lie":true},{"id":"o3","q":"Come ha prenotato la signora Orsini?","a":"Per telefono, tre settimane fa. Una cosa strana: voleva le stesse notti del signor Landi. Mi ha chiesto se lui aveva già confermato. E ha voluto la camera 2, sul cortile.","insight":"Secondo Ottavia, Livia ha chiesto le stesse notti di Landi, se lui aveva confermato, e la camera 2 sul cortile."}]},{"id":"matteo","name":"Matteo Sticchi","role":"Chef, 34 anni","look":"Giacca da cuoco sbottonata, dita gialle di nicotina. Mastica una gomma alla menta con accanimento.","tell":"Mastica la gomma con forza e ogni tanto si annusa le dita. Quando nomini il cortile guarda altrove. Ha un cerotto fresco sul pollice.","questions":[{"id":"m1","q":"Cosa ha cucinato per Landi?","a":"Un menu a parte, controllato due volte. Io con le allergie non scherzo: ieri in cucina non è entrata una noce.","insight":"Matteo dice che ieri in cucina non è entrata frutta a guscio.","lie":true},{"id":"m2","q":"Landi parlava della sua allergia?","a":"Con tutti. Ieri ha rimandato indietro il pane per due semi, urlando «volete ammazzarmi?». L'ha sentito tutta la sala. Anche la signora emiliana al tavolo accanto.","insight":"A cena Landi ha urlato della sua allergia davanti alla sala. Livia era al tavolo accanto."},{"id":"m3","q":"Lei era in cortile stanotte. Cosa ha visto?","req":["t_matteo"],"a":"(Sputa la gomma.) Ero lì a fumare, verso mezzanotte. Se Ottavia lo sa mi caccia: in servizio non si fuma. Ho visto aprirsi una finestra del piano terra e qualcosa cadere nella vasca. Ho pensato a una sigaretta.","insight":"Matteo fumava in cortile verso mezzanotte, di nascosto. Dice di aver visto qualcosa cadere nella vasca da una finestra del piano terra.","lie":true},{"id":"m4","q":"Ha visto Ottavia, dopo cena?","a":"Verso le undici meno un quarto saliva le scale delle suite, col passe-partout in mano. Di fretta. Ho pensato a un cliente.","insight":"Matteo dice di aver visto Ottavia salire alle suite col passe-partout verso le 22:45."}]}],"contradictions":[{"id":"x1","a":"v1","b":"o3","who":"livia","reply":"Va bene. Lo conoscevo. Sono venuta per dirgli in faccia che non avrei più pagato. Tutto qui.","aside":"Stringe i pugni sul tavolo.","insight":"Livia ammette di conoscere Landi e di essere venuta per dirgli che non avrebbe più pagato.","lie":true},{"id":"x2","a":"v3","b":"d3","who":"livia","reply":"Il nocino... è di mia nonna, lo porto sempre in viaggio. Gliel'ho offerto io. Non sapevo niente della sua allergia.","aside":"Si guarda le unghie.","insight":"Livia ammette che il nocino l'ha portato lei da casa e l'ha offerto a Landi. Dice di non sapere dell'allergia.","lie":true},{"id":"x3","a":"o2","b":"m4","who":"ottavia","reply":"Va bene. Sono salita nella sua suite, lui era in terrazza. Cercavo i suoi appunti su di me. Non li ho trovati. Alle undici ero giù.","aside":"Tocca il mazzo di chiavi alla cintura.","insight":"Ottavia ammette di essere entrata nella suite di Landi col passe-partout verso le 22:45, mentre lui era in terrazza.","lie":true},{"id":"x4","a":"m1","b":"d6","who":"matteo","reply":"La pasta di mandorle era per il dolce degli altri tavoli. Lavorata a parte, guanti cambiati. Ottavia non lo sa: quando c'è un allergico vuole la cucina pulita.","aside":"Si mette in bocca un'altra gomma.","insight":"Matteo ammette che ieri in cucina ha usato pasta di mandorle, senza dirlo a Ottavia.","lie":true}],"bluff":{"text":"Annunci che la penna d'adrenalina di Landi è stata ritrovata e che la scientifica ci ha trovato un'impronta.","reactions":{"livia":"Si alza per prendere il caffè che non ha toccato. Lo lascia di nuovo lì e si risiede.","ottavia":"«Bene.» Poi tocca il mazzo di chiavi alla cintura.","matteo":"Diventa pallido, guarda verso il cortile e si mette in bocca un'altra gomma."},"insight":"Al bluff della penna: Livia si alza e si risiede, Ottavia tocca il mazzo di chiavi, Matteo guarda il cortile."},"motive":{"options":["Evitare la stroncatura e il ricatto da 15.000 €.","Salvare il posto prima di una recensione sulla cucina.","Chiudere per sempre il ricatto sulle foto del 2019.","Vendicare un'amica rovinata da una sua recensione."],"correct":2},"culprit":"livia","key":["x2","x1","d7"],"solution":"Landi ricattava Livia dal 2019 con delle foto, e lei aveva già pagato tre volte. Ha prenotato apposta le sue stesse notti, nella camera 2 sul cortile, e si è portata da casa un nocino, sapendo, come tutta la sala, che Landi era allergico alla frutta a guscio. In terrazza gli ha offerto il «suo amaro» e intanto gli ha sfilato l'adrenalina dal taschino. Tornata in camera l'ha gettata dalla finestra nella vasca delle ninfee, dove Matteo l'ha vista cadere. Ottavia era entrata nella suite alle 22:45 a cercare gli appunti di Landi su di lei, ma dalle 23 è rimasta sotto la telecamera. Matteo nascondeva la sigaretta in servizio e la pasta di mandorle in cucina: niente a che vedere con il nocino emiliano."},{"id":"sedutacastellana","title":"Vieni con me","place":"Villa Fanizzi, campagne di Castellana Grotte","teaser":"Le luci si spengono. La moglie morta chiama. Il marito risponde.","intro":"Ernesto Fanizzi, 76 anni, vedovo da due, voleva risentire la voce di sua moglie Clara. Stasera, nella sua villa, il Professor Orfeo spegne le luci e la voce arriva: «Ernesto, vieni con me.» Quando le luci si riaccendono Ernesto è riverso sul tavolo, la mano stretta sullo spray per il cuore. Tutti accusano il medium. Tu i medium li conosci.","details":[{"id":"d1","label":"Sotto il tavolo","text":"Una piccola cassa bluetooth fissata con nastro biadesivo sotto il piano, al centro.","insight":"Sotto il tavolo della seduta, una cassa bluetooth fissata col biadesivo."},{"id":"d2","label":"Il tavolino","text":"Una delle tre gambe ha un piolo retrattile. Basta un ginocchio, dal posto del medium, per far «alzare» il tavolo.","insight":"Una gamba del tavolino ha un piolo retrattile, che si aziona col ginocchio dal posto del medium."},{"id":"d3","label":"Lo spray di Ernesto","text":"Trinitrina sublinguale, nuovo. Pieno fino all'orlo. Uno spruzzo sulla lingua non pizzica, non brucia, non sa di niente.","insight":"Lo spray nuovo di Ernesto è pieno fino all'orlo, e spruzzato sulla lingua non pizzica e non sa di niente. La trinitrina pizzica."},{"id":"d4","label":"Il cestino del bagno","text":"Uno spray di trinitrina vecchio, mezzo pieno, scadenza fra undici mesi. Accanto, la scatola del nuovo: «Farmacia Fanizzi, Putignano».","insight":"Nel cestino: lo spray vecchio, mezzo pieno, che scade fra undici mesi. La scatola del nuovo viene dalla Farmacia Fanizzi di Putignano."},{"id":"d5","label":"Il contratto del medium","text":"Firmato da Ernesto la settimana scorsa: dieci sedute, 2.000 € l'una, pagamento a fine seduta. Stasera era la prima.","insight":"Contratto del medium: dieci sedute a 2.000 €, pagate a fine seduta. Stasera era la prima."},{"id":"d6","label":"La lettera nello studio","text":"Scritta da Ernesto al suo notaio, non ancora spedita: «Chiedere a Filippo la restituzione dei 180.000 € entro il mese. Altrimenti procedere.»","insight":"Ernesto stava per chiedere a Filippo la restituzione di 180.000 € entro il mese. «Altrimenti procedere.»"},{"id":"d7","label":"Il foglio del cardiologo","text":"Attaccato al frigo con una calamita: «In caso di dolore al petto: trinitrina sotto la lingua, subito. Evitare emozioni forti.»","insight":"Sul frigo, il cardiologo: in caso di dolore al petto trinitrina subito, ed evitare emozioni forti."}],"suspects":[{"id":"orfeo","name":"Il Professor Orfeo","role":"Medium, al secolo Oronzo Pace","look":"Tunica scura, anello d'argento al pollice, voce impostata da teatro.","tell":"Ti tiene lo sguardo troppo a lungo e lascia le frasi a metà, aspettando che tu le completi. Quando guarda il corpo di Ernesto si sfila l'anello d'argento, poi lo rimette.","questions":[{"id":"o1","q":"Cosa è successo al buio?","a":"Clara è venuta. L'avete sentita tutti. Ernesto ha detto «sì, amore mio» e poi... il cuore. L'emozione. Io sono solo un canale.","aside":"Parla a occhi socchiusi."},{"id":"o2","q":"La voce di Clara usciva da una cassa sotto il tavolo.","req":["d1"],"a":"(Un silenzio lungo.) La gente vuole una voce. Io gliela do. È teatro, non omicidio. Ernesto l'ho visto stasera per la prima volta: stamattina ero a Lecce, a fare una seduta per sei signore. E morto mi costa diciottomila euro.","insight":"Orfeo ammette la cassa. Dice di aver visto Ernesto stasera per la prima volta, e di essere stato a Lecce stamattina.","lie":true},{"id":"o3","q":"Chi le ha dato i dettagli su Clara?","req":["o2"],"a":"Il nipote, Filippo. Mi ha cercato lui, un mese fa. Mi ha dato tutto: il soprannome, la canzone, la collana di perle. E una frase precisa da far dire a Clara: «Ernesto, vieni con me.» Su quella ha insistito.","insight":"Secondo Orfeo, un mese fa l'ha cercato Filippo: gli ha dato i ricordi di Clara e la frase «Ernesto, vieni con me»."}]},{"id":"livia","name":"Livia Fanizzi","role":"Figlia, 44 anni","look":"Occhi gonfi, cardigan abbottonato storto, il telefono stretto nella mano sinistra.","tell":"Il pollice sinistro scorre sul telefono anche adesso, a vuoto. Quando dice «non l'ho mai lasciata» guarda il telefono, non te.","questions":[{"id":"l1","q":"Cosa ricorda del buio?","a":"Tenevo la mano di papà, a sinistra. Non l'ho mai lasciata. Mai.","insight":"Livia dice di non aver mai lasciato la mano del padre."},{"id":"l2","q":"Al buio lei ha lasciato la mano di suo padre e ha preso il telefono.","req":["t_livia"],"a":"(Piange.) Registravo. Volevo le prove che quel ciarlatano ci derubava. Senta. (Nella registrazione, dopo la voce di Clara, Ernesto ansima: «Lo spray... non fa niente... non fa niente!» Una sedia che striscia. Venti secondi. Poi Livia che grida: «La luce!»)","insight":"Nella registrazione di Livia, al buio, Ernesto usa lo spray e dice «non fa niente». Passano venti secondi prima che Livia chieda la luce.","lie":true},{"id":"l3","q":"Chi ha trovato il medium?","a":"Filippo. Diceva che a papà avrebbe fatto bene sentire la mamma. Io ero contraria. Per questo ho registrato.","insight":"Secondo Livia la seduta l'ha voluta Filippo; lei era contraria."},{"id":"l4","q":"Chi è venuto in villa oggi?","a":"Filippo, alle dieci, con le medicine. E verso le undici una macchina che non conosco, targa di Lecce, parcheggiata dietro la serra. Ho pensato a un fornitore.","insight":"Oggi alle 10 è passato Filippo con le medicine. Verso le 11 un'auto targata Lecce era parcheggiata dietro la serra."}]},{"id":"filippo","name":"Filippo Fanizzi","role":"Nipote e farmacista, 39 anni","look":"Occhiali sottili, giacca grigia, mani in tasca.","tell":"Tiene le mani in tasca e le tira fuori solo per sistemarsi gli occhiali. Parla dello zio con parole da bugiardino: «evento cardiaco», «soggetto a rischio». Non dice mai «zio».","questions":[{"id":"f1","q":"Chi ha voluto la seduta?","a":"Livia. Io ero contrario, figuriamoci. Sono un uomo di scienza.","insight":"Filippo dice che la seduta l'ha voluta Livia."},{"id":"f2","q":"Chi si occupava dei farmaci di Ernesto?","a":"Io, da anni. Stamattina gli ho portato uno spray nuovo. Il vecchio era scaduto.","insight":"Filippo dice di aver sostituito lo spray stamattina perché quello vecchio era scaduto."},{"id":"f3","q":"Ernesto le chiedeva indietro 180.000 euro.","req":["d6"],"a":"Stavamo trattando. Il soggetto minacciava, poi perdonava. Funzionava così da sempre.","aside":"Si sistema gli occhiali.","insight":"Filippo conferma il debito di 180.000 €: «Il soggetto minacciava, poi perdonava.»"},{"id":"f4","q":"Nello spray che lei gli ha dato c'era acqua.","req":["d3"],"a":"Impossibile, era sigillato. Sarà un difetto di produzione. Capita.","insight":"Filippo dice che lo spray era sigillato, e parla di «un difetto di produzione».","lie":true}]}],"bluff":{"text":"Annunci che il medico legale ha già notato una cosa: nessuno spray di trinitrina esce dalla fabbrica pieno fino all'orlo come quello di Ernesto.","reactions":{"orfeo":"Alza le mani. «Io di medicine non so niente, faccio spettacolo!»","livia":"«Ma papà se l'è spruzzato, l'ho sentito!» Poi si morde il labbro.","filippo":"«I flaconi da duecento dosi sono pienissimi, sono tutti così.» Si sistema gli occhiali."},"insight":"Al bluff sullo spray Livia ha detto di aver sentito il padre spruzzarlo, Filippo che quei flaconi sono tutti pienissimi, Orfeo che di medicine non sa niente."},"motive":{"options":["Incassare le altre nove sedute del contratto.","Liberarsi di un padre che sperperava l'eredità con un ciarlatano.","Evitare una denuncia per la cassa sotto il tavolo.","Non restituire i 180.000 € ed evitare la causa."],"correct":3},"culprit":"filippo","key":["x1","f4","l2"],"solution":"Il medium è un truffatore: cassa sotto il tavolo, piolo nella gamba. Ma a uccidere è stato Filippo, che doveva allo zio 180.000 euro e rischiava di finire davanti a un giudice. Un mese fa trova il medium e gli detta i ricordi di Clara e la frase «vieni con me», sapendo che quel cuore non regge uno spavento. Stamattina butta lo spray buono, non scaduto, e gli consegna un flacone della sua farmacia pieno d'acqua. Al buio Ernesto spruzza, non succede niente. Orfeo era un truffatore e stamattina non era a Lecce ma in villa, a montare la cassa; Livia aveva lasciato la mano del padre per registrare, e per venti secondi non ha chiesto la luce.","contradictions":[{"id":"x1","a":"f2","b":"d4","who":"filippo","reply":"Avrò letto male la data. Ero di corsa.","insight":"Filippo ammette che lo spray che ha buttato non era scaduto: «Avrò letto male la data.»","lie":true},{"id":"x2","a":"f1","b":"l3","who":"filippo","reply":"Va bene, l'ho proposto io. Volevo che si desse pace.","insight":"Filippo ammette di aver proposto lui la seduta.","lie":true},{"id":"x3","a":"o2","b":"l4","who":"orfeo","reply":"(Si sfila l'anello.) Stamattina ero qui, sì. Sono venuto a montare la cassa sotto il tavolo. La governante mi ha fatto entrare. Mezz'ora in casa, da solo. Lecce era una storia.","insight":"Orfeo ammette di essere stato in villa stamattina verso le 11, mezz'ora da solo, per montare la cassa.","lie":true}]},{"id":"calici","title":"Il quinto calice","place":"Teatro dei Portici, Martina Franca","teaser":"Il numero lo faceva da trent'anni. Stasera il pubblico ha applaudito un morto.","intro":"Orfeo il Grande, al secolo Oreste Pace, 62 anni, chiude ogni spettacolo con il suo numero più famoso: cinque calici, uno col veleno, e uno spettatore che li mescola. Lui «legge» lo spettatore e beve sempre quello giusto. Stasera ha bevuto, ha sorriso e si è accasciato sul palco. Duecento persone hanno applaudito per dieci secondi, prima di capire. Tu eri in quarta fila.","details":[{"id":"d1","label":"I cinque calici","text":"Sul tavolino in scena. Quello da cui ha bevuto Orfeo ha una tacca minuscola sulla base, invisibile dalla platea. Dal fondo sale un odore di mandorle amare.","insight":"Orfeo ha bevuto dal calice con una tacca minuscola sulla base, invisibile dalla platea. Dal fondo sale odore di mandorle amare."},{"id":"d2","label":"La scaletta dietro le quinte","text":"Attaccata al muro: «20:45 Sergio: riempire i calici. 21:10 Nives: vassoio in scena.»","insight":"Scaletta: alle 20:45 Sergio riempie i calici; alle 21:10 Nives porta il vassoio in scena."},{"id":"d3","label":"Il camerino di Orfeo","text":"Stampati, gli screenshot di un canale video, «Magia Nuda», che svela i suoi numeri uno per uno. Tutti ripresi di nascosto dalla quinta sinistra. A penna, Orfeo: «È uno di casa. Lunedì avvocato.»","insight":"Nel camerino, stampe del canale «Magia Nuda», che svela i numeri di Orfeo, tutti ripresi dalla quinta sinistra. Nota di Orfeo: «È uno di casa. Lunedì avvocato.»"},{"id":"d4","label":"Il registro del retropalco","text":"Stasera tre firme soltanto: Orfeo, Nives, Sergio. La porta di servizio era chiusa dall'interno.","insight":"Registro del retropalco: stasera solo tre firme, Orfeo, Nives, Sergio. Porta di servizio chiusa dall'interno."},{"id":"d5","label":"Il cestino del retropalco","text":"Un paio di guanti di lattice appallottolati e una fialetta di vetro vuota, senza etichetta.","insight":"Nel cestino del retropalco: guanti di lattice appallottolati e una fialetta di vetro vuota, senza etichetta."},{"id":"d6","label":"La cassetta di Sergio","text":"Cacciaviti, nastro nero, una lima da orafo. In fondo, una microcamera da occhiello ancora nella scatola del caricatore.","insight":"Nella cassetta di Sergio, in fondo: una microcamera da occhiello nella scatola del caricatore."},{"id":"d7","label":"La citazione in tribunale","text":"Nel camerino, un atto: Lucio Ferrara, in arte Lucifer, cita Orfeo per plagio. Il numero conteso è quello dei calici.","insight":"Lucio Ferrara, in arte Lucifer, ha citato Orfeo per plagio. Il numero conteso è quello dei calici."}],"suspects":[{"id":"sergio","name":"Sergio Conversano","role":"Tecnico di scena, da vent'anni con Orfeo","look":"Maglia nera, cintura con gli attrezzi, mani da falegname. Fuma sul retro.","tell":"Unghie pulite per uno che maneggia attrezzi. Nelle pieghe delle nocche, una polvere bianca e fine. Se la strofina sui pantaloni quando lo guardi. Accende sigarette e le lascia consumare.","questions":[{"id":"s1","q":"Che cosa ha fatto prima del numero?","a":"Il solito. Botole, corde, e alle nove meno un quarto ho riempito i calici. Acqua dal rubinetto, e il blu nel calice finto. Poi il vassoio l'ha preso Nives.","insight":"Sergio: alle 20:45 ha riempito i calici, acqua dal rubinetto e il blu in quello finto. Poi il vassoio l'ha preso Nives."},{"id":"s2","q":"Conosce il canale «Magia Nuda»?","a":"Mai visto. Io lavoro con le mani, non col telefono.","insight":"Sergio dice di non aver mai visto il canale «Magia Nuda»: «Io lavoro con le mani, non col telefono.»"},{"id":"s3","q":"Nella sua cassetta c'è una microcamera da occhiello.","req":["d6"],"a":"Me l'ha chiesta il maestro, per rivedersi le prove.","insight":"Sergio dice che la microcamera gliel'ha chiesta Orfeo, per rivedersi le prove."},{"id":"s4","q":"Nel cestino ci sono guanti di lattice. E lei ha il talco sulle nocche.","req":["d5","t_sergio"],"a":"Li uso per le lampade. Le alogene non si toccano con le dita.","aside":"Le lampade si cambiano la mattina, a teatro vuoto. Stasera le luci le gestiva il tecnico in cabina.","insight":"Sergio dice che i guanti di lattice li usa per le lampade alogene, che non si toccano con le dita.","lie":true}]},{"id":"nives","name":"Nives Semeraro","role":"Assistente di scena e compagna di Orfeo","look":"Ancora col costume di paillettes, trucco colato, uno scialle sulle spalle.","tell":"Continua a guardare verso la platea, sempre la stessa poltrona della fila C. Si sfila e si rimette un anello d'argento a forma di serpente. Ha le mani fredde e se le tiene sotto lo scialle.","questions":[{"id":"n1","q":"Cosa è successo in scena?","a":"Tutto come sempre. Lo spettatore mescola, Orfeo «legge», e alla fine beve dal calice con la tacca, che è sempre acqua. Si è portato la mano alla gola. Ho pensato che improvvisasse.","insight":"Nives: a fine numero Orfeo beve sempre dal calice con la tacca, che è sempre acqua. Stasera si è portato la mano alla gola."},{"id":"n2","q":"I video del canale sono girati dalla quinta sinistra. Chi c'è lì?","req":["d3"],"a":"Alla sinistra? Solo Sergio, alla leva delle botole. Io sto sempre a destra, col vassoio. Sempre.","insight":"Nives: in quinta sinistra c'è solo Sergio, alla leva delle botole. Lei sta sempre a destra col vassoio."},{"id":"n3","q":"Chi sapeva della tacca?","a":"Orfeo, io, e Sergio, che ha fatto i calici. Nessun altro al mondo. Orfeo non l'ha mai detto nemmeno al suo avvocato.","insight":"Nives: della tacca sapevano Orfeo, lei e Sergio, che ha fatto i calici. Nessun altro."},{"id":"n4","q":"Continua a guardare la fila C. Il posto di Lucio.","req":["t_nives"],"a":"(Si stringe lo scialle.) Lucio mi ha offerto un posto nel suo spettacolo. Stavo per lasciare Orfeo. Non gliel'avevo ancora detto.","insight":"Nives: Lucio le ha offerto un posto nel suo spettacolo; stava per lasciare Orfeo e non gliel'aveva ancora detto.","lie":true}]},{"id":"lucio","name":"Lucio Ferrara","role":"Illusionista rivale, in arte Lucifer","look":"Mantello nero anche fuori scena, tre anelli d'argento a forma di serpente, biglietto della fila C in mano.","tell":"Parla forte e si gira verso chi ascolta. Quando si parla di Orfeo morto smette di parlare e gli trema il mento. Non guarda mai Nives, nemmeno quando lei parla.","questions":[{"id":"l1","q":"Dov'era durante lo spettacolo?","a":"Fila C, posto 7. Ho pagato il biglietto per vedere dal vivo il mio numero rubato. Non mi sono alzato nemmeno all'intervallo. Chieda ai miei vicini.","insight":"Lucio dice di essere rimasto al posto C7 per tutto lo spettacolo, intervallo compreso. Indica i vicini come testimoni."},{"id":"l2","q":"Lei ha fatto causa a Orfeo per il numero dei calici.","req":["d7"],"a":"Il numero è mio. Io uso un magnete sotto il tavolo. Lui come facesse non lo so: non me l'ha mai voluto dire, il ladro.","insight":"Lucio: il suo numero usa un magnete sotto il tavolo. Dice di non sapere come Orfeo riconoscesse il calice giusto."},{"id":"l3","q":"Dalla platea ha notato qualcosa?","a":"Il tecnico. Durante il numero delle corde era in quinta sinistra col telefono puntato sul palco. Durante un numero! Io uno così lo licenzio in tronco.","insight":"Lucio: durante il numero delle corde il tecnico era in quinta sinistra col telefono puntato sul palco."},{"id":"l4","q":"Che rapporto ha con Nives?","a":"Professionale. Le ho offerto un contratto per la prossima tournée. L'avrò vista tre volte in vita mia.","insight":"Lucio dice che con Nives il rapporto è solo di lavoro: un'offerta per la tournée, tre incontri in tutto."}]}],"bluff":{"text":"Annunci che Orfeo, sospettando qualcuno, stasera aveva spostato la tacca su un altro calice.","reactions":{"sergio":"«Spostata? Quando?» Si accende una sigaretta e la spegne subito.","nives":"«Impossibile. Il vassoio l'ho portato io, era tutto come sempre.» Poi si morde il labbro.","lucio":"«Tacca? Quale tacca?» E, per la prima volta, guarda Nives."},"insight":"Al bluff della tacca: Sergio ha chiesto quando; Nives ha detto che il vassoio era come sempre; Lucio ha guardato Nives."},"culprit":"sergio","key":["s4","x1","d1"],"motive":{"options":["Vincere la causa per plagio eliminando l'avversario","Impedire a Orfeo di denunciarlo per il canale che svelava i suoi trucchi","Liberarsi di Orfeo per stare con Lucio","Prendersi il numero dei calici una volta per tutte"],"correct":1},"solution":"Il veleno era nel calice con la tacca, l'unico che Orfeo avrebbe bevuto di sicuro. Della tacca sapevano solo Nives e Sergio. Sergio riempiva i calici alle 20:45, coi guanti di lattice che ha lasciato nel cestino e il talco rimasto sulle nocche. Il movente era nel camerino: da mesi Sergio filmava i numeri dalla quinta sinistra e li svelava sul suo canale, e lunedì Orfeo sarebbe andato dall'avvocato. Nives voleva solo andarsene, e Lucio, che non ha mai lasciato la fila C, la tacca non sapeva nemmeno che esistesse. Nives e Lucio nascondevano solo la loro relazione: lei conosceva la tacca ma il vassoio l'ha preso già pronto, lui dalla fila C non si è mai mosso.","contradictions":[{"id":"x1","a":"s2","b":"n2","who":"sergio","reply":"Va bene, il canale è mio. Novecento euro al mese per trent'anni di segreti. Sa quanto rende un video da un milione di visualizzazioni?","aside":"Lo dice guardando la porta del camerino di Orfeo.","insight":"Sergio ammette che il canale «Magia Nuda» è suo. Dice che gli rende novecento euro al mese.","lie":true},{"id":"x2","a":"l4","b":"t_nives","who":"lucio","reply":"(Si guarda gli anelli.) Da marzo. Lei voleva dirglielo dopo la tournée. Adesso non serve più.","aside":"Nives si copre la faccia con lo scialle.","insight":"Lucio ammette una relazione con Nives da marzo. L'anello di Nives è uguale ai suoi. Orfeo non lo sapeva.","lie":true}]},{"id":"cesareo-villette","title":"Le Dune Bianche","place":"Cantiere Le Dune Bianche, Porto Cesareo","teaser":"Quattordici villette sulla carta. Sul terreno, sabbia. E il geometra è sparito.","intro":"Quattordici famiglie hanno versato trentamila euro di caparra per una villetta alle Dune Bianche, a trecento metri dal mare di Porto Cesareo. Lunedì hanno scoperto che il permesso di costruire è falso e che le caparre sono sparite. Il geometra Aldo Miglietta, che firmava tutto, non si trova da venerdì sera: la sua auto è al parcheggio di Torre Lapillo. Per tutti è scappato coi soldi. Il costruttore ti ha chiamato perché, dice, «se è scappato, voglio sapere con chi».","details":[{"id":"d1","label":"Il permesso di costruire","text":"Appeso nella baracca del cantiere, con timbro e firma di Aldo Miglietta. Il numero di protocollo, sul sito del Comune, corrisponde a una tettoia autorizzata nel 2016.","insight":"Il numero di protocollo del permesso, sul sito del Comune, è quello di una tettoia del 2016."},{"id":"d2","label":"I preliminari","text":"Quattordici contratti di vendita. La firma di Aldo è identica in tutti, al millimetro, compresa una piccola sbavatura sulla M.","insight":"Nei quattordici preliminari la firma di Aldo è identica al millimetro, sbavatura sulla M compresa."},{"id":"d3","label":"L'estratto conto","text":"Conto «caparre Dune Bianche», intestato all'agenzia Leo Immobiliare. A maggio: prelievo in contanti di 60.000 euro, causale «anticipo Sud Costruzioni». Lunedì mattina: bonifico di 380.000 euro a «Salina Holding Ltd», La Valletta.","insight":"Conto caparre dell'agenzia Leo: a maggio 60.000 € in contanti, causale «anticipo Sud Costruzioni». Lunedì 380.000 € a una società di Malta."},{"id":"d4","label":"L'agenda di Aldo","text":"Nella baracca. Ultima pagina scritta, venerdì: «Firme false?? Parlare con S. prima di andare in Procura.»","insight":"Agenda di Aldo, venerdì: «Firme false?? Parlare con S. prima di andare in Procura.»"},{"id":"d5","label":"L'ipoteca","text":"Sulla scrivania di Gianni Quarta: ipoteca sulla sua casa di Leverano, a garanzia del mutuo per il terreno.","insight":"Gianni ha ipotecato la sua casa di Leverano per il mutuo sul terreno."},{"id":"d6","label":"Le telecamere del cantiere","text":"Registro dell'impianto: spente venerdì alle 19:02 dall'app, utente «agenzia». Riaccese lunedì mattina. Sul cancello, un cartello: «Cantiere chiuso sabato e domenica».","insight":"Telecamere del cantiere spente venerdì alle 19:02 dall'utente «agenzia», riaccese lunedì. Il cantiere è chiuso nel weekend."},{"id":"d7","label":"L'auto di Aldo","text":"Una vecchia Punto al parcheggio di Torre Lapillo, chiusa a chiave. Sul sedile, la borsa da lavoro con il suo timbro. Nessuna valigia.","insight":"Auto di Aldo a Torre Lapillo: sul sedile la borsa col suo timbro. Nessuna valigia."}],"suspects":[{"id":"gianni","name":"Gianni Quarta","role":"Costruttore, Sud Costruzioni, 61 anni","look":"Faccia bruciata dal sole, voce che copre le betoniere. Agita una cartellina di documenti mentre parla.","tell":"Urla, e ti porge i documenti prima che tu li chieda. Quando dice «la mia casa» la voce gli si spezza. Si asciuga il sudore e tiene una mano sulla tasca interna della giacca.","questions":[{"id":"g1","q":"Lei ha incassato le caparre?","a":"Io non ho visto un euro! Caparre e preliminari li gestiva l'agenzia, sul conto vincolato. Io per quel terreno ho messo in ipoteca pure casa mia!","insight":"Gianni dice di non aver visto un euro: caparre e preliminari li gestiva l'agenzia di Sabrina.","lie":true},{"id":"g2","q":"Aldo voleva parlare con «S.» prima della Procura. Sud Costruzioni?","req":["d4"],"a":"Aldo aveva il mio numero, mi chiamava pure per un sacco di cemento. E venerdì sera ero alla cresima di mio nipote a Leverano: duecento invitati e un fotografo.","insight":"Gianni dice di essere stato venerdì sera a una cresima a Leverano, con duecento invitati."},{"id":"g3","q":"Chi le ha presentato Aldo?","a":"Sabrina, a maggio. «Un ragazzo bravo, uno che non fa domande.» Così me l'ha venduto.","insight":"Aldo l'ha presentato Sabrina, a maggio: «uno che non fa domande»."},{"id":"g4","q":"Ha visto la moglie di Aldo, in questi giorni?","a":"Martedì, in banca a Porto Cesareo. Usciva con una busta gialla gonfia così. Una moglie disperata che ritira contanti: mi è parso strano.","insight":"Gianni dice di aver visto Teresa martedì uscire dalla banca con una busta gonfia di contanti."}]},{"id":"sabrina","name":"Sabrina Leo","role":"Agente immobiliare, 44 anni","look":"Blazer color sabbia, sorriso da vetrina, un portachiavi pieno di chiavi di case altrui.","tell":"Sorride anche quando parla dei soldi spariti. Dice «povero Aldo» e non chiede se l'hanno trovato. Quando le mostri un foglio lo gira verso di sé per leggerlo.","questions":[{"id":"s1","q":"Chi curava le pratiche?","a":"Aldo. Tutto Aldo: permessi, firme, carte. Io vendo, non timbro. Povero Aldo. Si vede che aveva debiti.","insight":"Sabrina dice che permessi, firme e carte erano tutti di Aldo."},{"id":"s2","q":"Quando ha visto Aldo l'ultima volta?","a":"Giovedì, in agenzia. Venerdì mi ha solo telefonato, agitatissimo. Poi più niente.","insight":"Sabrina dice di aver visto Aldo l'ultima volta giovedì. Venerdì solo una telefonata."},{"id":"s3","q":"Lunedì dal conto della sua agenzia sono partiti 380.000 euro per Malta.","req":["d3"],"a":"Una disposizione di Aldo. Il conto è dell'agenzia, ma i pagamenti ai fornitori li decideva lui, come direttore dei lavori.","aside":"Sorride.","insight":"Sabrina dice che il bonifico a Malta l'ha disposto Aldo, come direttore dei lavori, sul conto della sua agenzia.","lie":true},{"id":"s4","q":"Le telecamere del cantiere le ha spente la sua agenzia.","req":["d6"],"a":"Le spegniamo sempre il venerdì sera. Per la privacy dei clienti che vengono a vedere il cantiere nel weekend.","aside":"Gira il foglio verso di sé.","insight":"Sabrina dice che le telecamere le spengono il venerdì «per i clienti che visitano il cantiere nel weekend».","lie":true}]},{"id":"teresa","name":"Teresa Miglietta","role":"Moglie di Aldo, 39 anni","look":"Una felpa del marito, troppo grande. Due telefoni in mano, uno vecchio con la cover rotta.","tell":"Guarda sempre il telefono vecchio, mai il suo. Quando qualcuno dice che il marito è un ladro stringe le labbra e sta zitta. Non ha chiesto nemmeno una volta dove lo stanno cercando.","questions":[{"id":"t1","q":"Quando ha visto suo marito l'ultima volta?","a":"Venerdì, alle sette e mezza. È uscito dicendo: «Vado al cantiere, Sabrina mi aspetta là, dobbiamo chiarire una cosa.» Non è più tornato.","insight":"Secondo Teresa, venerdì alle 19:30 Aldo è uscito per incontrare Sabrina al cantiere."},{"id":"t2","q":"Lei aspetta un messaggio su quel telefono vecchio.","req":["t_teresa"],"a":"È il telefono di Aldo. Quello vecchio. Lo tengo carico, se mai chiamasse.","aside":"Lo gira a faccia in giù.","insight":"Teresa dice che tiene carico il vecchio telefono di Aldo, nel caso chiamasse.","lie":true},{"id":"t3","q":"Aldo aveva debiti?","a":"Aldo? Porta la stessa giacca da dieci anni. Se avesse avuto quattrocentomila euro, prima di scappare se ne sarebbe comprata una nuova.","insight":"Secondo Teresa, Aldo non aveva debiti né soldi da parte."}]}],"contradictions":[{"id":"x1","a":"s2","b":"t1","who":"sabrina","reply":"Va bene, ci siamo visti al cantiere. Cinque minuti. Era fuori di sé, farneticava di firme. L'ho calmato e se n'è andato.","aside":"Mentre lo dice, sorride.","insight":"Sabrina ammette di aver incontrato Aldo al cantiere venerdì sera.","lie":true},{"id":"x2","a":"s1","b":"d2","who":"sabrina","reply":"Tanti geometri hanno la firma su un timbro. Sarà così.","aside":"Gira il foglio verso di sé e lo guarda a lungo.","insight":"Sulla firma identica in tutti i preliminari, Sabrina dice che Aldo avrà usato un timbro.","lie":true},{"id":"x3","a":"g1","b":"d3","who":"gianni","reply":"Sessantamila, in contanti. Anticipo per i materiali. In nero, sì. Ma il cemento l'ho comprato davvero, venga a vedere il piazzale.","aside":"Toglie la mano dalla tasca della giacca.","insight":"Gianni ammette di aver preso a maggio 60.000 € in contanti e in nero dal conto delle caparre, come anticipo per i materiali.","lie":true},{"id":"x4","a":"t2","b":"g4","who":"teresa","reply":"(Ti porge il telefono vecchio.) Martedì mi ha scritto da un numero nuovo. «Sto bene. Non dire niente. Lei dice che le firme sono mie e che se parlo la galera me la faccio io.» Gli ho mandato cinquemila euro. Lei, dice. Non so chi è, lei.","aside":"Stringe le labbra.","insight":"Teresa ammette che Aldo le scrive da un numero nuovo e che gli ha mandato 5.000 €. Aldo scrive di temere una donna che gli addossa le firme.","lie":true}],"bluff":{"text":"Annunci che Aldo è stato trovato vivo in un B&B di Veglie e che sta parlando con i carabinieri.","reactions":{"gianni":"«Finalmente! Adesso ci ridà i soldi.» Poi si tocca la tasca interna della giacca.","sabrina":"«Qualunque cosa dica, ci sono i documenti.» Sorride.","teresa":"Chiude gli occhi. Non chiede dov'è, né come sta."},"insight":"Al bluff: Gianni si tocca la giacca, Sabrina parla dei documenti, Teresa non chiede come sta Aldo."},"motive":{"options":["Salvare la casa ipotecata incassando le caparre.","Tenersi le caparre e far ricadere la truffa sul geometra.","Far sparire un marito e cominciare da capo.","Coprire i pagamenti in nero del cantiere."],"correct":1},"culprit":"sabrina","key":["x1","x2","s3"],"solution":"La truffa l'ha costruita Sabrina: permesso falso, preliminari preparati dalla sua agenzia con la firma di Aldo stampata sopra, caparre sul conto dell'agenzia. Aldo, scelto perché «non faceva domande», si è accorto delle firme e venerdì è andato al cantiere a chiarire con lei. Sabrina aveva già spento le telecamere alle 19:02: lo ha minacciato di fargli pagare tutto, e Aldo è scappato così com'era, lasciando l'auto a Torre Lapillo senza nemmeno una valigia. Lunedì, con il geometra «in fuga» come colpevole perfetto, Sabrina ha spostato 380.000 euro a Malta. Gianni nascondeva i 60.000 € in nero presi come anticipo per i materiali. Teresa nascondeva che Aldo è vivo e che gli manda soldi. Aldo ha paura di Sabrina."},{"id":"studiodentistico","title":"Il sorriso perfetto","place":"Studio dentistico Mancuso, quartiere Poggiofranco, Bari","teaser":"Trentamila euro, o le foto vanno a due famiglie.","intro":"Il dottor Sergio Mancuso, 52 anni, dentista, sposato, ha una relazione con la sua collega di studio, Irene Caputo, anche lei sposata. Stamattina nella cassetta dello studio c'era una busta: quattro foto di loro due, di notte, nella sala 2, e una lettera. «30.000 € in contanti, o le foto arrivano a tua moglie e al marito di Irene.» Sergio non vuole la polizia. Vuole sapere chi, dei suoi, lo sta tradendo.","details":[{"id":"d1","label":"La lettera","text":"Stampata al computer. La carta è quella intestata dello studio, con l'intestazione tagliata via: in alto resta un filo del logo blu.","insight":"La lettera è stampata su carta intestata dello studio, con l'intestazione tagliata via."},{"id":"d2","label":"Le foto","text":"Scattate dall'alto, dalla mensola della sala 2 dove sta la reflex per le foto dei sorrisi. Sergio si vede sempre in faccia. Irene sempre di spalle, o di profilo coperta dai capelli. In quattro scatti, mai il suo viso.","insight":"Le foto sono scattate dalla mensola della reflex, in sala 2. Sergio si vede sempre in faccia; Irene mai."},{"id":"d3","label":"Il registro dell'allarme","text":"Giovedì scorso: «20:58 disattivato — codice 03 (E. Barone)». «23:40 riattivato — codice 03.»","insight":"Giovedì sera l'allarme è stato disattivato alle 20:58 col codice di Elisa, e riattivato alle 23:40."},{"id":"d4","label":"Il post-it","text":"Attaccato sotto la tastiera della reception: tutti i codici dell'allarme, scritti a penna, con una grafia tonda.","insight":"Sotto la tastiera della reception, un post-it con tutti i codici dell'allarme, in grafia tonda."},{"id":"d5","label":"La chat di Sergio","text":"Te la mostra lui, a malincuore. Giovedì, 20:41, Sergio a Irene: «Entra tu, io arrivo alle nove e un quarto.» Irene: «Ok. Ti aspetto in sala 2.»","insight":"Giovedì alle 20:41 Sergio scrive a Irene: «Entra tu, io arrivo alle nove e un quarto.» Lei: «Ti aspetto in sala 2.»"},{"id":"d6","label":"La raccomandata","text":"Nella posta dello studio, per Irene, già aperta: uno studio legale di Bari. «Ricorso per separazione consensuale. Udienza fissata al 12 ottobre.»","insight":"Raccomandata per Irene: ricorso per separazione consensuale, udienza il 12 ottobre."},{"id":"d7","label":"Le istruzioni per il pagamento","text":"In fondo alla lettera: «Contanti in una scatola per impronte. Da lasciare nel laboratorio, armadietto 4.» L'armadietto 4 è quello di Elisa. Dallo sportello socchiuso spuntano due kit di sbiancamento sigillati, con l'etichetta del magazzino dello studio.","insight":"I soldi vanno lasciati nell'armadietto 4, quello di Elisa. Dentro ci sono due kit di sbiancamento sigillati del magazzino dello studio."}],"suspects":[{"id":"elisa","name":"Elisa Barone","role":"Igienista dentale, 29 anni","look":"Divisa verde, occhiaie, una foto di un bambino attaccata al badge.","tell":"Risponde di getto, senza pause, e ti guarda in faccia anche quando la domanda è brutta. Quando nomini l'armadietto alza la voce e si stringe il badge.","questions":[{"id":"e1","q":"Giovedì sera il suo codice ha disattivato l'allarme.","req":["d3"],"a":"Giovedì ero al matrimonio di mia cugina a Conversano, dalle sei all'una di notte. Trecento invitati e un videografo. Mi trovate in tutti i balli.","insight":"Elisa dice che giovedì sera era a un matrimonio a Conversano, dalle 18 all'una, con un videografo."},{"id":"e2","q":"Lei ha problemi di soldi?","a":"Un mutuo e un figlio di tre anni. Chi non ne ha? Ma chi ricatta non scrive di lasciare i soldi nel suo armadietto. Sarei scema.","insight":"Elisa ha un mutuo e un figlio di tre anni. Fa notare che le istruzioni puntano al suo armadietto."},{"id":"e3","q":"Chi usa la reflex della sala 2?","a":"La dottoressa Caputo. Fa le foto prima e dopo delle faccette. La regola lei, la carica lei. Se la tocchi ti uccide.","insight":"Secondo Elisa, la reflex della sala 2 la usa e la regola solo Irene."},{"id":"e4","q":"Cosa tiene nel suo armadietto?","a":"La divisa e le scarpe. Basta. Perché, volete aprirlo?","insight":"Elisa dice di tenere nell'armadietto solo la divisa e le scarpe.","lie":true}]},{"id":"irene","name":"Irene Caputo","role":"Dentista, collega di Sergio, 44 anni","look":"Camice su misura, fede ancora al dito, voce bassa e controllata.","tell":"Dice sempre «ci»: «ci ricatta», «ci rovina». Quando Sergio sparge le foto sul tavolo lei non abbassa gli occhi su nessuna. Gira la fede al dito.","questions":[{"id":"i1","q":"Giovedì sera, come siete entrati?","a":"Mi ha aperto Sergio. Io l'allarme non l'ho toccato.","insight":"Irene dice di essere arrivata dopo Sergio e di non aver toccato l'allarme."},{"id":"i2","q":"Nelle foto lei non si vede mai in faccia.","req":["d2"],"a":"Fortuna. O forse il ricattatore vuole colpire lui, non me.","aside":"Un mezzo sorriso, poi abbassa gli occhi.","insight":"Irene sul suo viso assente dalle foto: «Forse vuole colpire lui, non me.»"},{"id":"i3","q":"Lei si sta già separando.","req":["d6"],"a":"Sì. E allora? Non lo sapeva nessuno. Adesso lo sa lei.","aside":"Sergio si gira di scatto. Lui non lo sapeva.","insight":"Irene si sta separando, udienza il 12 ottobre. Non l'aveva detto a Sergio.","lie":true},{"id":"i4","q":"Chi altro, nello studio, ha bisogno di soldi?","a":"Chieda a Tina dei contanti. Metà di quelli che incassa in cassa non ci arrivano. Io lo so da mesi, e ho taciuto.","insight":"Secondo Irene, Tina non registra metà dei contanti che incassa."}]},{"id":"tina","name":"Tina Sgaramella","role":"Segretaria, 47 anni","look":"Occhiali alla catenella, agenda aperta, penna dietro l'orecchio.","tell":"Sull'agenda aperta la sua grafia è tonda, con le «a» chiuse a ricciolo. Quando si parla di codici d'allarme o di cassa chiude l'agenda e ci appoggia sopra la mano.","questions":[{"id":"s1","q":"Chi conosce i codici dell'allarme?","a":"Ognuno il suo. Io li so tutti a memoria, li ho impostati io.","insight":"Tina dice di sapere a memoria tutti i codici dell'allarme."},{"id":"s2","q":"Sotto la sua tastiera c'è un post-it con tutti i codici. Scritto da lei.","req":["d4"],"a":"(Arrossisce.) Non ho memoria per i numeri, va bene? Quel foglietto lo guarda anche Elisa, quando dimentica il suo. E la dottoressa Caputo, due settimane fa, frugava nel mio cassetto: cercava un modulo, disse.","insight":"Il post-it dei codici è di Tina. Lo consulta Elisa; due settimane fa Irene ha frugato nel cassetto della reception.","lie":true},{"id":"s3","q":"Come vanno le cose tra i due dottori?","a":"Lei voleva diventare socia al cinquanta per cento. Un mese fa lui le ha detto di no, qui, a voce alta. Lei è uscita sbattendo la porta. Il giorno dopo era tutta miele.","insight":"Un mese fa Sergio ha negato a Irene la società al 50%. Il giorno dopo lei era «tutta miele»."},{"id":"s4","q":"Chi tiene la cassa dei contanti?","a":"Io. Tutto registrato, al centesimo. Può controllare.","insight":"Tina dice che la cassa dei contanti è registrata al centesimo.","lie":true}]}],"bluff":{"text":"Annunci che la reflex della sala 2 salva ogni scatto anche su una seconda scheda, e che la stai facendo leggere adesso.","reactions":{"elisa":"«Magari! Così la finiamo con l'armadietto.» Si stringe il badge.","irene":"«Quel modello ha uno slot solo.» Poi si guarda la fede.","tina":"«Una seconda scheda? Io non so neanche accenderla, quella.» Chiude l'agenda."},"insight":"Al bluff della seconda scheda Irene ha detto che la reflex ha uno slot solo, Elisa ha tirato di nuovo in ballo l'armadietto, Tina ha chiuso l'agenda."},"motive":{"options":["Soldi per la separazione, e rivalsa per la società negata.","Pagare il mutuo con i contanti del ricatto.","Coprire i contanti spariti dalla cassa prima di essere scoperta.","Far licenziare Elisa scaricando su di lei il ricatto."],"correct":0},"culprit":"irene","key":["x1","i3","s2"],"solution":"La ricattatrice è la donna nelle foto. Sergio le aveva negato la società e Irene, che si stava già separando, aveva bisogno di soldi. Due settimane fa prende il codice di Elisa dal post-it di Tina. Giovedì entra per prima con quel codice, sistema la reflex della sala 2, che usa solo lei, e inquadra in modo che il suo viso non si veda mai. Poi lettera su carta dello studio e soldi nell'armadietto di Elisa, per incastrarla. Ma Elisa quella sera ballava a Conversano, e la minaccia di scriverlo al marito di Irene non spaventava nessuno. Elisa temeva l'armadietto perché ci teneva i kit di sbiancamento presi dal magazzino per lavori in nero; Tina tratteneva contanti dalla cassa, ma di ricatti non ne ha scritti.","contradictions":[{"id":"x1","a":"i1","b":"d5","who":"irene","reply":"Va bene, sono entrata io. Col codice di Elisa, sì: il mio avrebbe lasciato traccia. Per discrezione.","aside":"Sergio la fissa. Del codice di Elisa non sapeva niente.","insight":"Irene ammette di essere entrata giovedì per prima, da sola, col codice di Elisa: «il mio avrebbe lasciato traccia».","lie":true},{"id":"x2","a":"s4","b":"i4","who":"tina","reply":"(Si toglie gli occhiali.) Trecento euro al mese, da un anno. Mio marito è in cassa integrazione. Li avrei rimessi. Ma ricattare il dottore no: gli porto il caffè da quindici anni.","insight":"Tina ammette di trattenere circa 300 € al mese di contanti, da un anno.","lie":true},{"id":"x3","a":"e4","b":"d7","who":"elisa","reply":"(Abbassa la voce.) Li porto a casa. Il sabato faccio sbiancamenti in nero, in cucina, ad amiche e vicine. Con un mutuo e un bambino... Se il dottore lo scopre, mi licenzia.","insight":"Elisa ammette di prendere kit di sbiancamento dal magazzino dello studio per lavori in nero a casa.","lie":true}]},{"id":"zaffiri","title":"Gli zaffiri della nonna","place":"Masseria Le Due Torri, campagne di Fasano","teaser":"Dieci minuti di fuochi d'artificio. Novantamila euro di zaffiri.","intro":"Federica si è sposata oggi, in una masseria sopra Fasano, con la parure di zaffiri della nonna: collana, orecchini, bracciale. Alle undici li ha tolti per il cambio d'abito e li ha lasciati nella suite. A mezzanotte, dieci minuti di fuochi d'artificio sull'aia. All'una la cassetta era vuota. Nessuno ha lasciato la festa, e la sposa ti ha trovato tra gli invitati.","details":[{"id":"d1","label":"La cassetta della suite","text":"Aperta, vuota, nessun segno di forzatura. Federica ammette di non averla chiusa.","insight":"Cassetta della suite aperta e vuota, senza segni di forzatura. Federica non l'aveva chiusa."},{"id":"d2","label":"La serratura elettronica","text":"Il registro della porta: «23:40 tessera Ospite 2. 00:04 tessera Staff.»","insight":"Registro della porta della suite: 23:40 tessera Ospite 2; 00:04 tessera Staff."},{"id":"d3","label":"La reception","text":"In cassaforte c'è una sola tessera Staff. Il registro: «Tessere Staff: 2. Una consegnata a B. Colaianni, wedding planner. Non restituita.»","insight":"In reception, in cassaforte, c'è una sola tessera Staff. Delle due, una risulta consegnata a B. Colaianni, wedding planner, e non restituita."},{"id":"d4","label":"La lista del personale","text":"Accanto al nome di un cameriere, a penna: «Lomuscio Cristian – precedente per furto (2021). Tenere d'occhio.»","insight":"Sulla lista del personale: Cristian Lomuscio, precedente per furto nel 2021. «Tenere d'occhio.»"},{"id":"d5","label":"Il video dei fuochi","text":"Dal tablet del videomaker: l'aia per tutti e dieci i minuti. Cristian col vassoio in primo piano, sempre. In fondo, il pirotecnico da solo al quadro, dal primo all'ultimo botto.","insight":"Video dei fuochi: Cristian col vassoio in primo piano per tutti i dieci minuti. In fondo, il pirotecnico da solo al quadro, dal primo all'ultimo botto."},{"id":"d6","label":"La scrivania del gestore","text":"Un fascicolo: «Colaianni Wedding – acconti non versati. Terzo sollecito.» Sotto, altri due solleciti di un fiorista e di un catering.","insight":"Sulla scrivania del gestore: terzo sollecito per acconti non versati dalla Colaianni Wedding. Sotto, solleciti di un fiorista e di un catering."},{"id":"d7","label":"Il furgone della planner","text":"Nel cortile, già carico di centrotavola e candelabri da riportare al noleggio. Sul cruscotto un biglietto: «Partenza appena finita la festa».","insight":"Il furgone della planner è già carico di centrotavola e candelabri. Sul cruscotto: «Partenza appena finita la festa»."}],"suspects":[{"id":"cristian","name":"Cristian Lomuscio","role":"Cameriere, 24 anni","look":"Camicia bianca, papillon storto, vassoio sempre in mano.","tell":"Mani ferme, sguardo stanco. Sulla manica sinistra della giacca bianca c'è una macchia umida, come di vino. Quando passa il gestore della masseria gira la testa dall'altra parte.","questions":[{"id":"c1","q":"Dov'era durante i fuochi?","a":"Sull'aia col vassoio del brindisi. Il videomaker mi ha detto di stare fermo nell'inquadratura, e io sono stato fermo.","insight":"Cristian: durante i fuochi era sull'aia col vassoio del brindisi; il videomaker gli ha detto di restare fermo nell'inquadratura."},{"id":"c2","q":"Lei ha un precedente per furto.","req":["d4"],"a":"Avevo diciannove anni. Una bici. Da allora ogni volta che sparisce qualcosa guardano me. Fate pure.","aside":"Non abbassa gli occhi.","insight":"Cristian: il precedente è di quando aveva diciannove anni, una bici."},{"id":"c3","q":"Dopo i fuochi ha visto qualcosa di strano?","a":"A mezzanotte e dieci, più o meno, la planner è tornata sull'aia. Ma non dalla parte dei fuochi: dal vialetto delle suite. Con quella valigetta che non molla mai.","insight":"Cristian: verso le 00:10 la planner è tornata sull'aia dal vialetto delle suite, non dalla parte dei fuochi, con la sua valigetta."},{"id":"c4","q":"Dov'era prima dei fuochi, verso le undici e mezza?","a":"In cucina. Sempre in cucina. Chieda allo chef.","aside":"Si tocca la macchia sulla manica.","insight":"Cristian dice che prima dei fuochi è stato sempre in cucina.","lie":true}]},{"id":"alessia","name":"Alessia Loiacono","role":"Sorella della sposa e testimone","look":"Abito verde smeraldo, capelli raccolti, flûte sempre piena.","tell":"Si tocca il collo sotto l'orecchio, dove c'è una linea rossa sottile. Mette via il telefono ogni volta che qualcuno le passa dietro. Non guarda mai la sorella.","questions":[{"id":"a1","q":"È salita in suite stasera?","a":"Alle undici e quaranta, a prendere lo scialle di Federica. Con la seconda tessera ospite. I gioielli erano nella cassetta aperta.","insight":"Alessia: alle 23:40 è salita in suite con la seconda tessera ospite, a prendere lo scialle di Federica. I gioielli erano nella cassetta aperta."},{"id":"a2","q":"Lei ha provato la collana.","req":["t_alessia"],"a":"(Arrossisce.) Due minuti. Una foto. La nonna l'ha lasciata a lei, non a me, e io volevo vedere come mi stava. L'ho rimessa nella cassetta. Guardi l'ora della foto: 23:42.","insight":"Alessia ammette di aver provato la collana in suite e dice di averla rimessa nella cassetta. Mostra una foto delle 23:42.","lie":true},{"id":"a3","q":"Chi può entrare in suite?","a":"Federica, io con la seconda tessera, e la planner. Quella ha la tessera per tutte le stanze.","insight":"Alessia: in suite possono entrare Federica, lei con la seconda tessera ospite, e la planner con la tessera staff."},{"id":"a4","q":"Prima dei fuochi ha visto qualcuno dove non doveva essere?","a":"Il cameriere. Alle undici e mezza, scendendo dalla suite, l'ho visto uscire dalla cantina con qualcosa sotto la giacca. Si è guardato intorno.","insight":"Alessia: alle 23:30 ha visto Cristian uscire dalla cantina con qualcosa sotto la giacca."}]},{"id":"beatrice","name":"Beatrice Colaianni","role":"Wedding planner, 40 anni","look":"Auricolare all'orecchio, tailleur nero, scarpe basse. Una valigetta rigida con scritto «Kit sposa».","tell":"Sorriso professionale che non si spegne mai. Tiene la valigetta «Kit sposa» stretta tra le caviglie. Quando si alza la solleva con due mani e il braccio si tende.","questions":[{"id":"b1","q":"Dov'era durante i fuochi?","a":"Col pirotecnico, al quadro. È il momento più delicato della serata. Non l'ho lasciato un secondo.","insight":"Beatrice dice di essere rimasta al quadro col pirotecnico per tutti i fuochi."},{"id":"b2","q":"Lei ha una tessera della suite?","a":"La tessera staff, sì. Ma l'ho lasciata alla reception prima dei fuochi. Io in suite senza la sposa non entro.","insight":"Beatrice dice di aver lasciato la tessera staff alla reception prima dei fuochi, e di non entrare mai in suite senza la sposa."},{"id":"b3","q":"Il gestore aspetta i suoi acconti da mesi.","req":["d6"],"a":"Periodo difficile. Le spose pagano tardi, io pago tardi. Funziona così, in questo lavoro.","aside":"Mentre parla, sposta il piede contro la valigetta.","insight":"Beatrice: con i fornitori paga in ritardo perché le spose pagano in ritardo."},{"id":"b4","q":"Quella valigetta non la molla un secondo.","req":["t_beatrice"],"a":"È il kit d'emergenza della sposa. Spille, ago e filo, cerotti. Se salta un bottone, chi la salva, la sposa?","aside":"Federica balla da due ore. La valigetta non si è mai aperta.","insight":"Beatrice dice che nella valigetta c'è il kit d'emergenza della sposa: spille, ago e filo, cerotti."}]}],"bluff":{"text":"Annunci che i carabinieri stanno arrivando e che perquisiranno tutte le borse e tutti i veicoli prima che qualcuno esca.","reactions":{"cristian":"Posa il vassoio e allarga le braccia. «Cominciate da me, tanto.» Poi guarda verso il bagno del personale.","alessia":"«Anche i telefoni? Guardano anche le foto?» Poi arrossisce.","beatrice":"Si offre di organizzare lei le uscite, «per non rovinare la festa agli sposi», e chiede se i furgoni dei fornitori possono partire prima: «Hanno orari col noleggio.»"},"insight":"Al bluff della perquisizione: Cristian ha guardato il bagno del personale; Alessia ha chiesto dei telefoni; Beatrice ha chiesto di far partire prima i furgoni."},"culprit":"beatrice","key":["x2","d2","x1"],"motive":{"options":["Tenersi la collana che la nonna aveva lasciato all'altra sorella","Rivendere i gioielli, come col furto di qualche anno fa","Coprire le bottiglie sparite dalla cantina","Pagare i fornitori che la sollecitano da mesi"],"correct":3},"solution":"Alle 23:42 la collana era ancora in suite: c'è la foto di Alessia, che l'ha provata di nascosto e rimessa a posto. Alle 00:04, a fuochi in corso, la porta si apre con una tessera staff. Quella della reception era in cassaforte; l'altra era di Beatrice, che giura di averla restituita e invece non l'ha mai fatto. Il video mostra il pirotecnico da solo per tutti i fuochi, e alle 00:10 Cristian la vede tornare dal vialetto delle suite. Beatrice, piena di debiti, ha messo gli zaffiri nella valigetta del kit sposa e contava di portarli via col furgone. Cristian, col suo precedente, era il colpevole perfetto, ma per dieci minuti non è mai uscito dall'inquadratura. Alessia aveva solo provato la collana di nascosto, e Cristian aveva rubato due bottiglie dalla cantina prima dei fuochi.","contradictions":[{"id":"x1","a":"b1","b":"d5","who":"beatrice","reply":"Mi sono allontanata un attimo, a prendere le stelline per gli ospiti. Due minuti.","aside":"Le stelline le ha distribuite lei alle undici, prima della torta.","insight":"Beatrice ammette di essersi allontanata dal pirotecnico durante i fuochi. Dice: due minuti, per prendere le stelline.","lie":true},{"id":"x2","a":"b2","b":"d3","who":"beatrice","reply":"Me la sarò dimenticata in tasca. Ma in suite non ci sono entrata.","aside":"Il registro della serratura segna la tessera Staff alle 00:04.","insight":"Beatrice ammette che la tessera staff non è mai tornata alla reception: «me la sarò dimenticata in tasca».","lie":true},{"id":"x3","a":"c4","b":"a4","who":"cristian","reply":"Due bottiglie di Franciacorta. Sono nel bagno del personale, dietro lo sciacquone. Erano avanzate, lo giuro. Lo so, lo so: col mio precedente.","insight":"Cristian ammette di aver preso due bottiglie di Franciacorta dalla cantina alle 23:30 e di averle nascoste nel bagno del personale.","lie":true}]}];
